var e=JSON.parse(`[{"id":"aut.penal_tj.coacao_fraude_processual.0001","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":2,"enunciado":"Réu em processo por roubo, Diego procura a principal testemunha de acusação e ameaça matá-la caso ela compareça à audiência, para favorecer o próprio interesse. Nos termos do Código Penal, Diego comete","alternativas":{"A":"ameaça, apenas, punida com detenção de um a seis meses, ou multa.","B":"coação no curso do processo, punida com reclusão de um a quatro anos, e multa, além da pena correspondente à violência.","C":"corrupção de testemunha, punida com reclusão de três a quatro anos, e multa.","D":"fraude processual, punida com detenção de três meses a dois anos, e multa.","E":"exercício arbitrário das próprias razões, punido com detenção de quinze dias a um mês, ou multa."},"gabarito":"B","explicacao":"O art. 344 pune quem usa de violência ou grave ameaça, com o fim de favorecer interesse próprio ou alheio, contra autoridade, parte, ou qualquer outra pessoa que funciona ou é chamada a intervir em processo judicial, policial ou administrativo, ou em juízo arbitral, com reclusão de um a quatro anos, e multa, além da pena correspondente à violência.","explicacoes":{"A":"A grave ameaça contra quem é chamado a intervir em processo, para favorecer interesse, tem tipo próprio no art. 344.","B":"Correta: é a coação no curso do processo.","C":"Diego não ofereceu vantagem à testemunha; ameaçou-a.","D":"Não houve inovação artificiosa do estado de lugar, coisa ou pessoa.","E":"Diego não buscava satisfazer pretensão pelas próprias mãos."},"fonte":"Código Penal, art. 344, caput","mastigado":"A resposta é a letra B. Diego ameaçou de morte a testemunha para que ela não fosse à audiência e ele se desse bem no processo. Isso é coação no curso do processo, com pena de um a quatro anos de reclusão, e multa.","teSitua":{"termos":[{"termo":"testemunha de acusação","significado":"pessoa indicada pela acusação para contar o que sabe sobre o crime."},{"termo":"coação no curso do processo","significado":"crime de usar violência ou grave ameaça contra quem participa de um processo, para favorecer interesse."},{"termo":"grave ameaça","significado":"promessa séria de causar mal grave, capaz de intimidar."}],"exemplo":"Diego responde por roubo e sabe que a vendedora Lúcia o reconheceu. Ele a espera na saída do trabalho e diz que ela \\"não chega viva\\" se for à audiência. Lúcia avisa o juiz. Diego passa a responder também por coação no curso do processo."}},{"id":"aut.penal_tj.coacao_fraude_processual.0002","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"certo_errado","dificuldade":2,"enunciado":"O crime de coação no curso do processo pode ocorrer também em processo administrativo e em juízo arbitral, e não apenas em processo judicial ou policial.","gabarito":"C","explicacao":"O art. 344 menciona expressamente processo judicial, policial ou administrativo, ou juízo arbitral.","fonte":"Código Penal, art. 344, caput","mastigado":"Certo. A lei protege quem participa de vários tipos de procedimento: processo na Justiça, inquérito na polícia, processo administrativo e até arbitragem. Ameaçar alguém em qualquer deles para favorecer interesse é coação no curso do processo.","teSitua":{"termos":[{"termo":"processo administrativo","significado":"procedimento dentro de um órgão público para decidir uma questão ou apurar uma falta."},{"termo":"juízo arbitral","significado":"forma de resolver conflitos fora do Judiciário, por um árbitro escolhido pelas partes."}],"exemplo":"Em um processo disciplinar contra um servidor, o colega Rubens, chamado a depor, é ameaçado pelo acusado: \\"se falar, você vai se arrepender\\". Mesmo sendo um processo administrativo, o acusado comete coação no curso do processo."}},{"id":"aut.penal_tj.coacao_fraude_processual.0003","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do Código Penal, se a coação no curso do processo ocorre em processo que envolve crime contra a dignidade sexual, a pena","alternativas":{"A":"é aplicada em dobro.","B":"é aumentada de um sexto.","C":"é aumentada de um terço.","D":"é aumentada de metade.","E":"aumenta-se de um terço até a metade."},"gabarito":"E","explicacao":"O parágrafo único do art. 344 prevê que a pena aumenta-se de 1/3 (um terço) até a metade se o processo envolver crime contra a dignidade sexual.","explicacoes":{"A":"Não há previsão de pena em dobro no art. 344.","B":"O aumento não é de um sexto.","C":"O aumento é variável, de um terço até a metade, e não fixo em um terço.","D":"O aumento é variável, de um terço até a metade, e não fixo na metade.","E":"Correta: é a causa de aumento do parágrafo único do art. 344."},"fonte":"Código Penal, art. 344, parágrafo único","mastigado":"A resposta é a letra E. Quando o processo trata de crime sexual, a vítima e as testemunhas costumam estar mais frágeis. Por isso, quem as ameaça recebe pena maior: o aumento vai de um terço até a metade.","teSitua":{"termos":[{"termo":"dignidade sexual","significado":"o direito de cada pessoa decidir livremente sobre sua vida sexual, protegido pela lei penal."},{"termo":"coação no curso do processo","significado":"crime de usar violência ou grave ameaça contra quem participa de um processo, para favorecer interesse."}],"exemplo":"No processo por estupro contra Vicente, a vítima é procurada por um amigo dele, que ameaça espalhar fotos dela se não retirar o que disse. Como o processo envolve crime contra a dignidade sexual, a pena da coação aumenta de um terço até a metade."}},{"id":"aut.penal_tj.coacao_fraude_processual.0004","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"certo_errado","dificuldade":3,"enunciado":"No crime de coação no curso do processo, somente a testemunha pode ser vítima da violência ou grave ameaça.","gabarito":"E","explicacao":"O art. 344 protege a autoridade, a parte ou qualquer outra pessoa que funciona ou é chamada a intervir em processo judicial, policial ou administrativo, ou em juízo arbitral. Juiz, promotor, perito, escrevente, partes e testemunhas podem ser vítimas.","fonte":"Código Penal, art. 344, caput","mastigado":"Errado. A lei protege muito mais gente: a autoridade, como o juiz ou o delegado, as partes e qualquer pessoa que trabalhe ou seja chamada no processo, como o perito ou o escrevente.","teSitua":{"termos":[{"termo":"grave ameaça","significado":"promessa séria de causar mal grave, capaz de intimidar."},{"termo":"somente a testemunha","significado":"apenas a pessoa chamada para contar o que sabe."}],"exemplo":"Inconformado com a demora, o réu Gaspar ameaça a escrevente Rosa, responsável pelo processo, dizendo que \\"algo vai acontecer\\" se ela não fizer o processo andar como ele quer. Rosa não é testemunha, mas funciona no processo. Gaspar comete coação no curso do processo."}},{"id":"aut.penal_tj.coacao_fraude_processual.0005","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":2,"enunciado":"Credor de uma dívida vencida e não paga, Hélio entra na casa do devedor sem violência, enquanto este viaja, e leva um televisor para se pagar. Nos termos do Código Penal, Hélio comete","alternativas":{"A":"exercício arbitrário das próprias razões, punido com detenção de quinze dias a um mês, ou multa.","B":"furto, porque a pretensão de receber a dívida não autoriza levar o bem.","C":"coação no curso do processo, punida com reclusão de um a quatro anos, e multa.","D":"fraude processual, punida com detenção de três meses a dois anos, e multa.","E":"subtração de coisa própria em poder de terceiro, punida com detenção de seis meses a dois anos, e multa."},"gabarito":"A","explicacao":"O art. 345 pune quem faz justiça pelas próprias mãos, para satisfazer pretensão, embora legítima, salvo quando a lei o permite, com detenção de quinze dias a um mês, ou multa, além da pena correspondente à violência.","explicacoes":{"A":"Correta: Hélio fez justiça pelas próprias mãos para satisfazer pretensão.","B":"Como Hélio agiu para satisfazer pretensão que entende ter, a conduta se amolda ao art. 345, e não ao furto.","C":"Não houve violência ou grave ameaça contra quem atua em processo.","D":"Não houve inovação artificiosa em processo.","E":"O televisor não era de Hélio; o art. 346 trata de coisa própria em poder de terceiro."},"fonte":"Código Penal, art. 345, caput","mastigado":"A resposta é a letra A. Hélio tinha mesmo dinheiro a receber, mas em vez de procurar a Justiça, resolveu se pagar sozinho, pegando a TV. Isso é exercício arbitrário das próprias razões: fazer justiça com as próprias mãos.","teSitua":{"termos":[{"termo":"dívida vencida","significado":"dívida cujo prazo de pagamento já passou."},{"termo":"exercício arbitrário das próprias razões","significado":"crime de fazer justiça com as próprias mãos, sem recorrer à Justiça."},{"termo":"pretensão","significado":"aquilo que a pessoa acha que tem direito de exigir."}],"exemplo":"Gílson deve R$ 2.000,00 a Hélio há meses. Cansado de esperar, Hélio entra na casa de Gílson, que está viajando, e leva o televisor da sala \\"como pagamento\\". Hélio responde por exercício arbitrário das próprias razões."}},{"id":"aut.penal_tj.coacao_fraude_processual.0006","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"certo_errado","dificuldade":3,"enunciado":"No exercício arbitrário das próprias razões, somente se procede mediante queixa quando houver emprego de violência.","gabarito":"E","explicacao":"O parágrafo único do art. 345 do CP dispõe o contrário: se não há emprego de violência, somente se procede mediante queixa. Havendo violência, a ação penal é pública, e o agente responde também pela pena correspondente à violência.","fonte":"Código Penal, art. 345, parágrafo único","mastigado":"Errado. A regra é ao contrário. Quando a pessoa faz justiça com as próprias mãos sem violência, só a vítima pode iniciar o processo, por queixa. Se houve violência, o Ministério Público pode agir.","teSitua":{"termos":[{"termo":"emprego de violência","significado":"uso de força física contra alguém."},{"termo":"mediante queixa","significado":"só por iniciativa da vítima, que apresenta a acusação por meio de advogado."}],"exemplo":"Ari leva sem violência a bicicleta do inquilino Beto para compensar aluguéis atrasados. Se Beto quiser ver Ari processado por exercício arbitrário das próprias razões, terá de oferecer queixa, porque não houve violência."}},{"id":"aut.penal_tj.coacao_fraude_processual.0007","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":3,"enunciado":"Quanto à ação penal no crime de exercício arbitrário das próprias razões, é correto afirmar que","alternativas":{"A":"é sempre pública incondicionada.","B":"é sempre privada, com ou sem violência.","C":"é pública condicionada à representação, se houver violência.","D":"somente se procede mediante queixa se não houver emprego de violência.","E":"depende de requisição do Ministro da Justiça."},"gabarito":"D","explicacao":"O art. 345, parágrafo único, só exige queixa quando não há emprego de violência. Havendo violência, não incide essa regra, e a ação é pública.","explicacoes":{"A":"Sem violência, a ação depende de queixa.","B":"A exigência de queixa só vale quando não há violência.","C":"A lei não prevê representação para esse crime.","D":"Correta: é a regra do parágrafo único do art. 345.","E":"Não há previsão de requisição do Ministro da Justiça."},"fonte":"Código Penal, art. 345, parágrafo único","mastigado":"A resposta é a letra D. Se a pessoa fez justiça com as próprias mãos sem violência, só a vítima pode dar início ao processo, com a queixa. Se usou violência, o caso fica com o Ministério Público.","teSitua":{"termos":[{"termo":"ação penal","significado":"o processo criminal e quem tem o poder de iniciá-lo."},{"termo":"pública incondicionada","significado":"ação que o Ministério Público inicia sem precisar da vontade da vítima."},{"termo":"representação","significado":"autorização da vítima para que o Ministério Público possa agir."},{"termo":"requisição do Ministro da Justiça","significado":"pedido formal do ministro, exigido em alguns crimes para que haja processo."}],"exemplo":"Paulo toma à força, com empurrões, o celular do devedor Ciro para se pagar. Como houve violência, o Ministério Público pode processá-lo sem queixa de Ciro. Se Paulo tivesse levado o celular sem violência, só Ciro poderia iniciar a ação."}},{"id":"aut.penal_tj.coacao_fraude_processual.0008","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"certo_errado","dificuldade":3,"enunciado":"Só há exercício arbitrário das próprias razões se a pretensão que o agente busca satisfazer pelas próprias mãos for ilegítima.","gabarito":"E","explicacao":"O art. 345 pune quem faz justiça pelas próprias mãos, para satisfazer pretensão, \\"embora legítima\\". A legitimidade da pretensão não afasta o crime; ao contrário, é o caso típico.","fonte":"Código Penal, art. 345, caput","mastigado":"Errado. A lei pune justamente quem tem razão, mas resolve o problema sozinho em vez de procurar a Justiça. Mesmo que o direito exista, fazer justiça com as próprias mãos é crime, salvo quando a lei permite.","teSitua":{"termos":[{"termo":"pretensão","significado":"aquilo que a pessoa acha que tem direito de exigir."},{"termo":"ilegítima","significado":"sem amparo na lei, injusta."}],"exemplo":"Marta tem mesmo R$ 800,00 a receber da cliente Joice, que confessa a dívida. Em vez de cobrar na Justiça, Marta pega a bolsa de Joice no salão e diz que só devolve quando receber. Mesmo com o direito ao dinheiro, Marta comete o crime."}},{"id":"aut.penal_tj.coacao_fraude_processual.0009","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":3,"enunciado":"Na execução movida contra Rogério, seu carro foi penhorado e entregue, por determinação judicial, à guarda de um depositário. Rogério vai ao pátio do depositário e leva o carro de volta para casa. Nos termos do Código Penal, Rogério comete","alternativas":{"A":"furto, porque o carro estava em poder de terceiro.","B":"exercício arbitrário das próprias razões, punido com detenção de quinze dias a um mês, ou multa.","C":"subtração de coisa própria em poder de terceiro, punida com detenção de seis meses a dois anos, e multa.","D":"fraude processual, punida com detenção de três meses a dois anos, e multa.","E":"conduta atípica, porque o carro é dele."},"gabarito":"C","explicacao":"O art. 346 pune quem tira, suprime, destrói ou danifica coisa própria, que se acha em poder de terceiro por determinação judicial ou convenção, com detenção de seis meses a dois anos, e multa.","explicacoes":{"A":"Não há furto de coisa própria; há tipo específico no art. 346.","B":"Rogério não buscava satisfazer pretensão contra outrem; tirou coisa própria em poder de terceiro.","C":"Correta: é o crime do art. 346.","D":"Não houve inovação artificiosa para induzir em erro juiz ou perito.","E":"A lei pune tirar coisa própria que se acha em poder de terceiro por determinação judicial."},"fonte":"Código Penal, art. 346","mastigado":"A resposta é a letra C. O carro é de Rogério, mas estava guardado com outra pessoa por ordem do juiz. Tirar de lá a própria coisa é um crime específico, com pena de seis meses a dois anos de detenção, e multa.","teSitua":{"termos":[{"termo":"penhorado","significado":"separado por ordem do juiz para garantir o pagamento de uma dívida."},{"termo":"depositário","significado":"pessoa encarregada de guardar o bem até o fim do processo."},{"termo":"conduta atípica","significado":"comportamento que não se encaixa em nenhum crime previsto na lei."}],"exemplo":"O carro de Rogério foi penhorado e levado ao pátio de uma empresa depositária. Uma noite, Rogério usa a chave reserva, tira o carro do pátio e o esconde na garagem da mãe. Ele responde pelo crime do art. 346, mesmo sendo o dono."}},{"id":"aut.penal_tj.coacao_fraude_processual.0010","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"certo_errado","dificuldade":3,"enunciado":"O crime do art. 346 do Código Penal alcança também a coisa própria que se acha em poder de terceiro por convenção, e não apenas por determinação judicial.","gabarito":"C","explicacao":"O art. 346 pune quem tira, suprime, destrói ou danifica coisa própria, que se acha em poder de terceiro por determinação judicial ou convenção.","fonte":"Código Penal, art. 346","mastigado":"Certo. A lei protege a coisa que está com outra pessoa por ordem do juiz e também a que está com ela por um acordo entre as partes. Em ambos os casos, o dono não pode simplesmente tomá-la de volta.","teSitua":{"termos":[{"termo":"coisa própria","significado":"bem que pertence ao próprio agente."},{"termo":"convenção","significado":"acordo, contrato entre as partes."}],"exemplo":"Para garantir um empréstimo, Celso entregou por contrato seu trator ao credor Dalton, que ficaria com ele até o pagamento. Antes de pagar, Celso leva o trator de volta escondido. Ele comete o crime do art. 346, porque o bem estava com Dalton por convenção."}},{"id":"aut.penal_tj.coacao_fraude_processual.0011","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":2,"enunciado":"Em ação de indenização por vazamento, antes da vistoria do perito judicial, o réu pinta a parede manchada do apartamento vizinho com o fim de fazer crer que não houve dano. Nos termos do Código Penal, a conduta configura","alternativas":{"A":"fraude processual, punida com detenção de três meses a dois anos, e multa.","B":"fraude processual, com a pena aplicada em dobro.","C":"falsidade ideológica, punida com reclusão de um a três anos, e multa.","D":"coação no curso do processo, punida com reclusão de um a quatro anos, e multa.","E":"supressão de documento, punida com reclusão de um a cinco anos, e multa."},"gabarito":"A","explicacao":"O art. 347 pune quem inova artificiosamente, na pendência de processo civil ou administrativo, o estado de lugar, de coisa ou de pessoa, com o fim de induzir a erro o juiz ou o perito, com detenção de três meses a dois anos, e multa. A pena só é aplicada em dobro se a inovação se destina a produzir efeito em processo penal.","explicacoes":{"A":"Correta: alterar o estado do lugar em processo civil para enganar o perito é fraude processual.","B":"A pena em dobro é para inovação destinada a produzir efeito em processo penal.","C":"Não houve declaração falsa em documento.","D":"Não houve violência ou grave ameaça.","E":"Não houve destruição ou ocultação de documento."},"fonte":"Código Penal, art. 347, caput e parágrafo único","mastigado":"A resposta é a letra A. O réu mexeu na parede para que o perito não visse o estrago e o juiz se enganasse. Isso é fraude processual. Como o processo é civil, a pena é a simples: três meses a dois anos de detenção, e multa.","teSitua":{"termos":[{"termo":"vistoria","significado":"exame do local feito pelo perito para verificar o que aconteceu."},{"termo":"fraude processual","significado":"crime de alterar lugar, coisa ou pessoa para enganar o juiz ou o perito."},{"termo":"ação de indenização","significado":"processo em que alguém pede que o outro pague pelo prejuízo que causou."}],"exemplo":"Na ação em que Sueli pede indenização por infiltração, o vizinho Moacir pinta às pressas a parede manchada do apartamento dela, aproveitando uma visita, um dia antes da perícia. O perito desconfia da tinta fresca. Moacir responde por fraude processual."}},{"id":"aut.penal_tj.coacao_fraude_processual.0012","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":3,"enunciado":"Depois de atropelar um pedestre, um motorista lava o sangue do para-choque e muda o carro de posição antes da chegada da perícia, para fazer crer que a vítima atravessou fora da faixa. Ainda não há inquérito nem processo. Nos termos do Código Penal, a fraude processual","alternativas":{"A":"não se configura, porque não havia processo em curso.","B":"configura-se com a pena simples, de três meses a dois anos, e multa.","C":"configura-se com as penas aplicadas em dobro, pois a inovação se destina a produzir efeito em processo penal, ainda que não iniciado.","D":"configura-se com a pena aumentada de um terço.","E":"é absorvida pelo crime de trânsito, sem punição autônoma."},"gabarito":"C","explicacao":"O parágrafo único do art. 347 determina que, se a inovação se destina a produzir efeito em processo penal, ainda que não iniciado, as penas aplicam-se em dobro.","explicacoes":{"A":"Para o processo penal, a lei dispensa que ele já tenha sido iniciado.","B":"Por se destinar a processo penal, as penas são aplicadas em dobro.","C":"Correta: é a forma do parágrafo único do art. 347.","D":"A lei prevê aplicação em dobro, e não aumento de um terço.","E":"A fraude processual tem previsão autônoma no art. 347, parágrafo único."},"fonte":"Código Penal, art. 347, parágrafo único","mastigado":"A resposta é a letra C. O motorista mexeu na cena para enganar a perícia de um futuro processo criminal. Mesmo sem processo aberto ainda, isso é fraude processual, e a pena dobra por envolver a área penal.","teSitua":{"termos":[{"termo":"perícia","significado":"exame feito por especialista para esclarecer como os fatos ocorreram."},{"termo":"inovação","significado":"mudança, alteração do estado de algo."},{"termo":"ainda que não iniciado","significado":"mesmo antes de o processo começar."}],"exemplo":"Rafael atropela um ciclista à noite. Antes de a polícia chegar, lava o sangue do carro e o empurra para longe da faixa. A perícia descobre a manobra. Rafael responde por fraude processual com as penas em dobro, porque a mudança visava o processo penal."}},{"id":"aut.penal_tj.coacao_fraude_processual.0013","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"certo_errado","dificuldade":2,"enunciado":"Na fraude processual, se a inovação se destina a produzir efeito em processo penal, as penas aplicam-se em dobro, ainda que o processo não tenha sido iniciado.","gabarito":"C","explicacao":"É a regra do parágrafo único do art. 347 do Código Penal: \\"Se a inovação se destina a produzir efeito em processo penal, ainda que não iniciado, as penas aplicam-se em dobro\\".","fonte":"Código Penal, art. 347, parágrafo único","mastigado":"Certo. Alterar a cena para enganar um futuro processo criminal é mais grave. Por isso, a pena da fraude processual dobra, e não é preciso esperar que o processo já tenha começado.","teSitua":{"termos":[{"termo":"inovação","significado":"mudança, alteração do estado de algo."},{"termo":"processo penal","significado":"processo que apura um crime e pode levar à condenação do réu."}],"exemplo":"Logo após uma briga com morte num bar, o dono do estabelecimento esconde a faca e limpa o chão antes da chegada da polícia, para proteger um cliente. Ainda não há processo, mas a fraude processual se configura com as penas em dobro."}},{"id":"aut.penal_tj.coacao_fraude_processual.0014","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":3,"enunciado":"Sobre a fraude processual (art. 347 do Código Penal), assinale a alternativa correta.","alternativas":{"A":"Exige que o agente seja parte no processo.","B":"Só se configura se o juiz efetivamente for induzido a erro.","C":"Consiste em usar de violência contra o perito para alterar o laudo.","D":"Pune a alteração de documento público para induzir a erro o juiz.","E":"Consiste em inovar artificiosamente o estado de lugar, de coisa ou de pessoa, com o fim de induzir a erro o juiz ou o perito."},"gabarito":"E","explicacao":"O art. 347 descreve a conduta de inovar artificiosamente, na pendência de processo civil ou administrativo, o estado de lugar, de coisa ou de pessoa, com o fim de induzir a erro o juiz ou o perito. Basta a finalidade de induzir a erro.","explicacoes":{"A":"O tipo não exige que o agente seja parte.","B":"A lei exige o fim de induzir a erro, não o resultado.","C":"Violência contra quem atua no processo é coação no curso do processo (art. 344).","D":"Alteração de documento público é falsificação de documento público (art. 297).","E":"Correta: é a descrição do art. 347."},"fonte":"Código Penal, art. 347, caput","mastigado":"A resposta é a letra E. A fraude processual é mexer, de forma enganosa, no lugar, numa coisa ou até numa pessoa, para que o juiz ou o perito se enganem. Não é preciso que o engano dê certo.","teSitua":{"termos":[{"termo":"inovar artificiosamente","significado":"mudar algo de forma enganosa, com truque."},{"termo":"estado de lugar, de coisa ou de pessoa","significado":"a situação em que se encontram o local, o objeto ou o corpo de alguém."},{"termo":"induzir a erro","significado":"levar alguém a acreditar em algo falso."}],"exemplo":"Num processo trabalhista por acidente, o dono da fábrica instala às pressas uma proteção na máquina antes da perícia, para parecer que ela sempre existiu. O perito percebe os parafusos novos. Mesmo sem enganá-lo, o dono cometeu fraude processual."}},{"id":"aut.penal_tj.coacao_fraude_processual.0015","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":3,"enunciado":"Assinale a alternativa que associa corretamente o crime à sua pena, nos termos do Código Penal.","alternativas":{"A":"Coação no curso do processo: detenção, de três meses a dois anos, e multa.","B":"Exercício arbitrário das próprias razões: detenção, de quinze dias a um mês, ou multa, além da pena correspondente à violência.","C":"Subtração de coisa própria em poder de terceiro: reclusão, de um a quatro anos, e multa.","D":"Fraude processual: reclusão, de um a quatro anos, e multa.","E":"Coação no curso do processo: detenção, de seis meses a dois anos, e multa."},"gabarito":"B","explicacao":"Art. 344: reclusão, de um a quatro anos, e multa, além da pena da violência. Art. 345: detenção, de quinze dias a um mês, ou multa, além da pena da violência. Art. 346: detenção, de seis meses a dois anos, e multa. Art. 347: detenção, de três meses a dois anos, e multa.","explicacoes":{"A":"A coação tem pena de reclusão de um a quatro anos, e multa.","B":"Correta: é a pena do art. 345.","C":"O art. 346 prevê detenção de seis meses a dois anos, e multa.","D":"A fraude processual prevê detenção de três meses a dois anos, e multa.","E":"Seis meses a dois anos, e multa, é a pena do art. 346."},"fonte":"Código Penal, arts. 344 a 347","mastigado":"A resposta é a letra B. Fazer justiça com as próprias mãos tem pena bem leve, quinze dias a um mês ou multa, mas a pessoa responde também pela violência que usar. Dos quatro crimes do tema, só a coação tem pena de reclusão.","teSitua":{"termos":[{"termo":"exercício arbitrário das próprias razões","significado":"crime de fazer justiça com as próprias mãos, sem recorrer à Justiça."},{"termo":"coisa própria em poder de terceiro","significado":"bem do agente que está guardado com outra pessoa."}],"exemplo":"Na revisão, Natália monta um quadro: coação no processo, reclusão de um a quatro anos; justiça pelas próprias mãos, quinze dias a um mês ou multa; tirar coisa própria do depositário, seis meses a dois anos; fraude processual, três meses a dois anos."}},{"id":"aut.penal_tj.coacao_fraude_processual.0016","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":3,"enunciado":"Um amigo do réu, sem que este saiba, ameaça gravemente o perito nomeado em ação penal, exigindo que o laudo seja favorável ao acusado. Nos termos do Código Penal, o amigo","alternativas":{"A":"não comete crime, pois não é parte no processo.","B":"comete corrupção de perito, punida com reclusão de três a quatro anos, e multa.","C":"comete fraude processual, com as penas em dobro.","D":"comete coação no curso do processo, pois usou grave ameaça para favorecer interesse alheio contra pessoa que funciona no processo.","E":"comete exercício arbitrário das próprias razões."},"gabarito":"D","explicacao":"O art. 344 pune quem usa de violência ou grave ameaça, com o fim de favorecer interesse próprio ou alheio, contra autoridade, parte, ou qualquer outra pessoa que funciona ou é chamada a intervir em processo judicial. O perito funciona no processo, e o interesse favorecido pode ser alheio.","explicacoes":{"A":"Qualquer pessoa pode praticar a coação, e o interesse favorecido pode ser alheio.","B":"Não houve oferecimento de vantagem; houve grave ameaça.","C":"Não houve inovação do estado de lugar, coisa ou pessoa.","D":"Correta: é coação no curso do processo.","E":"O agente não buscava satisfazer pretensão própria pelas próprias mãos."},"fonte":"Código Penal, art. 344, caput","mastigado":"A resposta é a letra D. Não é preciso ser o réu para cometer o crime. O amigo ameaçou o perito para ajudar o réu, e a lei pune quem ameaça qualquer pessoa que trabalha no processo para favorecer interesse próprio ou de outro.","teSitua":{"termos":[{"termo":"perito nomeado","significado":"especialista escolhido pelo juiz para fazer um exame no processo."},{"termo":"ameaça gravemente","significado":"promete causar um mal sério para intimidar alguém."},{"termo":"laudo","significado":"relatório escrito do perito com o resultado do exame."}],"exemplo":"Sem avisar o primo, réu num processo por homicídio, Elias liga para o perito Dr. Breno e diz que sabe onde os filhos dele estudam e que \\"é bom o laudo sair favorável\\". Elias responde por coação no curso do processo."}},{"id":"aut.penal_tj.coacao_fraude_processual.0017","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":3,"enunciado":"O art. 345 do Código Penal pune quem faz justiça pelas próprias mãos para satisfazer pretensão, embora legítima. O próprio artigo afasta o crime","alternativas":{"A":"quando a lei o permite.","B":"sempre que a pretensão for legítima.","C":"quando o valor envolvido for pequeno.","D":"quando a vítima não oferecer queixa no prazo de trinta dias.","E":"quando o agente devolver a coisa antes da sentença."},"gabarito":"A","explicacao":"O art. 345 traz a ressalva \\"salvo quando a lei o permite\\": há casos em que o ordenamento autoriza a autotutela, e nesses casos não há crime.","explicacoes":{"A":"Correta: é a ressalva expressa do art. 345.","B":"A pretensão legítima não afasta o crime; o tipo diz \\"embora legítima\\".","C":"O valor envolvido não é critério do tipo.","D":"A queixa é condição para processar, quando não há violência, mas o artigo não fixa esse prazo como causa que afasta o crime.","E":"A devolução da coisa não está prevista como causa de exclusão do crime no art. 345."},"fonte":"Código Penal, art. 345, caput","mastigado":"A resposta é a letra A. Em regra, quem tem um direito deve procurar a Justiça. Mas há situações em que a própria lei deixa a pessoa agir sozinha. Nesses casos, fazer justiça com as próprias mãos não é crime.","teSitua":{"termos":[{"termo":"justiça pelas próprias mãos","significado":"resolver um conflito sozinho, sem recorrer ao Judiciário."},{"termo":"pretensão","significado":"aquilo que a pessoa acha que tem direito de exigir."},{"termo":"queixa","significado":"acusação apresentada pela própria vítima, por meio de advogado, para iniciar o processo."}],"exemplo":"Alguém invade o terreno de Marisa e começa a cercá-lo. Marisa, logo em seguida, retira a cerca recém-colocada, sem excessos. A lei civil permite que o possuidor reaja logo à invasão, e por isso Marisa não comete exercício arbitrário das próprias razões."}},{"id":"aut.penal_tj.coacao_fraude_processual.0018","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":4,"enunciado":"O dono de uma moto, que a deixou por contrato como garantia com um credor, a retira escondido do pátio do credor antes de pagar a dívida. Em relação aos crimes contra a administração da justiça, é correto afirmar que","alternativas":{"A":"há exercício arbitrário das próprias razões, porque o dono quis satisfazer pretensão.","B":"há furto de coisa comum.","C":"há o crime do art. 346, porque tirou coisa própria que se achava em poder de terceiro por convenção.","D":"não há crime, porque a moto pertence ao agente.","E":"há fraude processual, porque não havia processo em curso."},"gabarito":"C","explicacao":"O art. 346 pune quem tira, suprime, destrói ou danifica coisa própria, que se acha em poder de terceiro por determinação judicial ou convenção, com detenção de seis meses a dois anos, e multa.","explicacoes":{"A":"O agente não buscava satisfazer pretensão contra outrem, mas retirou coisa própria em poder de terceiro.","B":"A moto não é coisa comum; é do agente e está com terceiro por contrato.","C":"Correta: é a figura do art. 346, na modalidade de coisa em poder de terceiro por convenção.","D":"A lei pune justamente o dono que tira a própria coisa.","E":"A fraude processual exige inovação para induzir a erro juiz ou perito."},"fonte":"Código Penal, art. 346","mastigado":"A resposta é a letra C. A moto é dele, mas estava com o credor por causa de um contrato. Tirá-la escondido antes de pagar é o crime de tirar coisa própria em poder de terceiro.","teSitua":{"termos":[{"termo":"garantia","significado":"bem entregue para assegurar que a dívida será paga."},{"termo":"convenção","significado":"acordo, contrato entre as partes."},{"termo":"coisa comum","significado":"bem que pertence a mais de uma pessoa ao mesmo tempo."}],"exemplo":"Joel entrega a moto a Silvano como garantia de um empréstimo, por contrato escrito. Antes de pagar, Joel pula o muro do pátio de Silvano e leva a moto. Joel responde pelo crime do art. 346."}},{"id":"aut.penal_tj.coacao_fraude_processual.0019","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":3,"enunciado":"Para impedir que a vítima mantenha a acusação em processo por estelionato, o réu a agride com socos, causando-lhe lesão corporal. Nos termos do Código Penal, o réu responde por","alternativas":{"A":"lesão corporal apenas, que absorve a coação.","B":"coação no curso do processo apenas, que absorve a lesão.","C":"exercício arbitrário das próprias razões e lesão corporal.","D":"fraude processual com as penas em dobro.","E":"coação no curso do processo, com reclusão de um a quatro anos, e multa, além da pena correspondente à violência."},"gabarito":"E","explicacao":"O art. 344 prevê reclusão, de um a quatro anos, e multa, além da pena correspondente à violência. Assim, o agente responde pela coação e pela lesão corporal, com penas somadas.","explicacoes":{"A":"A coação não é absorvida; a lei soma a pena da violência.","B":"A lesão não é absorvida; a lei manda aplicar também a pena correspondente à violência.","C":"O réu não buscava satisfazer pretensão pelas próprias mãos.","D":"Não houve inovação de lugar, coisa ou pessoa.","E":"Correta: coação no curso do processo, somada à pena da lesão."},"fonte":"Código Penal, art. 344, caput","mastigado":"A resposta é a letra E. O réu bateu na vítima para que ela desistisse de acusá-lo. Isso é coação no curso do processo, e ele responde também pela agressão. As duas penas se somam.","teSitua":{"termos":[{"termo":"lesão corporal","significado":"ferimento ou dano à saúde de uma pessoa."},{"termo":"absorve","significado":"engloba, de modo que só um crime é punido."},{"termo":"mantenha a acusação","significado":"continue confirmando, no processo, o que relatou contra o réu."}],"exemplo":"Lúcio, processado por aplicar um golpe em Dona Maria, vai à casa dela e lhe dá socos, mandando que diga ao juiz que tudo foi um engano. Maria fica com o rosto ferido. Lúcio responde por coação no curso do processo e por lesão corporal."}},{"id":"aut.penal_tj.coacao_fraude_processual.0020","subtopico":"penal_tj.adm_justica.coacao_fraude_processual","tipo":"multipla","dificuldade":4,"enunciado":"Na fraude processual, em sua forma simples (art. 347, caput, do Código Penal), a inovação artificiosa deve ocorrer","alternativas":{"A":"a qualquer tempo, ainda que não exista processo civil ou administrativo.","B":"na pendência de processo civil ou administrativo.","C":"somente durante processo penal já instaurado.","D":"somente após a sentença, para influir no recurso.","E":"somente em inquérito policial."},"gabarito":"B","explicacao":"O caput do art. 347 exige que a inovação ocorra \\"na pendência de processo civil ou administrativo\\". Para o processo penal, o parágrafo único dispensa que ele já tenha sido iniciado e aplica as penas em dobro.","explicacoes":{"A":"Na forma simples, a lei exige processo civil ou administrativo pendente.","B":"Correta: é o momento exigido pelo caput.","C":"O processo penal está no parágrafo único, que nem exige que ele já tenha começado.","D":"A lei não limita a conduta ao período posterior à sentença.","E":"O caput fala em processo civil ou administrativo."},"fonte":"Código Penal, art. 347, caput e parágrafo único","mastigado":"A resposta é a letra B. Na forma simples, a fraude processual exige que já exista um processo civil ou administrativo andando. No caso de processo criminal, a regra muda: vale mesmo antes de ele começar, e a pena dobra.","teSitua":{"termos":[{"termo":"inovação artificiosa","significado":"mudança enganosa feita para iludir alguém."},{"termo":"na pendência","significado":"enquanto o processo está em andamento, ainda não terminado."},{"termo":"inquérito policial","significado":"investigação feita pela polícia para apurar um crime e quem o cometeu."}],"exemplo":"Durante a ação de despejo, o inquilino Norberto troca a fechadura e tira móveis para fingir ao perito que já desocupou o imóvel, antes da vistoria determinada pelo juiz. Como o processo civil estava em andamento, ele comete fraude processual na forma simples."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0001","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"multipla","dificuldade":2,"enunciado":"Joana, para se vingar do vizinho, registra ocorrência afirmando que ele furtou sua bicicleta, sabendo que ele é inocente. Com base nessa notícia, é instaurado inquérito policial contra o vizinho. Nos termos do Código Penal, Joana comete","alternativas":{"A":"comunicação falsa de crime, punida com detenção de um a seis meses, ou multa.","B":"calúnia, apenas, por ter ofendido a honra do vizinho.","C":"denunciação caluniosa, punida com reclusão de dois a oito anos, e multa.","D":"autoacusação falsa, punida com detenção de três meses a dois anos, ou multa.","E":"falso testemunho, punido com reclusão de dois a quatro anos, e multa."},"gabarito":"C","explicacao":"O art. 339 pune quem dá causa à instauração de inquérito policial, de procedimento investigatório criminal, de processo judicial, de processo administrativo disciplinar, de inquérito civil ou de ação de improbidade administrativa contra alguém, imputando-lhe crime, infração ético-disciplinar ou ato ímprobo de que o sabe inocente, com reclusão de dois a oito anos, e multa.","explicacoes":{"A":"Na comunicação falsa (art. 340) não se aponta pessoa determinada; Joana acusou o vizinho.","B":"Como a imputação deu causa à instauração de inquérito, o crime é a denunciação caluniosa, contra a administração da justiça.","C":"Correta: imputar crime a quem sabe inocente, dando causa a inquérito, é denunciação caluniosa.","D":"Joana não se acusou de nada.","E":"Joana não depôs como testemunha em processo."},"fonte":"Código Penal, art. 339, caput","mastigado":"A resposta é a letra C. Joana acusou o vizinho de um furto sabendo que ele não fez nada, e por causa disso a polícia abriu investigação contra ele. Isso é denunciação caluniosa, crime grave, com dois a oito anos de reclusão.","teSitua":{"termos":[{"termo":"registra ocorrência","significado":"comunica um fato à polícia, que o anota em um boletim."},{"termo":"inquérito policial","significado":"investigação feita pela polícia para apurar um crime e quem o cometeu."},{"termo":"denunciação caluniosa","significado":"crime de quem provoca investigação ou processo contra alguém que sabe ser inocente."},{"termo":"calúnia","significado":"crime de acusar falsamente alguém de ter cometido um crime."}],"exemplo":"Depois de uma briga por causa de barulho, Joana vai à delegacia e diz que o vizinho Ivan furtou sua bicicleta, embora saiba que a bicicleta foi vendida por ela mesma. O delegado abre inquérito contra Ivan. Joana responde por denunciação caluniosa."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0002","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"multipla","dificuldade":2,"enunciado":"Para receber o valor do seguro, Mateus comunica à polícia o furto de seu celular, sabendo que o furto não ocorreu, sem apontar nenhum suspeito. A autoridade inicia diligências. Quanto ao crime contra a administração da justiça, Mateus comete","alternativas":{"A":"comunicação falsa de crime ou de contravenção, punida com detenção de um a seis meses, ou multa.","B":"denunciação caluniosa, punida com reclusão de dois a oito anos, e multa.","C":"autoacusação falsa, punida com detenção de três meses a dois anos, ou multa.","D":"fraude processual, punida com detenção de três meses a dois anos, e multa.","E":"falso testemunho, punido com reclusão de dois a quatro anos, e multa."},"gabarito":"A","explicacao":"O art. 340 pune quem provoca a ação de autoridade, comunicando-lhe a ocorrência de crime ou de contravenção que sabe não se ter verificado, com detenção de um a seis meses, ou multa. Não há imputação a pessoa determinada, o que a distingue da denunciação caluniosa.","explicacoes":{"A":"Correta: é a comunicação falsa de crime ou de contravenção.","B":"A denunciação caluniosa exige imputação a pessoa determinada que se sabe inocente.","C":"Mateus não se acusou de crime.","D":"Não houve inovação artificiosa de lugar, coisa ou pessoa em processo.","E":"Mateus não prestou depoimento como testemunha."},"fonte":"Código Penal, arts. 339 e 340","mastigado":"A resposta é a letra A. Mateus inventou um furto que nunca aconteceu e fez a polícia trabalhar à toa, mas não acusou ninguém. Isso é comunicação falsa de crime, com pena de um a seis meses de detenção, ou multa.","teSitua":{"termos":[{"termo":"diligências","significado":"providências da polícia para investigar, como buscas e oitivas."},{"termo":"contravenção","significado":"infração penal mais leve que o crime, com penas menores."},{"termo":"denunciação caluniosa","significado":"crime de quem provoca investigação ou processo contra alguém que sabe ser inocente."}],"exemplo":"Mateus quer trocar de celular e decide enganar a seguradora. Vai à delegacia e diz que foi assaltado no ponto de ônibus por desconhecidos. A polícia procura câmeras e testemunhas. Como não acusou ninguém, Mateus responde por comunicação falsa de crime."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0003","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"certo_errado","dificuldade":2,"enunciado":"Na denunciação caluniosa, a pena é diminuída de metade se a imputação é de prática de contravenção.","gabarito":"C","explicacao":"O art. 339, § 2º, determina que a pena é diminuída de metade se a imputação é de prática de contravenção.","fonte":"Código Penal, art. 339, § 2º","mastigado":"Certo. Se a pessoa acusa falsamente alguém de uma infração mais leve, chamada contravenção, a pena da denunciação caluniosa cai pela metade.","teSitua":{"termos":[{"termo":"imputação","significado":"atribuição a alguém da autoria de um fato."},{"termo":"contravenção","significado":"infração penal mais leve que o crime, com penas menores."}],"exemplo":"Rosana diz ao delegado que o vizinho Abel mantém jogo do bicho em casa, sabendo que é mentira. É instaurado inquérito contra Abel. Como o jogo do bicho é contravenção, a pena de Rosana pela denunciação caluniosa é diminuída de metade."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0004","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"certo_errado","dificuldade":3,"enunciado":"Na denunciação caluniosa, a pena é aumentada de um terço se o agente se serve de anonimato ou de nome suposto.","gabarito":"E","explicacao":"O art. 339, § 1º, prevê aumento de sexta parte, e não de um terço, se o agente se serve de anonimato ou de nome suposto.","fonte":"Código Penal, art. 339, § 1º","mastigado":"Errado. A pena aumenta, mas em um sexto, e não em um terço. O aumento vale para quem faz a acusação falsa sem se identificar ou usando nome inventado.","teSitua":{"termos":[{"termo":"anonimato","significado":"situação de quem não revela quem é."},{"termo":"nome suposto","significado":"nome falso, inventado para esconder quem é."}],"exemplo":"Por carta sem assinatura, Teresa acusa o colega Silas de desviar dinheiro do condomínio, sabendo que ele é honesto. A polícia abre inquérito. Teresa responde por denunciação caluniosa com a pena aumentada de um sexto, por ter usado o anonimato."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0005","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"multipla","dificuldade":3,"enunciado":"Para livrar o filho, que atropelou uma pessoa, Ernesto vai à delegacia e se acusa de ter dirigido o carro no momento do acidente. Nos termos do Código Penal, Ernesto comete","alternativas":{"A":"denunciação caluniosa.","B":"comunicação falsa de crime.","C":"falso testemunho.","D":"autoacusação falsa.","E":"favorecimento real, apenas."},"gabarito":"D","explicacao":"O art. 341 pune quem se acusa, perante a autoridade, de crime inexistente ou praticado por outrem, com detenção de três meses a dois anos, ou multa.","explicacoes":{"A":"Ernesto não imputou crime a outra pessoa inocente; acusou-se.","B":"O crime existiu; ele apenas se atribuiu a autoria.","C":"Ele não depôs como testemunha; acusou-se perante a autoridade.","D":"Correta: acusar-se de crime praticado por outrem é autoacusação falsa.","E":"Há tipo específico para quem se acusa de crime praticado por outrem (art. 341)."},"fonte":"Código Penal, art. 341","mastigado":"A resposta é a letra D. Ernesto disse à polícia que foi ele quem dirigia, para proteger o filho. Assumir um crime que outra pessoa cometeu é autoacusação falsa, com pena de três meses a dois anos de detenção, ou multa.","teSitua":{"termos":[{"termo":"se acusa","significado":"assume para si a culpa de um fato."},{"termo":"favorecimento real","significado":"crime de ajudar o autor de crime a esconder o proveito do crime."},{"termo":"autoacusação falsa","significado":"crime de quem se acusa perante autoridade de crime que não existiu ou que outro cometeu."}],"exemplo":"O filho de Ernesto bate o carro e fere um ciclista. Para que o rapaz não perca a carteira, Ernesto vai à delegacia e jura que estava ao volante. As câmeras mostram o filho dirigindo. Ernesto responde por autoacusação falsa."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0006","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 342 do Código Penal, podem cometer o crime de falso testemunho ou falsa perícia, EXCETO","alternativas":{"A":"a testemunha.","B":"o perito.","C":"o contador.","D":"o tradutor ou intérprete.","E":"o réu que mente em seu interrogatório."},"gabarito":"E","explicacao":"O art. 342 pune quem faz afirmação falsa, ou nega ou cala a verdade como testemunha, perito, contador, tradutor ou intérprete em processo judicial, ou administrativo, inquérito policial, ou em juízo arbitral. O réu não está entre os sujeitos do tipo.","explicacoes":{"A":"A testemunha é sujeito ativo expresso do art. 342.","B":"O perito é sujeito ativo expresso do art. 342.","C":"O contador é sujeito ativo expresso do art. 342.","D":"Tradutor e intérprete são sujeitos ativos expressos do art. 342.","E":"Correta: o réu não figura no rol do art. 342."},"fonte":"Código Penal, art. 342, caput","mastigado":"A resposta é a letra E. A lei lista quem pode cometer falso testemunho: testemunha, perito, contador, tradutor e intérprete. O réu não está nessa lista, por isso a mentira dele no interrogatório não é esse crime.","teSitua":{"termos":[{"termo":"perito","significado":"especialista chamado para examinar algo e dar sua opinião técnica no processo."},{"termo":"interrogatório","significado":"momento em que o juiz ouve o réu sobre a acusação."},{"termo":"intérprete","significado":"pessoa que traduz oralmente a fala de quem não fala português ou usa Libras."}],"exemplo":"Na audiência, o réu Dênis jura que estava em outra cidade no dia do crime, o que é mentira. A testemunha Vera também mente para ajudá-lo. Vera pode responder por falso testemunho; Dênis, não, porque o réu não está entre os sujeitos do crime."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0007","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"certo_errado","dificuldade":2,"enunciado":"No crime de falso testemunho ou falsa perícia, o fato deixa de ser punível se, antes da sentença no processo em que ocorreu o ilícito, o agente se retrata ou declara a verdade.","gabarito":"C","explicacao":"É a regra do art. 342, § 2º, do Código Penal.","fonte":"Código Penal, art. 342, § 2º","mastigado":"Certo. A testemunha que mentiu ainda pode se salvar se voltar atrás e contar a verdade antes de o juiz dar a sentença naquele processo. Nesse caso, a mentira deixa de ser punida.","teSitua":{"termos":[{"termo":"retrata","significado":"volta atrás e desdiz o que tinha afirmado."},{"termo":"sentença","significado":"decisão do juiz que julga o processo."},{"termo":"ilícito","significado":"ato contrário à lei, proibido por ela."}],"exemplo":"Na audiência, a testemunha Olga mente sobre o horário em que viu o réu. Arrependida, procura o cartório dias depois e pede para ser ouvida de novo, contando a verdade. Como fez isso antes da sentença, Olga não será punida pelo falso testemunho."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0008","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"multipla","dificuldade":3,"enunciado":"Uma testemunha mente em audiência de ação de cobrança. A sentença é proferida e, só depois, ela procura o juízo para declarar a verdade. Nos termos do Código Penal, é correto afirmar que","alternativas":{"A":"o fato deixa de ser punível, pois a retratação pode ocorrer até o trânsito em julgado.","B":"o fato continua punível, pois a retratação só afasta a punição se ocorrer antes da sentença no processo em que ocorreu o ilícito.","C":"a pena é reduzida de metade, pela retratação tardia.","D":"o fato deixa de ser punível, pois a retratação pode ocorrer a qualquer tempo.","E":"a pena é aumentada de um sexto, pois a sentença foi influenciada."},"gabarito":"B","explicacao":"O art. 342, § 2º, exige que a retratação ou a declaração da verdade ocorra antes da sentença no processo em que ocorreu o ilícito. Depois da sentença, a retratação não afasta a punibilidade, e a lei não prevê redução de pena para ela.","explicacoes":{"A":"O marco é a sentença, não o trânsito em julgado.","B":"Correta: a retratação após a sentença não torna o fato impunível.","C":"Não há previsão de redução de metade pela retratação tardia.","D":"A retratação tem prazo: antes da sentença.","E":"O aumento do § 1º depende de suborno ou do tipo de processo, não da influência na sentença."},"fonte":"Código Penal, art. 342, § 2º","mastigado":"A resposta é a letra B. A testemunha só se livra da punição se contar a verdade antes de o juiz decidir. Como ela só voltou atrás depois da sentença, continua respondendo pelo falso testemunho.","teSitua":{"termos":[{"termo":"ação de cobrança","significado":"processo em que alguém pede que o devedor seja condenado a pagar uma dívida."},{"termo":"proferida","significado":"dada, pronunciada pelo juiz no processo."},{"termo":"trânsito em julgado","significado":"momento em que não cabe mais recurso contra a decisão."}],"exemplo":"Na ação de cobrança de Nélson contra Paulo, a testemunha Irene mente a favor de Paulo. O juiz sentencia. Uma semana depois, Irene, arrependida, conta a verdade ao cartório. Como a retratação veio depois da sentença, Irene continua punível."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0009","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"multipla","dificuldade":3,"enunciado":"Em processo penal, uma testemunha faz afirmação falsa com o fim de obter prova destinada a produzir efeito naquele processo. Nos termos do Código Penal, a pena do falso testemunho","alternativas":{"A":"aumenta-se de um sexto a um terço.","B":"é aplicada em dobro.","C":"é aumentada de metade.","D":"é diminuída de um terço, por ser processo penal.","E":"não sofre alteração, pois o aumento só incide em processo civil."},"gabarito":"A","explicacao":"O art. 342, § 1º, prevê que as penas aumentam-se de um sexto a um terço se o crime é praticado mediante suborno ou se cometido com o fim de obter prova destinada a produzir efeito em processo penal, ou em processo civil em que for parte entidade da administração pública direta ou indireta.","explicacoes":{"A":"Correta: aumento de um sexto a um terço (art. 342, § 1º).","B":"Não há previsão de pena em dobro no falso testemunho.","C":"O aumento é de um sexto a um terço.","D":"Não há diminuição; ao contrário, há aumento.","E":"O aumento incide em processo penal e em processo civil com entidade da administração como parte."},"fonte":"Código Penal, art. 342, § 1º","mastigado":"A resposta é a letra A. Mentir como testemunha num processo criminal é mais grave, porque pode levar alguém à prisão. Por isso a pena do falso testemunho cresce de um sexto até um terço.","teSitua":{"termos":[{"termo":"afirmação falsa","significado":"declaração que não corresponde à verdade."},{"termo":"produzir efeito","significado":"influenciar o resultado do processo."}],"exemplo":"No processo por roubo contra Álvaro, a testemunha Luzia diz ter visto Álvaro no local, embora estivesse viajando naquele dia. Como a mentira foi para produzir prova em processo penal, a pena de Luzia pelo falso testemunho aumenta de um sexto a um terço."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0010","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"certo_errado","dificuldade":2,"enunciado":"O falso testemunho só se configura em processo judicial ou inquérito policial, não alcançando a testemunha que cala a verdade em procedimento de juízo arbitral.","gabarito":"E","explicacao":"O art. 342 do CP pune quem faz afirmação falsa, ou nega ou cala a verdade como testemunha, perito, contador, tradutor ou intérprete em processo judicial, ou administrativo, inquérito policial, ou em juízo arbitral. O juízo arbitral está expressamente incluído.","fonte":"Código Penal, art. 342, caput","mastigado":"Errado. A lei inclui expressamente o juízo arbitral, além do processo judicial, do processo administrativo e do inquérito policial. A testemunha que esconde a verdade numa arbitragem também comete falso testemunho.","teSitua":{"termos":[{"termo":"cala a verdade","significado":"deixa de contar o que sabe, ficando em silêncio sobre o fato."},{"termo":"juízo arbitral","significado":"forma de resolver conflitos fora do Judiciário, por um árbitro escolhido pelas partes."}],"exemplo":"Duas empresas resolvem seu conflito numa câmara de arbitragem. Chamado como testemunha, o gerente Tobias sabe que o contrato foi descumprido, mas fica calado sobre isso de propósito. Ele comete falso testemunho, mesmo fora do Judiciário."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0011","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"multipla","dificuldade":2,"enunciado":"Um advogado oferece R$ 5.000,00 a uma testemunha para que ela negue, em audiência de processo trabalhista entre particulares, fatos que presenciou. A testemunha recusa. Nos termos do Código Penal, o advogado comete","alternativas":{"A":"corrupção ativa, punida com reclusão de dois a doze anos, e multa.","B":"coação no curso do processo, punida com reclusão de um a quatro anos, e multa.","C":"corrupção de testemunha, punida com reclusão de três a quatro anos, e multa.","D":"falso testemunho, punido com reclusão de dois a quatro anos, e multa.","E":"tráfico de influência, punido com reclusão de dois a cinco anos, e multa."},"gabarito":"C","explicacao":"O art. 343 pune quem dá, oferece ou promete dinheiro ou qualquer outra vantagem a testemunha, perito, contador, tradutor ou intérprete, para fazer afirmação falsa, negar ou calar a verdade em depoimento, perícia, cálculos, tradução ou interpretação, com reclusão de três a quatro anos, e multa. O oferecimento basta.","explicacoes":{"A":"A corrupção ativa do art. 333 é dirigida a funcionário público; aqui a destinatária é testemunha.","B":"Não houve violência ou grave ameaça.","C":"Correta: oferecer dinheiro a testemunha para negar a verdade é o crime do art. 343.","D":"Quem mente é a testemunha; o advogado que oferece a vantagem responde pelo art. 343.","E":"O advogado não pediu vantagem a pretexto de influir em funcionário."},"fonte":"Código Penal, art. 343, caput","mastigado":"A resposta é a letra C. Oferecer dinheiro a uma testemunha para que ela minta ou esconda a verdade é um crime próprio. Ele existe mesmo que a testemunha recuse, e a pena é de três a quatro anos de reclusão, e multa.","teSitua":{"termos":[{"termo":"oferece","significado":"põe à disposição de alguém uma vantagem para que faça algo."},{"termo":"presenciou","significado":"viu com os próprios olhos, estava lá quando aconteceu."},{"termo":"coação no curso do processo","significado":"crime de usar violência ou grave ameaça contra quem participa de um processo."}],"exemplo":"O advogado Hugo procura a testemunha Neide e oferece R$ 5.000,00 para que ela diga que não viu o acidente na fábrica. Neide recusa e conta tudo ao juiz. Hugo responde por corrupção de testemunha, mesmo sem ela ter aceitado."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0012","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"certo_errado","dificuldade":3,"enunciado":"Quem oferece dinheiro a testemunha para que ela faça afirmação falsa em depoimento recebe a mesma pena do falso testemunho: reclusão, de dois a quatro anos, e multa.","gabarito":"E","explicacao":"O art. 343 prevê pena de reclusão, de três a quatro anos, e multa, diferente da pena do falso testemunho (art. 342), que é de reclusão de dois a quatro anos, e multa.","fonte":"Código Penal, arts. 342 e 343","mastigado":"Errado. Quem paga ou oferece dinheiro à testemunha recebe pena própria, um pouco maior no mínimo: três a quatro anos de reclusão, e multa. A pena de dois a quatro anos é a da testemunha que mente.","teSitua":{"termos":[{"termo":"afirmação falsa","significado":"declaração que não corresponde à verdade."},{"termo":"depoimento","significado":"relato que a testemunha faz perante a autoridade."}],"exemplo":"Pela mentira na audiência, a testemunha Fábio pode pegar de dois a quatro anos de reclusão. Já Sílvia, que lhe ofereceu dinheiro para mentir, responde por crime próprio, com pena mínima maior: três a quatro anos de reclusão."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0013","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"multipla","dificuldade":3,"enunciado":"Sobre a denunciação caluniosa, assinale a alternativa correta.","alternativas":{"A":"Só se configura se o agente der causa à instauração de inquérito policial.","B":"Configura-se também quando o agente dá causa à instauração de ação de improbidade administrativa contra alguém, imputando-lhe ato ímprobo de que o sabe inocente.","C":"Basta que o agente impute crime a alguém, ainda que acredite sinceramente em sua culpa.","D":"É punida com detenção, de um a seis meses, ou multa.","E":"Tem a pena aumentada de metade se a imputação é de contravenção."},"gabarito":"B","explicacao":"O art. 339 alcança a instauração de inquérito policial, procedimento investigatório criminal, processo judicial, processo administrativo disciplinar, inquérito civil ou ação de improbidade administrativa, imputando-se crime, infração ético-disciplinar ou ato ímprobo de que o agente sabe ser a vítima inocente. A pena é de reclusão, de dois a oito anos, e multa, diminuída de metade se a imputação é de contravenção.","explicacoes":{"A":"O tipo abrange outros procedimentos, como processo judicial, processo administrativo disciplinar e inquérito civil.","B":"Correta: a ação de improbidade e o ato ímprobo estão expressamente no art. 339.","C":"Exige-se que o agente saiba que a vítima é inocente.","D":"Essa é a pena da comunicação falsa de crime (art. 340).","E":"Na contravenção, a pena é diminuída de metade, não aumentada."},"fonte":"Código Penal, art. 339, caput e §§ 1º e 2º","mastigado":"A resposta é a letra B. A denunciação caluniosa não se limita à polícia. Provocar uma ação por improbidade ou um processo disciplinar contra alguém que se sabe inocente também é esse crime.","teSitua":{"termos":[{"termo":"ação de improbidade administrativa","significado":"processo para punir agente público que agiu de forma desonesta com a Administração."},{"termo":"ato ímprobo","significado":"conduta desonesta de agente público contra a Administração."},{"termo":"contravenção","significado":"infração penal mais leve que o crime, com penas menores."}],"exemplo":"Para tirar um rival do cargo, Saulo envia ao Ministério Público documentos montados acusando o secretário Edson de desviar verbas, sabendo que ele é honesto. O MP propõe ação de improbidade contra Edson. Saulo comete denunciação caluniosa."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0014","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"multipla","dificuldade":3,"enunciado":"O elemento que distingue a denunciação caluniosa (art. 339) da comunicação falsa de crime ou de contravenção (art. 340) é que, na primeira,","alternativas":{"A":"o fato comunicado é sempre contravenção.","B":"não há necessidade de provocar a ação da autoridade.","C":"o agente se acusa de crime praticado por outrem.","D":"o agente imputa o fato a pessoa determinada que sabe ser inocente.","E":"a pena é de detenção, e não de reclusão."},"gabarito":"D","explicacao":"Na denunciação caluniosa, o agente dá causa a procedimento contra alguém, imputando-lhe crime, infração ético-disciplinar ou ato ímprobo de que o sabe inocente. Na comunicação falsa (art. 340), o agente comunica crime ou contravenção que sabe não se ter verificado, sem atribuí-lo a pessoa determinada.","explicacoes":{"A":"A denunciação pode envolver crime, infração ético-disciplinar ou ato ímprobo; a contravenção só reduz a pena.","B":"A denunciação exige dar causa à instauração de procedimento.","C":"Acusar-se de crime de outrem é a autoacusação falsa (art. 341).","D":"Correta: a imputação a pessoa determinada e inocente marca a denunciação caluniosa.","E":"A denunciação caluniosa é punida com reclusão; a comunicação falsa, com detenção."},"fonte":"Código Penal, arts. 339, 340 e 341","mastigado":"A resposta é a letra D. Na denunciação caluniosa, a pessoa aponta alguém específico como culpado, sabendo que ele é inocente. Na comunicação falsa, ela só inventa um crime, sem acusar ninguém.","teSitua":{"termos":[{"termo":"imputa","significado":"atribui a alguém a autoria de um fato."},{"termo":"pessoa determinada","significado":"alguém identificado, que se sabe quem é."}],"exemplo":"Bia inventa na delegacia que foi roubada por \\"dois rapazes desconhecidos\\": comunicação falsa de crime. Já sua amiga Lena diz que o roubo foi cometido pelo ex-namorado, sabendo que ele estava em outra cidade, e o inquérito é aberto contra ele: denunciação caluniosa."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0015","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"certo_errado","dificuldade":2,"enunciado":"A comunicação falsa de crime ou de contravenção é punida com detenção, de um a seis meses, ou multa.","gabarito":"C","explicacao":"É a pena do art. 340 do Código Penal para quem provoca a ação de autoridade comunicando crime ou contravenção que sabe não se ter verificado.","fonte":"Código Penal, art. 340","mastigado":"Certo. Quem inventa para a polícia um crime que não aconteceu, sem acusar ninguém, recebe pena leve: detenção de um a seis meses, ou só multa.","teSitua":{"termos":[{"termo":"comunicação falsa","significado":"aviso mentiroso feito à autoridade sobre um fato que não ocorreu."},{"termo":"contravenção","significado":"infração penal mais leve que o crime, com penas menores."}],"exemplo":"Para justificar a falta ao trabalho, Gil diz à polícia que seu carro foi furtado, o que não é verdade. A polícia gasta horas procurando o veículo. Gil responde por comunicação falsa de crime, com detenção de um a seis meses, ou multa."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0016","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do Código Penal, a autoacusação falsa é punida com","alternativas":{"A":"reclusão, de dois a oito anos, e multa.","B":"detenção, de um a seis meses, ou multa.","C":"reclusão, de dois a quatro anos, e multa.","D":"reclusão, de três a quatro anos, e multa.","E":"detenção, de três meses a dois anos, ou multa."},"gabarito":"E","explicacao":"O art. 341 prevê detenção, de três meses a dois anos, ou multa, para quem se acusa, perante a autoridade, de crime inexistente ou praticado por outrem.","explicacoes":{"A":"É a pena da denunciação caluniosa (art. 339).","B":"É a pena da comunicação falsa de crime (art. 340).","C":"É a pena do falso testemunho (art. 342).","D":"É a pena da corrupção de testemunha (art. 343).","E":"Correta: é a pena da autoacusação falsa."},"fonte":"Código Penal, arts. 339 a 343","mastigado":"A resposta é a letra E. Quem assume perante a autoridade um crime que não existiu ou que outra pessoa cometeu responde com detenção de três meses a dois anos, ou multa.","teSitua":{"termos":[{"termo":"autoacusação falsa","significado":"crime de quem se acusa perante autoridade de crime que não existiu ou que outro cometeu."},{"termo":"detenção","significado":"tipo de pena de prisão mais leve, que não começa em regime fechado."}],"exemplo":"Para chamar atenção, Juca vai à delegacia e confessa um incêndio numa loja que, na verdade, foi causado por curto-circuito. Ele responde por autoacusação falsa, com detenção de três meses a dois anos, ou multa."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0017","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"certo_errado","dificuldade":3,"enunciado":"Não comete autoacusação falsa quem se acusa, perante a autoridade, de crime praticado por outrem, pois nesse caso o crime efetivamente existiu.","gabarito":"E","explicacao":"O art. 341 pune quem se acusa, perante a autoridade, de crime inexistente ou praticado por outrem. As duas situações estão no tipo.","fonte":"Código Penal, art. 341","mastigado":"Errado. A lei pune tanto quem assume um crime que nunca existiu quanto quem assume um crime que outra pessoa cometeu. O fato de o crime ter acontecido não livra quem se acusa falsamente.","teSitua":{"termos":[{"termo":"se acusa","significado":"assume para si a culpa de um fato."},{"termo":"praticado por outrem","significado":"cometido por outra pessoa, e não por quem se acusa."}],"exemplo":"Depois que seu chefe desvia dinheiro da empresa, o funcionário Lauro, pressionado, vai à delegacia e diz que foi ele o autor do desvio. O crime existiu, mas foi praticado por outro. Lauro comete autoacusação falsa."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0018","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"multipla","dificuldade":3,"enunciado":"Em inquérito policial que apura um homicídio, uma testemunha afirma falsamente ter visto o investigado no local do crime. Nos termos do Código Penal, é correto afirmar que","alternativas":{"A":"há falso testemunho, pois o tipo abrange o inquérito policial.","B":"não há falso testemunho, que só existe em processo judicial.","C":"há denunciação caluniosa, pois o investigado é inocente.","D":"há comunicação falsa de crime.","E":"não há crime, pois o inquérito não leva à condenação."},"gabarito":"A","explicacao":"O art. 342 pune quem faz afirmação falsa, ou nega ou cala a verdade como testemunha, perito, contador, tradutor ou intérprete em processo judicial, ou administrativo, inquérito policial, ou em juízo arbitral. Como a prova se destina a efeito em processo penal, incide também o aumento do § 1º.","explicacoes":{"A":"Correta: o inquérito policial está expressamente no art. 342.","B":"O tipo abrange processo administrativo, inquérito policial e juízo arbitral.","C":"A testemunha não deu causa à instauração do procedimento; o inquérito já existia.","D":"O homicídio existiu; não há comunicação de crime inexistente.","E":"O tipo alcança o depoimento falso no inquérito policial."},"fonte":"Código Penal, art. 342, caput e § 1º","mastigado":"A resposta é a letra A. Mentir como testemunha na delegacia, durante o inquérito, também é falso testemunho. O crime não acontece só diante do juiz.","teSitua":{"termos":[{"termo":"inquérito policial","significado":"investigação feita pela polícia para apurar um crime e quem o cometeu."},{"termo":"investigado","significado":"pessoa suspeita, que está sendo investigada."},{"termo":"denunciação caluniosa","significado":"crime de quem provoca investigação ou processo contra alguém que sabe ser inocente."}],"exemplo":"Ouvido pelo delegado, o porteiro Edu diz ter visto Mauro saindo do prédio na hora do crime, embora estivesse de folga. A mentira é descoberta pelas câmeras. Edu responde por falso testemunho, porque o tipo alcança o depoimento no inquérito policial."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0019","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"certo_errado","dificuldade":3,"enunciado":"A denunciação caluniosa exige que o agente saiba que a pessoa a quem imputa o crime, a infração ético-disciplinar ou o ato ímprobo é inocente.","gabarito":"C","explicacao":"O art. 339 usa a expressão \\"de que o sabe inocente\\": o agente precisa ter certeza da inocência da vítima. Quem acredita, ainda que erradamente, na culpa do outro não comete o crime.","fonte":"Código Penal, art. 339, caput","mastigado":"Certo. Só comete denunciação caluniosa quem acusa sabendo que o outro não fez nada. Quem realmente acredita na culpa da pessoa e se engana não comete esse crime.","teSitua":{"termos":[{"termo":"imputa","significado":"atribui a alguém a autoria de um fato."},{"termo":"infração ético-disciplinar","significado":"falta contra as regras de conduta de uma profissão ou de um cargo."},{"termo":"ato ímprobo","significado":"conduta desonesta de agente público contra a Administração."}],"exemplo":"Dona Célia vê o vizinho com uma bicicleta igual à que lhe furtaram e o denuncia, crente de que foi ele. Depois se prova que a bicicleta era dele mesmo. Como Célia acreditava sinceramente na culpa, não comete denunciação caluniosa."}},{"id":"aut.penal_tj.denunciacao_falso_testemunho.0020","subtopico":"penal_tj.adm_justica.denunciacao_falso_testemunho","tipo":"multipla","dificuldade":4,"enunciado":"Um advogado oferece dinheiro a um perito judicial para que ele faça afirmação falsa em laudo destinado a produzir efeito em processo penal. Nos termos do Código Penal, o advogado responde pelo crime do art. 343, com pena de reclusão de três a quatro anos, e multa,","alternativas":{"A":"aplicada em dobro.","B":"sem aumento, pois o aumento só existe para o falso testemunho.","C":"aumentada de metade.","D":"aumentada de um sexto a um terço.","E":"diminuída de um terço, se o perito recusar a oferta."},"gabarito":"D","explicacao":"O parágrafo único do art. 343 prevê que as penas aumentam-se de um sexto a um terço se o crime é cometido com o fim de obter prova destinada a produzir efeito em processo penal ou em processo civil em que for parte entidade da administração pública direta ou indireta.","explicacoes":{"A":"Não há previsão de pena em dobro.","B":"O art. 343 tem causa de aumento própria no parágrafo único.","C":"O aumento é de um sexto a um terço.","D":"Correta: aumento de um sexto a um terço (art. 343, parágrafo único).","E":"A recusa do perito não reduz a pena; o oferecimento já configura o crime."},"fonte":"Código Penal, art. 343, caput e parágrafo único","mastigado":"A resposta é a letra D. Oferecer dinheiro ao perito para mentir no laudo já é crime. Como o laudo seria usado num processo criminal, a lei aumenta a pena de um sexto até um terço.","teSitua":{"termos":[{"termo":"perito judicial","significado":"especialista nomeado pelo juiz para examinar algo e dar opinião técnica."},{"termo":"laudo","significado":"relatório escrito do perito com o resultado do exame."}],"exemplo":"No processo por lesão corporal contra seu cliente, o advogado Marcos oferece R$ 20.000,00 ao perito Raul para que o laudo diga que os ferimentos eram leves. Raul recusa. Marcos responde por corrupção de perito, com pena aumentada de um sexto a um terço."}},{"id":"aut.penal_tj.edital_documentos.0001","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":2,"enunciado":"Inconformado com o leilão de seu imóvel, o executado arranca e rasga o edital de praça afixado, por ordem do juiz, no átrio do fórum. Nos termos do Código Penal, a conduta configura","alternativas":{"A":"dano qualificado, por se tratar de bem público.","B":"subtração ou inutilização de livro ou documento, punida com reclusão de dois a cinco anos.","C":"supressão de documento, punida com reclusão de dois a seis anos, e multa.","D":"inutilização de edital, punida com detenção de um mês a um ano, ou multa.","E":"desobediência, punida com detenção de quinze dias a seis meses, e multa."},"gabarito":"D","explicacao":"O art. 336 pune quem rasga ou, de qualquer forma, inutiliza ou conspurca edital afixado por ordem de funcionário público, com detenção de um mês a um ano, ou multa.","explicacoes":{"A":"Há tipo específico para quem rasga edital afixado por ordem de funcionário público (art. 336).","B":"O art. 337 trata de livro oficial, processo ou documento confiado à custódia de funcionário, não de edital afixado.","C":"A supressão de documento (art. 305) é crime contra a fé pública; o edital afixado tem proteção própria no art. 336.","D":"Correta: rasgar edital afixado por ordem de funcionário público é o crime do art. 336.","E":"Não houve descumprimento de ordem dirigida ao agente; houve inutilização do edital."},"fonte":"Código Penal, art. 336","mastigado":"A resposta é a letra D. O aviso do leilão estava pregado no fórum por ordem do juiz. Arrancar e rasgar esse aviso é o crime de inutilização de edital, com pena de um mês a um ano de detenção, ou multa.","teSitua":{"termos":[{"termo":"edital de praça","significado":"aviso público que anuncia o leilão judicial de um bem penhorado."},{"termo":"átrio do fórum","significado":"o saguão de entrada do prédio do fórum."},{"termo":"executado","significado":"a pessoa que está sendo cobrada no processo de execução."},{"termo":"inutilização de edital","significado":"crime de rasgar, estragar ou sujar aviso oficial afixado por ordem de servidor."}],"exemplo":"O apartamento de Válter vai a leilão e o edital está pregado no quadro de avisos do fórum. Furioso, Válter arranca o papel, rasga em pedaços e joga no chão. Ele responde por inutilização de edital, com detenção de um mês a um ano, ou multa."}},{"id":"aut.penal_tj.edital_documentos.0002","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"certo_errado","dificuldade":2,"enunciado":"Comete o crime do art. 336 do Código Penal quem conspurca edital afixado por ordem de funcionário público, ainda que não o rasgue.","gabarito":"C","explicacao":"O art. 336 descreve as condutas de rasgar ou, de qualquer forma, inutilizar ou conspurcar edital afixado por ordem de funcionário público. Conspurcar (sujar, manchar) basta.","fonte":"Código Penal, art. 336","mastigado":"Certo. Não é preciso rasgar o aviso oficial. Sujar, pichar ou manchar o edital afixado por ordem de servidor também é crime, porque a lei usa o verbo conspurcar.","teSitua":{"termos":[{"termo":"conspurca","significado":"suja, mancha ou picha algo."},{"termo":"afixado","significado":"pregado ou colado em lugar visível ao público."}],"exemplo":"Ao ver seu nome no edital de citação pregado no fórum, Jair passa caneta preta sobre o papel e escreve palavrões por cima. O edital não foi rasgado, mas foi conspurcado. Jair comete o crime de inutilização de edital."}},{"id":"aut.penal_tj.edital_documentos.0003","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":3,"enunciado":"Por ordem judicial, um estabelecimento é interditado e suas portas recebem lacres oficiais. O proprietário rompe os lacres à noite para retirar mercadorias. Nos termos do Código Penal, ao romper os lacres, ele comete","alternativas":{"A":"violação de sinal, punida com detenção de um mês a um ano, ou multa.","B":"desobediência, punida com detenção de quinze dias a seis meses, e multa.","C":"subtração de documento, punida com reclusão de dois a cinco anos.","D":"fraude processual, punida com detenção de três meses a dois anos, e multa.","E":"resistência, punida com detenção de dois meses a dois anos."},"gabarito":"A","explicacao":"O art. 336, na segunda parte, pune quem viola ou inutiliza selo ou sinal empregado, por determinação legal ou por ordem de funcionário público, para identificar ou cerrar qualquer objeto, com detenção de um mês a um ano, ou multa.","explicacoes":{"A":"Correta: romper lacre oficial aposto por ordem de funcionário é violação de selo ou sinal (art. 336).","B":"A violação de lacre tem tipo específico no art. 336.","C":"Não houve subtração de livro, processo ou documento.","D":"A fraude processual exige inovação artificiosa para induzir em erro juiz ou perito.","E":"Não houve oposição a ato legal com violência ou ameaça a funcionário."},"fonte":"Código Penal, art. 336","mastigado":"A resposta é a letra A. Os lacres foram colocados por ordem da Justiça para fechar a loja. Rompê-los é violar sinal oficial, crime com pena de um mês a um ano de detenção, ou multa.","teSitua":{"termos":[{"termo":"interditado","significado":"fechado por ordem da autoridade, proibido de funcionar."},{"termo":"lacres oficiais","significado":"selos colocados pela autoridade para fechar algo e mostrar se foi aberto."},{"termo":"violação de sinal","significado":"crime de romper ou estragar selo oficial usado para identificar ou fechar algo."}],"exemplo":"A padaria de Osmar foi interditada pelo juiz e o oficial de justiça colocou lacres nas portas. De madrugada, Osmar corta os lacres para tirar a farinha do estoque. Ele responde por violação de sinal oficial."}},{"id":"aut.penal_tj.edital_documentos.0004","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"certo_errado","dificuldade":2,"enunciado":"O crime de inutilização de edital ou de sinal é punido com detenção, de um mês a um ano, ou multa.","gabarito":"C","explicacao":"É a pena prevista no art. 336 do Código Penal.","fonte":"Código Penal, art. 336","mastigado":"Certo. Rasgar ou sujar um edital oficial, ou romper um selo oficial, tem pena leve: detenção de um mês a um ano, ou só multa.","teSitua":{"termos":[{"termo":"inutilização de edital","significado":"crime de rasgar, estragar ou sujar aviso oficial afixado por ordem de servidor."},{"termo":"detenção","significado":"tipo de pena de prisão mais leve, que não começa em regime fechado."}],"exemplo":"Lucas arranca o edital do concurso de remoção afixado pelo diretor do fórum e o joga no lixo. Condenado por inutilização de edital, o juiz escolhe aplicar apenas multa, o que a lei permite nesse crime."}},{"id":"aut.penal_tj.edital_documentos.0005","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":3,"enunciado":"Ao consultar um processo físico no balcão do cartório, uma parte arranca e leva consigo as folhas que continham um laudo desfavorável. Se o fato não constituir crime mais grave, ela responde por","alternativas":{"A":"supressão de documento, com reclusão de dois a seis anos, e multa.","B":"subtração ou inutilização de livro ou documento, com reclusão de dois a cinco anos.","C":"inutilização de edital, com detenção de um mês a um ano, ou multa.","D":"extravio, sonegação ou inutilização de livro ou documento, com reclusão de um a quatro anos.","E":"furto simples, com reclusão de um a quatro anos, e multa."},"gabarito":"B","explicacao":"O art. 337 pune quem subtrai, ou inutiliza, total ou parcialmente, livro oficial, processo ou documento confiado à custódia de funcionário, em razão de ofício, ou de particular em serviço público, com reclusão de dois a cinco anos, se o fato não constitui crime mais grave.","explicacoes":{"A":"O processo estava sob custódia de funcionário, hipótese que tem tipo próprio no art. 337.","B":"Correta: subtrair parte do processo confiado à custódia de funcionário é o art. 337.","C":"Processo não é edital afixado.","D":"O art. 314 é crime do funcionário que tem a guarda do documento; a parte é particular.","E":"A subtração de processo confiado à custódia de funcionário tem tipo próprio no art. 337."},"fonte":"Código Penal, art. 337","mastigado":"A resposta é a letra B. O processo estava sob os cuidados do cartório. A parte, que não é servidora, arrancou e levou folhas dele. Esse é o crime de subtração ou inutilização de documento, com dois a cinco anos de reclusão.","teSitua":{"termos":[{"termo":"processo físico","significado":"processo em papel, com folhas costuradas, e não eletrônico."},{"termo":"laudo desfavorável","significado":"relatório do perito com conclusão contrária ao interesse da parte."},{"termo":"balcão do cartório","significado":"local de atendimento ao público no cartório judicial."}],"exemplo":"No balcão da vara, Ronan pede para ver o processo em que é réu. Quando a escrevente se distrai, arranca as folhas do laudo que o prejudica e as esconde na pasta. Ronan responde por subtração ou inutilização de documento."}},{"id":"aut.penal_tj.edital_documentos.0006","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"certo_errado","dificuldade":3,"enunciado":"O crime de subtração ou inutilização de livro ou documento é punido com reclusão, de dois a cinco anos, se o fato não constitui crime mais grave.","gabarito":"C","explicacao":"É a pena do art. 337 do Código Penal, que é expressamente subsidiário.","fonte":"Código Penal, art. 337","mastigado":"Certo. Quem tira ou estraga um livro oficial, processo ou documento guardado por servidor pega de dois a cinco anos de reclusão. Mas, se a conduta fizer parte de um crime mais grave, responde por este.","teSitua":{"termos":[{"termo":"subtração","significado":"ato de tirar algo de onde está, levando consigo."},{"termo":"crime mais grave","significado":"crime com pena maior, que absorve o crime menor."}],"exemplo":"Dirce leva para casa um livro de registro de audiências do fórum para apagar uma anotação. Ela responde pelo crime de subtração de livro oficial, com reclusão de dois a cinco anos, já que o fato não integra crime mais grave."}},{"id":"aut.penal_tj.edital_documentos.0007","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":3,"enunciado":"Sobre a diferença entre os arts. 314 e 337 do Código Penal, é correto afirmar que","alternativas":{"A":"ambos só podem ser praticados por funcionário público.","B":"o art. 337 exige que o agente tenha a guarda do documento em razão do cargo.","C":"o art. 314 está no capítulo dos crimes praticados por particular contra a Administração.","D":"ambos têm a mesma pena de reclusão de dois a cinco anos.","E":"o art. 314 é praticado pelo funcionário que tem a guarda do documento em razão do cargo, ao passo que o art. 337 protege documento confiado à custódia de funcionário, podendo ser praticado por particular."},"gabarito":"E","explicacao":"O art. 314 (extravio, sonegação ou inutilização de livro ou documento) está entre os crimes de funcionário público e exige que o agente tenha a guarda em razão do cargo, com reclusão de um a quatro anos. O art. 337 está entre os crimes de particular contra a Administração e protege livro oficial, processo ou documento confiado à custódia de funcionário, em razão de ofício, ou de particular em serviço público, com reclusão de dois a cinco anos.","explicacoes":{"A":"O art. 337 está no capítulo dos crimes praticados por particular.","B":"É o art. 314 que exige a guarda em razão do cargo.","C":"O art. 314 está no capítulo dos crimes praticados por funcionário público.","D":"O art. 314 tem pena de um a quatro anos; o art. 337, de dois a cinco anos.","E":"Correta: é a distinção entre o crime do guardião (314) e o de quem atinge documento sob custódia alheia (337)."},"fonte":"Código Penal, arts. 314 e 337","mastigado":"A resposta é a letra E. Se quem some com o documento é o próprio servidor que cuidava dele, o crime é um. Se é outra pessoa, como uma parte, mexendo em documento guardado pelo servidor, o crime é outro, com pena maior.","teSitua":{"termos":[{"termo":"guarda do documento","significado":"dever de cuidar e conservar o documento."},{"termo":"confiado à custódia","significado":"entregue aos cuidados de alguém."},{"termo":"particular","significado":"pessoa comum, que não é servidor público."}],"exemplo":"O escrevente Iuri, responsável pelo arquivo, joga fora um processo que guardava: responde pelo art. 314. Já Elza, parte, rasga em pedaços o mesmo tipo de processo que pegou no balcão: responde pelo art. 337. A diferença está em quem tinha a guarda."}},{"id":"aut.penal_tj.edital_documentos.0008","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"certo_errado","dificuldade":3,"enunciado":"O art. 337 do Código Penal protege não só o documento confiado à custódia de funcionário em razão de ofício, mas também o confiado a particular em serviço público.","gabarito":"C","explicacao":"O art. 337 menciona livro oficial, processo ou documento confiado à custódia de funcionário, em razão de ofício, ou de particular em serviço público.","fonte":"Código Penal, art. 337","mastigado":"Certo. A lei também protege documentos guardados por pessoas que não são servidores, mas estão prestando um serviço público. Subtrair ou estragar o que está com elas também é crime.","teSitua":{"termos":[{"termo":"particular em serviço público","significado":"pessoa que não é servidora, mas está prestando um serviço ao poder público."},{"termo":"em razão de ofício","significado":"por causa do trabalho ou da função exercida."}],"exemplo":"Uma empresa privada contratada guarda as caixas de processos arquivados do tribunal. Flora, interessada em sumir com um processo, entra no depósito e leva os autos. Ela comete o crime do art. 337, porque o documento estava sob custódia de particular em serviço público."}},{"id":"aut.penal_tj.edital_documentos.0009","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 337 do Código Penal, são objetos materiais do crime de subtração ou inutilização de livro ou documento","alternativas":{"A":"o edital afixado e o selo oficial.","B":"apenas o documento público original.","C":"o livro oficial, o processo ou o documento confiado à custódia de funcionário, em razão de ofício, ou de particular em serviço público.","D":"apenas o processo judicial em andamento.","E":"somente o documento particular de que o agente não podia dispor."},"gabarito":"C","explicacao":"O art. 337 menciona livro oficial, processo ou documento confiado à custódia de funcionário, em razão de ofício, ou de particular em serviço público.","explicacoes":{"A":"Edital afixado e selo oficial são objetos do art. 336.","B":"O tipo não se limita a documento público original; abrange livro oficial e processo.","C":"Correta: é o rol do art. 337.","D":"O tipo abrange livro oficial e documento, não só processo.","E":"Documento de que o agente não podia dispor aparece no art. 305 (supressão de documento)."},"fonte":"Código Penal, arts. 305, 336 e 337","mastigado":"A resposta é a letra C. A lei protege o livro oficial, o processo e qualquer documento que esteja sob a guarda de um servidor, ou de um particular prestando serviço público. Edital e selo são protegidos em outro artigo.","teSitua":{"termos":[{"termo":"objetos materiais","significado":"as coisas sobre as quais recai a conduta do crime."},{"termo":"livro oficial","significado":"livro de registros mantido por órgão público, como o livro de protocolo."},{"termo":"edital afixado","significado":"aviso oficial pregado em lugar público."}],"exemplo":"O tribunal mantém um livro oficial de registro de sentenças sob a guarda da escrevente Nádia. Um réu arranca a folha onde está registrada sua condenação. O livro é objeto material do crime do art. 337."}},{"id":"aut.penal_tj.edital_documentos.0010","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"certo_errado","dificuldade":3,"enunciado":"O art. 336 do Código Penal só protege o selo ou sinal empregado por ordem de funcionário público, não alcançando o selo empregado por determinação legal.","gabarito":"E","explicacao":"O art. 336 pune quem viola ou inutiliza selo ou sinal empregado, por determinação legal ou por ordem de funcionário público, para identificar ou cerrar qualquer objeto. As duas origens são protegidas.","fonte":"Código Penal, art. 336","mastigado":"Errado. A lei protege os dois casos: o selo colocado por ordem de um servidor e o selo exigido diretamente pela lei. Romper qualquer um deles para abrir ou trocar o objeto é crime.","teSitua":{"termos":[{"termo":"selo ou sinal","significado":"lacre, carimbo ou marca oficial usada para identificar ou fechar algo."},{"termo":"determinação legal","significado":"ordem que vem diretamente da lei."}],"exemplo":"A lei exige que certos medidores de combustível tenham lacre oficial. Eurico rompe o lacre da bomba do seu posto para mexer na medição. Mesmo sem ordem específica de um servidor, o lacre foi posto por determinação legal, e Eurico comete o crime do art. 336."}},{"id":"aut.penal_tj.edital_documentos.0011","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":3,"enunciado":"Inês rasga um cartaz de propaganda de uma loja particular, colado no muro da vizinhança sem qualquer ordem de autoridade. Em relação ao art. 336 do Código Penal, é correto afirmar que","alternativas":{"A":"não há o crime de inutilização de edital, porque o cartaz não foi afixado por ordem de funcionário público.","B":"há o crime de inutilização de edital, porque qualquer aviso afixado em local público é protegido.","C":"há o crime de violação de sinal, porque o cartaz identifica a loja.","D":"há o crime do art. 337, porque o cartaz é documento particular.","E":"só haveria crime se Inês tivesse apenas conspurcado o cartaz, sem rasgá-lo."},"gabarito":"A","explicacao":"O art. 336 protege o edital afixado por ordem de funcionário público. Cartaz particular, sem ordem de autoridade, não é objeto do crime.","explicacoes":{"A":"Correta: falta o elemento \\"afixado por ordem de funcionário público\\".","B":"Só o edital afixado por ordem de funcionário público é protegido pelo art. 336.","C":"O sinal protegido é o empregado por determinação legal ou ordem de funcionário para identificar ou cerrar objeto.","D":"O art. 337 trata de livro oficial, processo ou documento confiado à custódia de funcionário.","E":"Rasgar e conspurcar são condutas equivalentes no tipo; o problema é a natureza do cartaz."},"fonte":"Código Penal, art. 336","mastigado":"A resposta é a letra A. O crime protege os avisos oficiais colocados por ordem de servidor. Um cartaz de loja não tem nada de oficial, então rasgá-lo não é inutilização de edital.","teSitua":{"termos":[{"termo":"propaganda","significado":"anúncio feito para vender um produto ou serviço."},{"termo":"inutilização de edital","significado":"crime de rasgar, estragar ou sujar aviso oficial afixado por ordem de servidor."},{"termo":"conspurcado","significado":"que foi sujo, manchado ou pichado."}],"exemplo":"Inês se irrita com os cartazes de uma loja de colchões colados no muro da sua rua e os rasga. Não há crime de inutilização de edital, porque ninguém do poder público mandou afixá-los."}},{"id":"aut.penal_tj.edital_documentos.0012","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":3,"enunciado":"Assinale a alternativa que associa corretamente o crime à sua pena.","alternativas":{"A":"Inutilização de edital ou de sinal (art. 336): reclusão, de dois a cinco anos.","B":"Subtração ou inutilização de livro ou documento (art. 337): detenção, de um mês a um ano, ou multa.","C":"Extravio, sonegação ou inutilização de livro ou documento (art. 314): reclusão, de dois a cinco anos.","D":"Subtração ou inutilização de livro ou documento (art. 337): reclusão, de dois a cinco anos, se o fato não constitui crime mais grave.","E":"Inutilização de edital ou de sinal (art. 336): detenção, de quinze dias a seis meses, e multa."},"gabarito":"D","explicacao":"Art. 336: detenção, de um mês a um ano, ou multa. Art. 337: reclusão, de dois a cinco anos, se o fato não constitui crime mais grave. Art. 314: reclusão, de um a quatro anos, se o fato não constitui crime mais grave.","explicacoes":{"A":"A pena do art. 336 é detenção de um mês a um ano, ou multa.","B":"Essa é a pena do art. 336, não do art. 337.","C":"A pena do art. 314 é reclusão de um a quatro anos.","D":"Correta: é a pena do art. 337.","E":"Quinze dias a seis meses, e multa, é a pena da desobediência (art. 330)."},"fonte":"Código Penal, arts. 314, 336 e 337","mastigado":"A resposta é a letra D. Tirar ou estragar livro, processo ou documento guardado por servidor é o crime mais grave do tema: dois a cinco anos de reclusão. Rasgar edital ou romper selo tem pena leve, de um mês a um ano ou multa.","teSitua":{"termos":[{"termo":"sonegação","significado":"esconder ou deixar de entregar algo que devia ser apresentado."},{"termo":"inutilização","significado":"ato de estragar algo a ponto de não servir mais."}],"exemplo":"Na revisão para a prova, Talita monta uma tabela: edital rasgado, até um ano de detenção ou multa; processo arrancado do balcão por uma parte, dois a cinco anos de reclusão; processo sumido pelo próprio servidor guardião, um a quatro anos."}},{"id":"aut.penal_tj.edital_documentos.0013","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"certo_errado","dificuldade":3,"enunciado":"Não configura o crime do art. 337 do Código Penal a inutilização apenas parcial do processo confiado à custódia de funcionário, como o rasgo de algumas folhas.","gabarito":"E","explicacao":"O art. 337 pune quem subtrai, ou inutiliza, total ou parcialmente, livro oficial, processo ou documento confiado à custódia de funcionário. A inutilização parcial está expressamente prevista.","fonte":"Código Penal, art. 337","mastigado":"Errado. A lei diz claramente que basta estragar uma parte. Rasgar só algumas folhas do processo já é o crime, não sendo preciso destruir o processo inteiro.","teSitua":{"termos":[{"termo":"inutilização apenas parcial","significado":"estrago de só uma parte, de modo que ela deixe de servir."},{"termo":"custódia de funcionário","significado":"guarda e responsabilidade de um servidor público."}],"exemplo":"Durante a consulta no balcão, Hélio rasga ao meio só a folha da procuração do advogado da parte contrária, deixando o resto do processo intacto. Ele comete o crime do art. 337, porque a inutilização parcial basta."}},{"id":"aut.penal_tj.edital_documentos.0014","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":3,"enunciado":"Durante uma investigação, por ordem do delegado, um malote com documentos apreendidos é fechado com lacre numerado. Antes da perícia, um investigado consegue acesso ao malote e rompe o lacre para trocar papéis. Quanto ao rompimento do lacre, o investigado pratica","alternativas":{"A":"desobediência.","B":"violação de selo ou sinal empregado por ordem de funcionário público para cerrar objeto.","C":"inutilização de edital afixado por ordem de funcionário público.","D":"usurpação de função pública.","E":"exercício arbitrário das próprias razões."},"gabarito":"B","explicacao":"O art. 336, segunda parte, pune quem viola ou inutiliza selo ou sinal empregado, por determinação legal ou por ordem de funcionário público, para identificar ou cerrar qualquer objeto. A troca de papéis pode, além disso, configurar outros crimes, como a fraude processual.","explicacoes":{"A":"Há tipo específico para a violação de selo ou sinal (art. 336).","B":"Correta: o lacre foi empregado por ordem de funcionário para cerrar o malote.","C":"O lacre não é edital.","D":"O investigado não exerceu função pública.","E":"Não há pretensão legítima satisfeita pelas próprias mãos."},"fonte":"Código Penal, art. 336","mastigado":"A resposta é a letra B. O lacre foi colocado por ordem do delegado para fechar o malote. Quem rompe esse lacre viola um sinal oficial, crime previsto junto com a inutilização de edital.","teSitua":{"termos":[{"termo":"malote","significado":"saco ou envelope resistente usado para transportar documentos."},{"termo":"lacre numerado","significado":"selo com número que mostra se o pacote foi aberto."},{"termo":"cerrar","significado":"fechar, de modo que não se possa abrir."},{"termo":"exercício arbitrário das próprias razões","significado":"crime de fazer justiça com as próprias mãos."}],"exemplo":"O malote com as notas fiscais da empresa de Gervásio foi lacrado por ordem do delegado. Gervásio suborna um faxineiro, entra na sala e corta o lacre para trocar algumas notas. Pelo rompimento do lacre, ele comete violação de selo ou sinal oficial."}},{"id":"aut.penal_tj.edital_documentos.0015","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"certo_errado","dificuldade":2,"enunciado":"Os crimes de inutilização de edital ou de sinal e de subtração ou inutilização de livro ou documento estão no capítulo do Código Penal que trata dos crimes praticados por particular contra a Administração em geral.","gabarito":"C","explicacao":"Os arts. 336 e 337 integram o Capítulo II do Título XI da Parte Especial, \\"Dos crimes praticados por particular contra a administração em geral\\", que vai do art. 328 ao art. 337-A.","fonte":"Código Penal, Título XI, Capítulo II, arts. 336 e 337","mastigado":"Certo. Esses dois crimes estão na parte da lei que trata das condutas de pessoas comuns contra o poder público, ao lado de crimes como desacato, desobediência e corrupção ativa.","teSitua":{"termos":[{"termo":"Administração em geral","significado":"o conjunto dos órgãos e serviços do poder público."},{"termo":"particular","significado":"pessoa comum, que não é servidor público."}],"exemplo":"Estudando o Código Penal, Bárbara percebe que, logo depois do desacato, da desobediência e da corrupção ativa, vêm a inutilização de edital e a subtração de documento. Todos estão no capítulo dos crimes praticados por particular contra a Administração."}},{"id":"aut.penal_tj.edital_documentos.0016","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":3,"enunciado":"O preceito secundário do art. 337 do Código Penal traz a ressalva \\"se o fato não constitui crime mais grave\\". Essa ressalva significa que","alternativas":{"A":"a pena será sempre aumentada de um terço.","B":"o crime só existe se houver também outro crime mais grave.","C":"o juiz pode escolher entre a pena do art. 337 e a de qualquer outro crime.","D":"as penas dos dois crimes devem ser somadas.","E":"o art. 337 é subsidiário, aplicando-se apenas quando o fato não configurar crime mais grave."},"gabarito":"E","explicacao":"A expressão indica subsidiariedade expressa: se a mesma conduta configurar crime mais grave, aplica-se apenas este; não havendo, aplica-se o art. 337 (reclusão, de dois a cinco anos).","explicacoes":{"A":"A ressalva não cria causa de aumento.","B":"Ao contrário: o art. 337 se aplica justamente quando não há crime mais grave.","C":"Não há escolha livre; a regra é aplicar o crime mais grave quando houver.","D":"A subsidiariedade afasta a soma; aplica-se só o crime mais grave.","E":"Correta: trata-se de subsidiariedade expressa."},"fonte":"Código Penal, art. 337","mastigado":"A resposta é a letra E. A frase quer dizer que esse crime é de reserva. Se a mesma conduta se encaixar num crime mais grave, a pessoa responde só por ele. Se não, responde pela subtração ou inutilização de documento.","teSitua":{"termos":[{"termo":"preceito secundário","significado":"a parte do artigo que diz qual é a pena do crime."},{"termo":"subsidiário","significado":"aplicado só quando não houver outro crime mais grave para o mesmo fato."},{"termo":"ressalva","significado":"observação que limita ou condiciona uma regra."}],"exemplo":"Leandro arranca folhas de um processo no balcão. Se fizer isso só para atrapalhar, responde pelo art. 337. Mas se as folhas fizerem parte de um plano maior, punido com pena mais alta, ele responderá apenas pelo crime mais grave."}},{"id":"aut.penal_tj.edital_documentos.0017","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":2,"enunciado":"As condutas descritas no art. 337 do Código Penal, em relação a livro oficial, processo ou documento confiado à custódia de funcionário, são","alternativas":{"A":"rasgar, conspurcar ou violar.","B":"destruir, suprimir ou ocultar.","C":"subtrair ou inutilizar, total ou parcialmente.","D":"extraviar, sonegar ou inutilizar.","E":"falsificar ou alterar."},"gabarito":"C","explicacao":"O art. 337 descreve as condutas de subtrair ou inutilizar, total ou parcialmente, livro oficial, processo ou documento confiado à custódia de funcionário, em razão de ofício, ou de particular em serviço público.","explicacoes":{"A":"Rasgar, conspurcar e violar são verbos do art. 336.","B":"Destruir, suprimir ou ocultar são verbos da supressão de documento (art. 305).","C":"Correta: subtrair ou inutilizar, total ou parcialmente.","D":"Extraviar, sonegar ou inutilizar são verbos do art. 314.","E":"Falsificar ou alterar são verbos dos crimes de falsidade documental (arts. 297 e 298)."},"fonte":"Código Penal, arts. 297, 305, 314, 336 e 337","mastigado":"A resposta é a letra C. O crime consiste em tirar o documento de onde ele está guardado ou estragá-lo, no todo ou em parte. Os outros verbos pertencem a crimes parecidos, mas diferentes.","teSitua":{"termos":[{"termo":"subtrair","significado":"tirar e levar consigo algo que está sob a guarda de outro."},{"termo":"extraviar","significado":"fazer sumir, perder ou desviar do lugar certo."},{"termo":"conspurcar","significado":"sujar, manchar ou pichar algo."}],"exemplo":"A professora Dalva pede que os alunos liguem verbos a crimes. Gabriel acerta: subtrair ou inutilizar processo guardado no cartório é o art. 337; rasgar edital é o art. 336; e extraviar documento que se guarda pelo cargo é o art. 314."}},{"id":"aut.penal_tj.edital_documentos.0018","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":4,"enunciado":"Durante audiência, a parte pega um documento original que acabara de ser juntado aos autos, sob a guarda do escrevente de sala, e o rasga em pedaços. Considerando os crimes do Código Penal, a conduta se amolda ao","alternativas":{"A":"art. 337, subtração ou inutilização de livro ou documento, pois o documento estava confiado à custódia de funcionário.","B":"art. 314, extravio, sonegação ou inutilização de livro ou documento, pois o documento estava nos autos.","C":"art. 336, inutilização de edital, pois o documento era público.","D":"art. 331, desacato, pois a conduta ofende o escrevente.","E":"art. 330, desobediência, pois houve ordem de não tocar nos autos."},"gabarito":"A","explicacao":"O art. 337 pune quem inutiliza, total ou parcialmente, documento confiado à custódia de funcionário em razão de ofício, com reclusão de dois a cinco anos, se o fato não constitui crime mais grave. O art. 314 exige que o próprio agente tenha a guarda em razão do cargo.","explicacoes":{"A":"Correta: a parte inutilizou documento sob custódia do escrevente.","B":"O art. 314 é crime do funcionário que tem a guarda; a parte é particular.","C":"Documento juntado aos autos não é edital afixado.","D":"Não houve ofensa dirigida ao funcionário.","E":"O enunciado não menciona ordem dirigida à parte."},"fonte":"Código Penal, arts. 314 e 337","mastigado":"A resposta é a letra A. O documento já estava no processo, sob os cuidados do escrevente. A parte, que é pessoa comum, rasgou o papel. Esse é o crime de inutilização de documento guardado por servidor.","teSitua":{"termos":[{"termo":"juntado aos autos","significado":"colocado dentro do processo, como parte dele."},{"termo":"escrevente de sala","significado":"servidor que registra e auxilia o juiz durante a audiência."},{"termo":"amolda","significado":"encaixa, corresponde à descrição feita na lei."}],"exemplo":"Na audiência, o advogado entrega o contrato original e o escrevente Ruan o junta ao processo. A ré Cássia, irritada, puxa o papel da mesa e o rasga em pedaços. Ela responde pelo crime de inutilização de documento confiado à custódia de funcionário."}},{"id":"aut.penal_tj.edital_documentos.0019","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":3,"enunciado":"Na penhora de máquinas de uma fábrica, o oficial de justiça afixa em cada uma delas uma etiqueta oficial de identificação, por ordem do juiz. Dias depois, o dono da fábrica arranca as etiquetas para vender as máquinas como se estivessem livres. Quanto à retirada das etiquetas, a conduta corresponde a","alternativas":{"A":"inutilização de edital, porque a etiqueta é aviso ao público.","B":"violação ou inutilização de sinal empregado por ordem de funcionário público para identificar objeto.","C":"subtração de documento confiado à custódia de funcionário.","D":"usurpação de função pública.","E":"conduta atípica, porque as máquinas pertencem ao próprio agente."},"gabarito":"B","explicacao":"O art. 336, segunda parte, pune quem viola ou inutiliza selo ou sinal empregado, por determinação legal ou por ordem de funcionário público, para identificar ou cerrar qualquer objeto, com detenção de um mês a um ano, ou multa. Pouco importa que o objeto pertença ao agente.","explicacoes":{"A":"A etiqueta é sinal de identificação de objeto, não edital afixado.","B":"Correta: é a violação de sinal do art. 336.","C":"A etiqueta não é livro oficial, processo ou documento sob custódia.","D":"O agente não exerceu função pública.","E":"O tipo protege o sinal oficial, ainda que aposto em bem do próprio agente."},"fonte":"Código Penal, art. 336","mastigado":"A resposta é a letra B. As etiquetas foram coladas por ordem do juiz para identificar as máquinas penhoradas. Arrancá-las é violar um sinal oficial, mesmo que as máquinas sejam do próprio dono.","teSitua":{"termos":[{"termo":"penhora","significado":"ato que separa bens do devedor para garantir o pagamento da dívida."},{"termo":"etiqueta oficial de identificação","significado":"marca colocada pela autoridade para mostrar que o bem está vinculado ao processo."},{"termo":"conduta atípica","significado":"comportamento que não se encaixa em nenhum crime previsto na lei."}],"exemplo":"O oficial Bento cola etiquetas da Justiça em três tornos da metalúrgica de Ariel, penhorados numa execução. Ariel arranca as etiquetas e anuncia os tornos na internet como livres. Pela retirada das etiquetas, Ariel comete violação de sinal oficial."}},{"id":"aut.penal_tj.edital_documentos.0020","subtopico":"penal_tj.adm_publica.edital_documentos","tipo":"multipla","dificuldade":2,"enunciado":"Sobre o crime do art. 336 do Código Penal, assinale a alternativa correta.","alternativas":{"A":"A pena é de reclusão, de dois a cinco anos.","B":"Pune quem rasga, inutiliza ou conspurca edital afixado por ordem de funcionário público, e quem viola ou inutiliza selo ou sinal empregado para identificar ou cerrar objeto.","C":"Só se configura se o edital estiver afixado em prédio do Poder Judiciário.","D":"Exige que o agente seja funcionário público.","E":"Só se consuma se houver prejuízo patrimonial à Administração."},"gabarito":"B","explicacao":"O art. 336 tem duas figuras: rasgar ou, de qualquer forma, inutilizar ou conspurcar edital afixado por ordem de funcionário público; e violar ou inutilizar selo ou sinal empregado, por determinação legal ou por ordem de funcionário público, para identificar ou cerrar qualquer objeto. A pena é de detenção, de um mês a um ano, ou multa.","explicacoes":{"A":"A pena é de detenção, de um mês a um ano, ou multa.","B":"Correta: resume as duas figuras do art. 336.","C":"A lei exige que o edital tenha sido afixado por ordem de funcionário público, não que esteja em prédio judicial.","D":"É crime que pode ser praticado por qualquer pessoa, inserido entre os crimes de particular.","E":"O tipo não exige prejuízo patrimonial."},"fonte":"Código Penal, art. 336","mastigado":"A resposta é a letra B. O artigo protege duas coisas: o edital colocado por ordem de servidor, que não pode ser rasgado nem sujado, e os selos ou lacres oficiais, que não podem ser rompidos. Qualquer pessoa pode cometer o crime.","teSitua":{"termos":[{"termo":"conspurca","significado":"suja, mancha ou picha algo."},{"termo":"selo ou sinal","significado":"lacre, carimbo ou marca oficial usada para identificar ou fechar algo."},{"termo":"prejuízo patrimonial","significado":"perda de dinheiro ou de bens."}],"exemplo":"Na mesma semana, o fórum registra dois casos: Vítor pichou o edital de leilão afixado no saguão e Zélia rompeu o lacre de um cofre apreendido. Os dois respondem pelo mesmo artigo, que protege editais e sinais oficiais."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0001","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":2,"enunciado":"Leonel recebe R$ 8.000,00 de um réu, a pretexto de influir no juiz da causa para que este o absolva, sem dizer que o juiz receberia parte do valor. Nos termos do Código Penal, Leonel comete","alternativas":{"A":"tráfico de influência, punido com reclusão de dois a cinco anos, e multa.","B":"exploração de prestígio, punida com reclusão de um a cinco anos, e multa.","C":"corrupção ativa, punida com reclusão de dois a doze anos, e multa.","D":"corrupção passiva, punida com reclusão de dois a doze anos, e multa.","E":"exploração de prestígio, com a pena aumentada de um terço."},"gabarito":"B","explicacao":"O art. 357 pune quem solicita ou recebe dinheiro ou qualquer outra utilidade, a pretexto de influir em juiz, jurado, órgão do Ministério Público, funcionário de justiça, perito, tradutor, intérprete ou testemunha, com reclusão de um a cinco anos, e multa. O aumento de um terço só incide se o agente alega ou insinua que o dinheiro também se destina a essas pessoas.","explicacoes":{"A":"Quando o pretexto é influir em juiz, aplica-se o tipo específico do art. 357, e não o art. 332.","B":"Correta: receber dinheiro a pretexto de influir em juiz é exploração de prestígio.","C":"Leonel não ofereceu vantagem a funcionário.","D":"Leonel não é funcionário público.","E":"O enunciado diz que ele não alegou nem insinuou que o juiz receberia parte do valor."},"fonte":"Código Penal, art. 357, caput e parágrafo único","mastigado":"A resposta é a letra B. Leonel vendeu ao réu uma suposta influência sobre o juiz. Quando a influência prometida é sobre gente da Justiça, como juiz, promotor ou testemunha, o crime é exploração de prestígio, com um a cinco anos de reclusão.","teSitua":{"termos":[{"termo":"a pretexto de influir","significado":"usando como desculpa a promessa de convencer ou pressionar alguém."},{"termo":"exploração de prestígio","significado":"crime de quem pede ou recebe dinheiro dizendo que vai influenciar juiz, promotor, testemunha e outros."},{"termo":"tráfico de influência","significado":"crime de quem cobra vantagem dizendo que pode influenciar um servidor."}],"exemplo":"Leonel diz a Otávio, réu num processo por estelionato, que joga futebol com o juiz e que, por R$ 8.000,00, \\"resolve tudo\\". Otávio paga. O juiz nunca soube de nada. Leonel responde por exploração de prestígio."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0002","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":4,"enunciado":"Mirela solicita R$ 2.000,00 a uma parte, a pretexto de influir no escrevente responsável pelo processo para que ele adiante a expedição de um alvará. Considerando o princípio da especialidade, Mirela comete","alternativas":{"A":"tráfico de influência (art. 332), porque o escrevente é funcionário público.","B":"corrupção ativa (art. 333), porque a vantagem se destina ao escrevente.","C":"advocacia administrativa (art. 321).","D":"concussão (art. 316), porque exigiu vantagem.","E":"exploração de prestígio (art. 357), porque o escrevente é funcionário de justiça."},"gabarito":"E","explicacao":"O art. 357 menciona expressamente o funcionário de justiça entre as pessoas em quem o agente diz influir. Por ser norma especial em relação ao tráfico de influência (art. 332), prevalece quando o pretexto é influir em funcionário de justiça.","explicacoes":{"A":"O art. 332 é a regra geral; quando o pretexto envolve funcionário de justiça, aplica-se o art. 357.","B":"Mirela não ofereceu vantagem ao escrevente; pediu-a à parte.","C":"Mirela não é funcionária patrocinando interesse privado perante a Administração.","D":"Mirela não é funcionária pública e solicitou, não exigiu, a vantagem.","E":"Correta: o funcionário de justiça está no rol do art. 357."},"fonte":"Código Penal, arts. 332 e 357","mastigado":"A resposta é a letra E. O escrevente é um servidor da Justiça, e a lei tem um crime próprio para quem vende influência sobre pessoas da Justiça: a exploração de prestígio. Esse crime especial prevalece sobre o tráfico de influência.","teSitua":{"termos":[{"termo":"princípio da especialidade","significado":"regra pela qual a lei mais específica prevalece sobre a lei geral."},{"termo":"alvará","significado":"documento expedido pelo juiz que autoriza algo, como sacar um dinheiro depositado."},{"termo":"funcionário de justiça","significado":"servidor que trabalha no Poder Judiciário, como o escrevente e o oficial de justiça."},{"termo":"advocacia administrativa","significado":"crime do servidor que usa o cargo para defender interesse particular perante a Administração."}],"exemplo":"Mirela, que frequenta o fórum, diz a Danilo que conhece o escrevente que cuida do seu inventário e que, por R$ 2.000,00, o alvará sai na semana seguinte. Danilo recusa e denuncia. Mirela responde por exploração de prestígio, já que o escrevente é funcionário de justiça."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0003","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"certo_errado","dificuldade":2,"enunciado":"Na exploração de prestígio, as penas aumentam-se de um terço se o agente alega ou insinua que o dinheiro ou utilidade também se destina ao juiz, jurado, órgão do Ministério Público, funcionário de justiça, perito, tradutor, intérprete ou testemunha.","gabarito":"C","explicacao":"É a regra do parágrafo único do art. 357 do Código Penal.","fonte":"Código Penal, art. 357, parágrafo único","mastigado":"Certo. Quem vende influência sobre pessoas da Justiça já comete crime. Se ainda diz ou dá a entender que parte do dinheiro vai para o juiz, o promotor ou outra dessas pessoas, a pena aumenta um terço.","teSitua":{"termos":[{"termo":"alega ou insinua","significado":"afirma claramente ou dá a entender."},{"termo":"utilidade","significado":"qualquer vantagem ou benefício, mesmo que não seja dinheiro."},{"termo":"órgão do Ministério Público","significado":"o promotor ou procurador que atua no processo."}],"exemplo":"Fábio cobra R$ 10.000,00 de um réu e diz que \\"metade é para o promotor pedir a absolvição\\". O promotor nada sabe. Como Fábio insinuou que o dinheiro iria também para o promotor, sua pena por exploração de prestígio aumenta de um terço."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0004","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"certo_errado","dificuldade":3,"enunciado":"Na exploração de prestígio, a pena é aumentada da metade se o agente alega ou insinua que o dinheiro também se destina a qualquer das pessoas mencionadas no tipo.","gabarito":"E","explicacao":"O parágrafo único do art. 357 prevê aumento de um terço. O aumento da metade é o do tráfico de influência (art. 332, parágrafo único).","fonte":"Código Penal, arts. 332, parágrafo único, e 357, parágrafo único","mastigado":"Errado. Na exploração de prestígio o aumento é de um terço. O aumento pela metade é do tráfico de influência, o crime parecido que envolve servidores públicos em geral.","teSitua":{"termos":[{"termo":"alega ou insinua","significado":"afirma claramente ou dá a entender."},{"termo":"exploração de prestígio","significado":"crime de quem pede ou recebe dinheiro dizendo que vai influenciar juiz, promotor, testemunha e outros."}],"exemplo":"Na revisão, Paula confunde os aumentos e o professor Jorge corrige: se o golpista diz que o dinheiro vai também para o juiz, a pena da exploração de prestígio sobe um terço; se diz que vai para um fiscal da prefeitura, o tráfico de influência sobe metade."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0005","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":3,"enunciado":"O art. 357 do Código Penal menciona expressamente as pessoas em quem o agente diz influir. NÃO está entre elas","alternativas":{"A":"o jurado.","B":"o órgão do Ministério Público.","C":"o delegado de polícia.","D":"o intérprete.","E":"a testemunha."},"gabarito":"C","explicacao":"O art. 357 menciona juiz, jurado, órgão do Ministério Público, funcionário de justiça, perito, tradutor, intérprete ou testemunha. O delegado de polícia não está no rol; o pretexto de influir em delegado se enquadra, em regra, no tráfico de influência (art. 332).","explicacoes":{"A":"O jurado está no rol do art. 357.","B":"O órgão do Ministério Público está no rol do art. 357.","C":"Correta: o delegado de polícia não está no rol do art. 357.","D":"O intérprete está no rol do art. 357.","E":"A testemunha está no rol do art. 357."},"fonte":"Código Penal, arts. 332 e 357","mastigado":"A resposta é a letra C. A lista da exploração de prestígio traz pessoas ligadas ao processo judicial: juiz, jurado, promotor, servidor da Justiça, perito, tradutor, intérprete e testemunha. O delegado não aparece; vender influência sobre ele é, em regra, tráfico de influência.","teSitua":{"termos":[{"termo":"jurado","significado":"cidadão sorteado para julgar crimes no Tribunal do Júri."},{"termo":"órgão do Ministério Público","significado":"o promotor ou procurador que atua no processo."},{"termo":"intérprete","significado":"pessoa que traduz oralmente a fala de quem não fala português ou usa Libras."}],"exemplo":"Renato cobra de um investigado dizendo que conhece o delegado: tráfico de influência. Já Glória cobra de um réu dizendo que conhece um dos jurados do júri: exploração de prestígio. A diferença está em quem é a pessoa que supostamente seria influenciada."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0006","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":2,"enunciado":"Os verbos que descrevem a conduta do crime de exploração de prestígio (art. 357 do Código Penal) são","alternativas":{"A":"solicitar ou receber.","B":"solicitar, exigir, cobrar ou obter.","C":"oferecer ou prometer.","D":"dar, oferecer ou prometer.","E":"exigir, apenas."},"gabarito":"A","explicacao":"O art. 357 pune quem solicita ou recebe dinheiro ou qualquer outra utilidade, a pretexto de influir nas pessoas que menciona.","explicacoes":{"A":"Correta: solicitar ou receber.","B":"São os verbos do tráfico de influência (art. 332).","C":"São os verbos da corrupção ativa (art. 333).","D":"São os verbos da corrupção de testemunha (art. 343).","E":"Exigir é verbo da concussão (art. 316)."},"fonte":"Código Penal, arts. 316, 332, 333, 343 e 357","mastigado":"A resposta é a letra A. Na exploração de prestígio a pessoa pede ou recebe dinheiro ou outra vantagem, dizendo que vai influenciar alguém da Justiça. Os outros verbos pertencem a crimes vizinhos.","teSitua":{"termos":[{"termo":"solicitar","significado":"pedir algo a outra pessoa."},{"termo":"exploração de prestígio","significado":"crime de quem pede ou recebe dinheiro dizendo que vai influenciar juiz, promotor, testemunha e outros."}],"exemplo":"Para memorizar, Aline anota: exploração de prestígio, pedir ou receber; tráfico de influência, pedir, exigir, cobrar ou obter; corrupção ativa, oferecer ou prometer. Na prova, ela acerta a questão sobre os verbos do art. 357."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0007","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"certo_errado","dificuldade":2,"enunciado":"A exploração de prestígio é punida com reclusão, de dois a doze anos, e multa.","gabarito":"E","explicacao":"O art. 357 do CP prevê reclusão, de um a cinco anos, e multa, aumentada de um terço se o agente alega ou insinua que o dinheiro ou utilidade também se destina às pessoas mencionadas no tipo. Dois a doze anos é a pena da corrupção ativa e da corrupção passiva.","fonte":"Código Penal, art. 357, caput","mastigado":"Errado. A pena da exploração de prestígio é de um a cinco anos de reclusão, e multa. Dois a doze anos é a pena das corrupções ativa e passiva, que são crimes diferentes.","teSitua":{"termos":[{"termo":"exploração de prestígio","significado":"crime de quem pede ou recebe dinheiro dizendo que vai influenciar juiz, promotor, testemunha e outros."},{"termo":"reclusão","significado":"tipo mais grave de pena de prisão, que pode começar em regime fechado."}],"exemplo":"Condenado por receber R$ 3.000,00 a pretexto de influir num perito judicial, Nestor recebe pena de dois anos de reclusão e multa, dentro do intervalo de um a cinco anos previsto para a exploração de prestígio."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0008","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":3,"enunciado":"Sobre a diferença entre o tráfico de influência (art. 332) e a exploração de prestígio (art. 357), é correto afirmar que","alternativas":{"A":"os dois crimes têm a mesma pena.","B":"o tráfico de influência só pode ser praticado por funcionário público.","C":"a exploração de prestígio exige que a vantagem seja efetivamente entregue ao juiz.","D":"na exploração de prestígio o pretexto é influir em juiz, jurado, órgão do Ministério Público, funcionário de justiça, perito, tradutor, intérprete ou testemunha.","E":"no tráfico de influência o aumento por insinuar que a vantagem se destina ao funcionário é de um terço."},"gabarito":"D","explicacao":"O art. 357 é especial: o pretexto é influir em pessoas ligadas à administração da justiça. O art. 332 trata de ato de funcionário público em geral, com reclusão de dois a cinco anos e aumento da metade. O art. 357 tem reclusão de um a cinco anos e aumento de um terço.","explicacoes":{"A":"O art. 332 prevê reclusão de dois a cinco anos; o art. 357, de um a cinco anos.","B":"Os dois crimes podem ser praticados por qualquer pessoa.","C":"Basta solicitar ou receber a pretexto de influir; a entrega ao juiz não é exigida.","D":"Correta: é o rol de pessoas do art. 357.","E":"No tráfico de influência o aumento é da metade."},"fonte":"Código Penal, arts. 332 e 357","mastigado":"A resposta é a letra D. Os dois crimes são parecidos: alguém vende uma influência que diz ter. Se a influência prometida é sobre gente da Justiça, como juiz, promotor ou testemunha, o crime é exploração de prestígio.","teSitua":{"termos":[{"termo":"tráfico de influência","significado":"crime de quem cobra vantagem dizendo que pode influenciar um servidor."},{"termo":"insinuar","significado":"dar a entender, sem dizer claramente."},{"termo":"funcionário de justiça","significado":"servidor que trabalha no Poder Judiciário, como o escrevente e o oficial de justiça."}],"exemplo":"Edgar pede dinheiro dizendo que convence o fiscal da Receita: tráfico de influência. Sua irmã Clara pede dinheiro dizendo que convence a testemunha de um processo: exploração de prestígio. Os dois vendem influência, mas sobre pessoas diferentes."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0009","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":3,"enunciado":"Por sentença criminal, um médico recebeu a pena de proibição temporária do exercício da profissão. Durante o prazo da proibição, ele continua atendendo pacientes em seu consultório. Nos termos do Código Penal, a conduta configura","alternativas":{"A":"desobediência a decisão judicial sobre perda ou suspensão de direito, punida com detenção de três meses a dois anos, ou multa.","B":"desobediência comum, punida com detenção de quinze dias a seis meses, e multa.","C":"exercício funcional ilegalmente prolongado, punido com detenção de quinze dias a um mês, ou multa.","D":"usurpação de função pública, punida com detenção de três meses a dois anos, e multa.","E":"conduta atípica, pois a medicina é atividade privada."},"gabarito":"A","explicacao":"O art. 359 pune quem exerce função, atividade, direito, autoridade ou múnus, de que foi suspenso ou privado por decisão judicial, com detenção de três meses a dois anos, ou multa.","explicacoes":{"A":"Correta: exercer atividade de que foi suspenso por decisão judicial é o crime do art. 359.","B":"O art. 359 é específico para o descumprimento de decisão judicial que suspende ou priva de direito ou atividade.","C":"O art. 324 trata de funcionário público que continua no cargo após exoneração ou suspensão; aqui se trata de atividade profissional suspensa por decisão judicial.","D":"O médico não exerce função pública.","E":"O art. 359 alcança qualquer atividade de que o agente foi suspenso ou privado por decisão judicial."},"fonte":"Código Penal, art. 359","mastigado":"A resposta é a letra A. O juiz proibiu o médico de trabalhar por um tempo, e ele continuou atendendo. Exercer uma atividade da qual a Justiça o afastou é crime próprio, com detenção de três meses a dois anos, ou multa.","teSitua":{"termos":[{"termo":"proibição temporária do exercício da profissão","significado":"pena que impede a pessoa de trabalhar na sua profissão por um período."},{"termo":"sentença criminal","significado":"decisão do juiz que julga o réu em processo por crime."},{"termo":"exercício funcional ilegalmente prolongado","significado":"continuar exercendo a função depois de perder o direito a ela."}],"exemplo":"Condenado por um erro grave numa cirurgia, o doutor Ítalo fica proibido pelo juiz de exercer a medicina por um ano. Dois meses depois, volta a atender no consultório. Ele responde pelo crime de desobediência a decisão judicial sobre suspensão de direito."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0010","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"certo_errado","dificuldade":3,"enunciado":"Configura o crime do art. 359 do Código Penal o exercício de atividade de que o agente foi suspenso por decisão meramente administrativa, sem participação do Poder Judiciário.","gabarito":"E","explicacao":"O art. 359 exige que a suspensão ou privação da função, atividade, direito, autoridade ou múnus decorra de decisão judicial.","fonte":"Código Penal, art. 359","mastigado":"Errado. O crime só existe quando quem suspendeu ou tirou o direito foi um juiz. Se a suspensão veio de um órgão administrativo, sem decisão judicial, esse crime específico não se configura.","teSitua":{"termos":[{"termo":"decisão meramente administrativa","significado":"decisão tomada por órgão da Administração, e não por um juiz."},{"termo":"Poder Judiciário","significado":"conjunto dos juízes e tribunais que julgam os processos."}],"exemplo":"O conselho profissional suspende administrativamente o registro do engenheiro Davi por três meses. Davi continua assinando projetos. Como a suspensão não veio de decisão judicial, ele não comete o crime do art. 359, embora possa responder por outras infrações."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0011","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do Código Penal, quem exerce função, atividade, direito, autoridade ou múnus de que foi suspenso ou privado por decisão judicial está sujeito à pena de","alternativas":{"A":"detenção, de quinze dias a seis meses, e multa.","B":"detenção, de três meses a dois anos, ou multa.","C":"reclusão, de um a cinco anos, e multa.","D":"detenção, de quinze dias a um mês, ou multa.","E":"reclusão, de dois a cinco anos, e multa."},"gabarito":"B","explicacao":"O art. 359 prevê detenção, de três meses a dois anos, ou multa.","explicacoes":{"A":"É a pena da desobediência (art. 330).","B":"Correta: é a pena do art. 359.","C":"É a pena da exploração de prestígio (art. 357).","D":"É a pena do exercício funcional ilegalmente antecipado ou prolongado (art. 324).","E":"É a pena do tráfico de influência (art. 332)."},"fonte":"Código Penal, arts. 330, 332, 357 e 359","mastigado":"A resposta é a letra B. Descumprir uma decisão judicial que suspendeu ou tirou um direito, uma atividade ou um encargo tem pena de três meses a dois anos de detenção, ou multa.","teSitua":{"termos":[{"termo":"múnus","significado":"encargo ou dever que alguém recebe por lei ou ordem do juiz, como o de tutor."},{"termo":"privado","significado":"que perdeu, que teve tirado um direito."}],"exemplo":"A juíza suspende Júlio do exercício da curatela da mãe por suspeita de desvio de dinheiro. Mesmo assim, ele continua sacando a aposentadoria dela como curador. Júlio responde pelo crime do art. 359, com detenção de três meses a dois anos, ou multa."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0012","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"certo_errado","dificuldade":2,"enunciado":"O art. 359 do Código Penal alcança o exercício de função, atividade, direito, autoridade ou múnus de que o agente foi suspenso ou privado por decisão judicial.","gabarito":"C","explicacao":"É a descrição do art. 359, que protege a autoridade das decisões judiciais que suspendem ou privam alguém de direitos e encargos.","fonte":"Código Penal, art. 359","mastigado":"Certo. A lei usa uma lista ampla: função, atividade, direito, autoridade ou encargo. Se um juiz suspendeu ou tirou da pessoa qualquer dessas coisas e ela continua exercendo, comete o crime.","teSitua":{"termos":[{"termo":"múnus","significado":"encargo ou dever que alguém recebe por lei ou ordem do juiz, como o de tutor."},{"termo":"suspenso ou privado","significado":"afastado por um tempo ou de forma definitiva."}],"exemplo":"Removido pelo juiz do cargo de inventariante, Sandro continua assinando recibos e vendendo bens da herança como se ainda fosse o administrador. Ele exerce múnus de que foi privado por decisão judicial e comete o crime do art. 359."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0013","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":3,"enunciado":"Fred pede a um réu que lhe empreste por um mês uma casa de praia, a pretexto de influir em um dos jurados que julgarão o caso. O réu recusa. Nos termos do Código Penal, é correto afirmar que","alternativas":{"A":"não há crime, porque o réu recusou o pedido.","B":"não há crime, porque o objeto pedido não é dinheiro.","C":"há tráfico de influência, porque o jurado é funcionário público.","D":"há corrupção de testemunha, punida com reclusão de três a quatro anos, e multa.","E":"há exploração de prestígio, porque o tipo abrange solicitar qualquer outra utilidade, a pretexto de influir em jurado."},"gabarito":"E","explicacao":"O art. 357 pune quem solicita ou recebe dinheiro ou qualquer outra utilidade, a pretexto de influir em juiz, jurado, órgão do Ministério Público, funcionário de justiça, perito, tradutor, intérprete ou testemunha. A solicitação basta, e a vantagem não precisa ser dinheiro.","explicacoes":{"A":"O verbo solicitar já realiza o tipo; a recusa do réu é irrelevante.","B":"O tipo menciona \\"qualquer outra utilidade\\".","C":"O jurado está no rol do art. 357, norma especial.","D":"Fred não ofereceu vantagem a testemunha.","E":"Correta: é exploração de prestígio."},"fonte":"Código Penal, art. 357, caput","mastigado":"A resposta é a letra E. Fred pediu um favor ao réu dizendo que convenceria um jurado. Só pedir já é crime, e o pedido não precisa ser dinheiro: emprestar uma casa de praia também é vantagem. Isso é exploração de prestígio.","teSitua":{"termos":[{"termo":"jurado","significado":"cidadão sorteado para julgar crimes no Tribunal do Júri."},{"termo":"utilidade","significado":"qualquer vantagem ou benefício, mesmo que não seja dinheiro."},{"termo":"corrupção de testemunha","significado":"crime de dar, oferecer ou prometer vantagem a testemunha para que minta."}],"exemplo":"Fred diz ao réu Maurício que é vizinho de uma jurada e que, se puder passar o mês de janeiro na casa de praia dele, garante um voto favorável. Maurício recusa e avisa o advogado. Fred já cometeu exploração de prestígio."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0014","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":3,"enunciado":"Um inventariante, removido do encargo por decisão do juiz, continua a receber aluguéis e a dar quitação em nome do espólio. Nos termos do Código Penal, a conduta corresponde a","alternativas":{"A":"usurpação de função pública.","B":"desobediência comum (art. 330).","C":"exercício de múnus de que foi privado por decisão judicial (art. 359).","D":"exercício arbitrário das próprias razões.","E":"exercício funcional ilegalmente prolongado (art. 324)."},"gabarito":"C","explicacao":"O art. 359 pune quem exerce função, atividade, direito, autoridade ou múnus, de que foi suspenso ou privado por decisão judicial, com detenção de três meses a dois anos, ou multa. O encargo de inventariante é múnus atribuído pelo juiz.","explicacoes":{"A":"O inventariante não exerce função pública.","B":"Há tipo específico para quem exerce múnus de que foi privado por decisão judicial.","C":"Correta: é o crime do art. 359.","D":"Ele não busca satisfazer pretensão própria pelas próprias mãos.","E":"O art. 324 é crime de funcionário público, e a remoção decorreu de decisão judicial."},"fonte":"Código Penal, art. 359","mastigado":"A resposta é a letra C. O juiz tirou dele o encargo de cuidar dos bens da herança, mas ele continuou agindo como inventariante. Exercer um encargo do qual a Justiça o afastou é o crime de desobediência a decisão judicial sobre perda de direito.","teSitua":{"termos":[{"termo":"inventariante","significado":"pessoa nomeada pelo juiz para administrar os bens da herança até a partilha."},{"termo":"dar quitação","significado":"declarar que recebeu um pagamento e que a dívida está paga."},{"termo":"espólio","significado":"conjunto de bens, direitos e dívidas deixados por quem morreu."},{"termo":"múnus","significado":"encargo ou dever que alguém recebe por lei ou ordem do juiz, como o de tutor."}],"exemplo":"Removido pelo juiz por não prestar contas, o inventariante Silas continua cobrando os aluguéis dos imóveis da mãe falecida e assinando recibos. Os irmãos avisam o juiz. Silas responde pelo crime do art. 359."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0015","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"certo_errado","dificuldade":2,"enunciado":"Comete exploração de prestígio quem recebe dinheiro a pretexto de influir em jurado.","gabarito":"C","explicacao":"O art. 357 menciona expressamente o jurado entre as pessoas em quem o agente diz influir, ao lado de juiz, órgão do Ministério Público, funcionário de justiça, perito, tradutor, intérprete e testemunha.","fonte":"Código Penal, art. 357, caput","mastigado":"Certo. O jurado está na lista do crime. Quem recebe dinheiro dizendo que vai convencer um jurado a votar de certo jeito comete exploração de prestígio.","teSitua":{"termos":[{"termo":"jurado","significado":"cidadão sorteado para julgar crimes no Tribunal do Júri."},{"termo":"a pretexto de influir","significado":"usando como desculpa a promessa de convencer ou pressionar alguém."}],"exemplo":"A família de um réu paga R$ 6.000,00 a Gláucio, que diz ser primo de um dos jurados e promete garantir a absolvição. Gláucio nem conhece os jurados. Ele responde por exploração de prestígio."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0016","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"certo_errado","dificuldade":4,"enunciado":"Quem solicita vantagem a pretexto de influir em perito judicial comete tráfico de influência (art. 332 do Código Penal), punido com reclusão de dois a cinco anos, e multa.","gabarito":"E","explicacao":"O perito está no rol do art. 357 (exploração de prestígio), norma especial que prevalece sobre o art. 332. A pena é de reclusão, de um a cinco anos, e multa.","fonte":"Código Penal, arts. 332 e 357","mastigado":"Errado. O perito é uma das pessoas da lista da exploração de prestígio. Por isso, quem pede vantagem dizendo que vai influenciar o perito comete esse crime, e não o tráfico de influência.","teSitua":{"termos":[{"termo":"perito judicial","significado":"especialista nomeado pelo juiz para examinar algo e dar opinião técnica."},{"termo":"tráfico de influência","significado":"crime de quem cobra vantagem dizendo que pode influenciar um servidor."}],"exemplo":"Jonas pede R$ 4.000,00 a uma empresa dizendo que conhece o perito contábil do processo e que o laudo sairá favorável. O caso é enquadrado como exploração de prestígio, porque o perito está no rol do art. 357."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0017","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":2,"enunciado":"Considerando a exploração de prestígio, o tráfico de influência e a desobediência a decisão judicial sobre perda ou suspensão de direito, assinale a alternativa que associa corretamente o crime à sua pena.","alternativas":{"A":"Exploração de prestígio: reclusão, de dois a cinco anos, e multa.","B":"Desobediência a decisão judicial sobre perda ou suspensão de direito: reclusão, de um a cinco anos, e multa.","C":"Tráfico de influência: reclusão, de um a cinco anos, e multa.","D":"Exploração de prestígio: reclusão, de um a cinco anos, e multa.","E":"Desobediência a decisão judicial sobre perda ou suspensão de direito: detenção, de quinze dias a seis meses, e multa."},"gabarito":"D","explicacao":"Art. 357 (exploração de prestígio): reclusão, de um a cinco anos, e multa. Art. 359: detenção, de três meses a dois anos, ou multa. Art. 332 (tráfico de influência): reclusão, de dois a cinco anos, e multa. Art. 330 (desobediência): detenção, de quinze dias a seis meses, e multa.","explicacoes":{"A":"Dois a cinco anos é a pena do tráfico de influência.","B":"O art. 359 prevê detenção de três meses a dois anos, ou multa.","C":"O tráfico de influência tem reclusão de dois a cinco anos, e multa.","D":"Correta: é a pena do art. 357.","E":"Quinze dias a seis meses, e multa, é a pena da desobediência comum (art. 330)."},"fonte":"Código Penal, arts. 330, 332, 357 e 359","mastigado":"A resposta é a letra D. A exploração de prestígio tem reclusão de um a cinco anos, e multa. Ela começa com pena mínima menor que a do tráfico de influência, que vai de dois a cinco anos.","teSitua":{"termos":[{"termo":"exploração de prestígio","significado":"crime de quem pede ou recebe dinheiro dizendo que vai influenciar juiz, promotor, testemunha e outros."},{"termo":"suspensão de direito","significado":"afastamento temporário de um direito por decisão judicial."}],"exemplo":"Revisando, Teo percebe uma curiosidade: vender influência sobre um fiscal (tráfico de influência) tem pena mínima de dois anos, enquanto vender influência sobre um juiz (exploração de prestígio) tem pena mínima de um ano, ambas com máximo de cinco anos."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0018","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":3,"enunciado":"Uma pessoa suspensa por decisão judicial do exercício de uma atividade continua a exercê-la. Em relação à desobediência do art. 330 do Código Penal, é correto afirmar que","alternativas":{"A":"aplica-se a desobediência comum, porque toda decisão judicial é ordem de funcionário público.","B":"aplica-se o art. 359, crime específico para o exercício de função, atividade, direito, autoridade ou múnus de que o agente foi suspenso ou privado por decisão judicial.","C":"aplicam-se os dois crimes, somando-se as penas.","D":"não há crime, pois o descumprimento de decisão judicial só gera multa processual.","E":"aplica-se o art. 359 apenas se o agente for funcionário público."},"gabarito":"B","explicacao":"O art. 359 é norma específica para quem exerce função, atividade, direito, autoridade ou múnus de que foi suspenso ou privado por decisão judicial, e prevalece sobre a desobediência genérica do art. 330.","explicacoes":{"A":"A existência de tipo específico afasta a desobediência genérica.","B":"Correta: aplica-se o art. 359.","C":"Pelo princípio da especialidade, aplica-se apenas o tipo específico.","D":"O art. 359 prevê crime para essa conduta.","E":"O art. 359 pode ser praticado por qualquer pessoa suspensa ou privada por decisão judicial."},"fonte":"Código Penal, arts. 330 e 359","mastigado":"A resposta é a letra B. Existe um crime feito sob medida para quem continua exercendo uma atividade da qual o juiz o afastou. Por ser mais específico, ele vale no lugar da desobediência comum.","teSitua":{"termos":[{"termo":"desobediência","significado":"crime de quem deixa de cumprir ordem legal de servidor público."},{"termo":"multa processual","significado":"valor que o juiz manda pagar como punição dentro do processo."},{"termo":"múnus","significado":"encargo ou dever que alguém recebe por lei ou ordem do juiz, como o de tutor."}],"exemplo":"O juiz suspende Kléber do direito de administrar a empresa da família durante o processo. Kléber continua assinando contratos como administrador. Ele responde pelo crime do art. 359, e não pela desobediência comum do art. 330."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0019","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":3,"enunciado":"Para obter dinheiro de uma ré, Ulisses diz que o promotor do caso é seu amigo e que metade dos R$ 6.000,00 cobrados será entregue a ele, para que deixe de recorrer. A ré paga. Nos termos do Código Penal, Ulisses responde por","alternativas":{"A":"exploração de prestígio, com a pena aumentada de um terço.","B":"exploração de prestígio, com a pena aumentada da metade.","C":"tráfico de influência, com a pena aumentada da metade.","D":"corrupção ativa, porque a vantagem seria destinada ao promotor.","E":"estelionato, por ter enganado a ré."},"gabarito":"A","explicacao":"O art. 357 menciona o órgão do Ministério Público. Ao alegar que o dinheiro também se destina ao promotor, Ulisses faz incidir o parágrafo único, que aumenta as penas de um terço.","explicacoes":{"A":"Correta: exploração de prestígio com aumento de um terço.","B":"No art. 357 o aumento é de um terço; metade é o aumento do art. 332.","C":"O promotor é órgão do Ministério Público, previsto no art. 357.","D":"Ulisses não ofereceu vantagem ao promotor; recebeu da ré.","E":"Há tipo específico para quem recebe dinheiro a pretexto de influir em órgão do Ministério Público (art. 357)."},"fonte":"Código Penal, art. 357, caput e parágrafo único","mastigado":"A resposta é a letra A. Ulisses vendeu uma influência sobre o promotor e ainda disse que parte do dinheiro iria para ele. Isso é exploração de prestígio, com a pena aumentada de um terço por causa dessa alegação.","teSitua":{"termos":[{"termo":"promotor","significado":"membro do Ministério Público que atua na acusação do processo criminal."},{"termo":"deixe de recorrer","significado":"não apresente recurso contra a decisão."},{"termo":"estelionato","significado":"crime de obter vantagem enganando alguém."}],"exemplo":"Absolvida em primeira instância, a ré Vilma teme o recurso da acusação. Ulisses cobra R$ 6.000,00 dizendo que metade é para o promotor, seu amigo, \\"esquecer o prazo\\". O promotor nada sabe. Ulisses responde por exploração de prestígio com aumento de um terço."}},{"id":"aut.penal_tj.exploracao_prestigio_desobediencia.0020","subtopico":"penal_tj.adm_justica.exploracao_prestigio_desobediencia","tipo":"multipla","dificuldade":3,"enunciado":"Sobre o crime previsto no art. 359 do Código Penal (desobediência a decisão judicial sobre perda ou suspensão de direito), assinale a alternativa correta.","alternativas":{"A":"Só pode ser praticado por funcionário público.","B":"Aplica-se também à suspensão determinada por decisão administrativa.","C":"É punido com reclusão, de um a cinco anos, e multa.","D":"Abrange o exercício de autoridade ou múnus de que o agente foi privado por decisão judicial.","E":"Limita-se ao exercício de função pública, não alcançando atividades privadas."},"gabarito":"D","explicacao":"O art. 359 pune quem exerce função, atividade, direito, autoridade ou múnus, de que foi suspenso ou privado por decisão judicial, com detenção de três meses a dois anos, ou multa. Qualquer pessoa pode praticá-lo, e a suspensão ou privação deve vir de decisão judicial.","explicacoes":{"A":"O tipo não exige a condição de funcionário público.","B":"A lei exige decisão judicial.","C":"A pena é de detenção, de três meses a dois anos, ou multa.","D":"Correta: autoridade e múnus estão no rol do art. 359.","E":"O tipo menciona também atividade e direito, o que inclui atividades privadas."},"fonte":"Código Penal, art. 359","mastigado":"A resposta é a letra D. O crime vale para quem continua exercendo qualquer coisa que o juiz tirou ou suspendeu: uma função, uma atividade, um direito, uma autoridade ou um encargo. Não é preciso ser servidor público.","teSitua":{"termos":[{"termo":"múnus","significado":"encargo ou dever que alguém recebe por lei ou ordem do juiz, como o de tutor."},{"termo":"decisão administrativa","significado":"decisão tomada por órgão da Administração, e não por um juiz."},{"termo":"atividades privadas","significado":"trabalhos e negócios particulares, que não são do poder público."}],"exemplo":"Destituída pelo juiz da tutela do sobrinho, Rosa continua matriculando o menino na escola e movimentando a pensão dele como se ainda fosse tutora. Ela exerce múnus de que foi privada por decisão judicial e responde pelo crime do art. 359."}},{"id":"aut.penal_tj.falsa_identidade_certames.0001","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"multipla","dificuldade":2,"enunciado":"No balcão de uma vara, um homem se apresenta verbalmente como sendo o advogado de uma das partes, dizendo um nome que não é o seu, para obter vista dos autos e copiar documentos de interesse de um amigo. Ele não exibe documento algum. De acordo com o Código Penal, a conduta, se não constituir elemento de crime mais grave, configura","alternativas":{"A":"uso de documento falso.","B":"uso, como próprio, de documento de identidade alheia.","C":"falsa identidade.","D":"falsidade ideológica.","E":"fraude em certames de interesse público."},"gabarito":"C","explicacao":"O art. 307 pune quem se atribui ou atribui a terceiro falsa identidade para obter vantagem, em proveito próprio ou alheio, ou para causar dano a outrem, com detenção de três meses a um ano, ou multa, se o fato não constitui elemento de crime mais grave. Não se exige documento.","explicacoes":{"A":"Ele não usou papel falsificado algum; apenas se atribuiu identidade falsa.","B":"O art. 308 exige o uso de documento de identidade alheia, o que não houve.","C":"Correta: atribuir-se falsa identidade para obter vantagem é o crime do art. 307.","D":"Não houve inserção de declaração falsa em documento.","E":"Não se trata de conteúdo sigiloso de concurso ou exame."},"fonte":"Código Penal, art. 307","mastigado":"A resposta é a letra C. O homem mentiu sobre quem era, só com palavras, para conseguir uma vantagem para o amigo. Isso é falsa identidade. Como ele não mostrou nenhum papel, não é uso de documento falso nem uso de documento de outra pessoa.","teSitua":{"termos":[{"termo":"vista dos autos","significado":"acesso ao processo para lê-lo e examinar seus documentos."},{"termo":"se apresenta verbalmente","significado":"diz de si mesmo, só com palavras, quem é, sem mostrar documento."},{"termo":"elemento de crime mais grave","significado":"parte de um crime mais sério, que absorve a conduta menor."}],"exemplo":"Otávio chega ao cartório da 5ª Vara e diz à escrevente Paula que é o doutor Marcelo, advogado do réu. Paula entrega o processo e Otávio fotografa documentos para um amigo. Depois se descobre que ele não é advogado nem se chama Marcelo. Otávio responde por falsa identidade."}},{"id":"aut.penal_tj.falsa_identidade_certames.0002","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"certo_errado","dificuldade":2,"enunciado":"O crime de falsa identidade só pode ser praticado por quem atribui a si mesmo identidade falsa; atribuir falsa identidade a terceiro não configura o crime.","gabarito":"E","explicacao":"O art. 307 do CP descreve a conduta de atribuir-se ou atribuir a terceiro falsa identidade, com a finalidade de obter vantagem, em proveito próprio ou alheio, ou de causar dano a outrem. As duas condutas estão no tipo.","fonte":"Código Penal, art. 307","mastigado":"Errado. A lei pune quem mente sobre a própria identidade e também quem mente sobre a identidade de outra pessoa. Basta que a mentira sirva para obter vantagem ou causar dano a alguém.","teSitua":{"termos":[{"termo":"atribui falsa identidade a terceiro","significado":"diz que outra pessoa é alguém que ela não é."},{"termo":"configura o crime","significado":"se encaixa na descrição do crime feita pela lei."}],"exemplo":"Na portaria do fórum, Lúcio apresenta o amigo Caio como se fosse o perito nomeado no processo, para que Caio entre na sala reservada e veja os autos. Lúcio responde por falsa identidade, porque atribuiu a outra pessoa uma identidade falsa para obter vantagem."}},{"id":"aut.penal_tj.falsa_identidade_certames.0003","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"certo_errado","dificuldade":3,"enunciado":"A falsa identidade é crime expressamente subsidiário: sua pena só se aplica se o fato não constitui elemento de crime mais grave.","gabarito":"C","explicacao":"O preceito secundário do art. 307 prevê detenção, de três meses a um ano, ou multa, \\"se o fato não constitui elemento de crime mais grave\\". Trata-se de subsidiariedade expressa, também presente no art. 308.","fonte":"Código Penal, art. 307","mastigado":"Certo. A própria lei diz que a falsa identidade só é punida sozinha quando a mentira não faz parte de um crime mais sério. Se ela for só um passo de um golpe maior, a pessoa responde pelo crime maior.","teSitua":{"termos":[{"termo":"subsidiário","significado":"aplicado só quando não houver outro crime mais grave que abranja o mesmo fato."}],"exemplo":"Jonas diz ser o sobrinho de uma idosa e, com essa mentira, faz com que ela lhe entregue R$ 5.000,00. A mentira sobre a identidade é só o meio do golpe. Por isso, Jonas responde pelo crime mais grave, e não pela falsa identidade isolada."}},{"id":"aut.penal_tj.falsa_identidade_certames.0004","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"multipla","dificuldade":2,"enunciado":"Abordado por policiais, Ícaro exibe como sendo seu o documento de identidade do irmão, para se livrar de um mandado de prisão. Nos termos do Código Penal, a conduta de Ícaro, se não constituir elemento de crime mais grave, corresponde ao crime de","alternativas":{"A":"uso, como próprio, de documento de identidade alheia, punido com detenção de quatro meses a dois anos, e multa.","B":"falsa identidade, punido com detenção de três meses a um ano, ou multa.","C":"uso de documento falso, punido com a pena da falsificação de documento público.","D":"falsificação de documento público, punido com reclusão de dois a seis anos, e multa.","E":"supressão de documento, punido com reclusão de dois a seis anos, e multa."},"gabarito":"A","explicacao":"O art. 308 pune quem usa, como próprio, passaporte, título de eleitor, caderneta de reservista ou qualquer documento de identidade alheia, com detenção de quatro meses a dois anos, e multa, se o fato não constitui elemento de crime mais grave. O documento é verdadeiro, mas é de outra pessoa.","explicacoes":{"A":"Correta: usar como próprio documento de identidade alheia é o crime do art. 308.","B":"A falsa identidade do art. 307 não envolve o uso de documento alheio, que tem tipo específico.","C":"O documento do irmão é verdadeiro; não há uso de documento falso.","D":"Ícaro não falsificou nem alterou o documento.","E":"Ícaro não destruiu nem ocultou documento."},"fonte":"Código Penal, art. 308","mastigado":"A resposta é a letra A. A carteira era verdadeira, mas era do irmão. Mostrar documento verdadeiro de outra pessoa como se fosse seu é um crime próprio, com pena de quatro meses a dois anos e multa. Não é falsa identidade simples, porque houve uso de documento.","teSitua":{"termos":[{"termo":"documento de identidade alheia","significado":"documento verdadeiro que pertence a outra pessoa."},{"termo":"mandado de prisão","significado":"ordem escrita do juiz que manda prender uma pessoa."}],"exemplo":"Ícaro tem um mandado de prisão contra si. Parado numa blitz, entrega ao policial a carteira de identidade do irmão Elias, que é parecido com ele. O policial desconfia da foto e descobre a troca. Ícaro responde por usar, como próprio, documento de identidade alheia."}},{"id":"aut.penal_tj.falsa_identidade_certames.0005","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"certo_errado","dificuldade":3,"enunciado":"Comete o crime do art. 308 do Código Penal não só quem usa como próprio documento de identidade alheia, mas também quem cede a outrem, para que dele se utilize, documento dessa natureza, próprio ou de terceiro.","gabarito":"C","explicacao":"O art. 308 tem duas condutas: usar, como próprio, passaporte, título de eleitor, caderneta de reservista ou qualquer documento de identidade alheia; ou ceder a outrem, para que dele se utilize, documento dessa natureza, próprio ou de terceiro.","fonte":"Código Penal, art. 308","mastigado":"Certo. A lei pune quem usa o documento de outra pessoa como se fosse seu e também quem empresta o documento, seu ou de alguém, para que outro o use. Os dois lados da troca respondem pelo mesmo crime.","teSitua":{"termos":[{"termo":"cede a outrem","significado":"entrega ou empresta a outra pessoa."},{"termo":"documento dessa natureza","significado":"documento de identidade, como passaporte, título de eleitor ou caderneta de reservista."}],"exemplo":"Bianca empresta seu passaporte à irmã gêmea Beatriz, que tem uma restrição e quer viajar. Beatriz usa o passaporte como se fosse seu. As duas respondem pelo mesmo crime: Beatriz porque usou documento alheio como próprio, Bianca porque cedeu o seu para esse uso."}},{"id":"aut.penal_tj.falsa_identidade_certames.0006","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"multipla","dificuldade":3,"enunciado":"Sobre as penas previstas para a falsa identidade (art. 307) e para o uso de documento de identidade alheia (art. 308), é correto afirmar que","alternativas":{"A":"ambas são de reclusão, cumulada com multa.","B":"a do art. 307 é de detenção cumulada com multa, e a do art. 308 é de detenção ou multa.","C":"ambas são de detenção, de três meses a um ano, ou multa.","D":"a do art. 307 é de detenção ou multa, e a do art. 308 é de detenção cumulada com multa.","E":"a do art. 308 é de reclusão, de dois a seis anos, e multa."},"gabarito":"D","explicacao":"O art. 307 prevê detenção, de três meses a um ano, ou multa (pena alternativa). O art. 308 prevê detenção, de quatro meses a dois anos, e multa (pena cumulativa). Os dois são subsidiários: só se aplicam se o fato não constitui elemento de crime mais grave.","explicacoes":{"A":"Ambos preveem detenção, não reclusão.","B":"Inverte a regra: no art. 307 a multa é alternativa; no art. 308 é cumulativa.","C":"O art. 308 tem pena de quatro meses a dois anos, e multa.","D":"Correta: art. 307, detenção ou multa; art. 308, detenção e multa.","E":"O art. 308 prevê detenção de quatro meses a dois anos, e multa."},"fonte":"Código Penal, arts. 307 e 308","mastigado":"A resposta é a letra D. Na falsa identidade simples o juiz pode escolher entre prisão leve ou multa. No uso de documento de identidade de outra pessoa a lei manda aplicar as duas coisas juntas: detenção e multa.","teSitua":{"termos":[{"termo":"detenção","significado":"tipo de pena de prisão mais leve, que não começa em regime fechado."},{"termo":"cumulada com multa","significado":"aplicada junto com a multa, e não no lugar dela."}],"exemplo":"Rui mentiu o nome em uma repartição e pode receber detenção ou só multa. Sua amiga Tereza usou a carteira de identidade da prima e, se condenada, receberá detenção e também multa, porque a lei soma as duas penas nesse caso."}},{"id":"aut.penal_tj.falsa_identidade_certames.0007","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"certo_errado","dificuldade":2,"enunciado":"Para a configuração do crime de falsa identidade (art. 307 do Código Penal) é indispensável que o agente apresente documento falso ou alheio.","gabarito":"E","explicacao":"O art. 307 se consuma com o ato de atribuir-se ou atribuir a terceiro falsa identidade, o que pode ocorrer verbalmente, sem qualquer documento. O uso de documento de identidade alheia tem tipo próprio no art. 308, e o uso de documento falso, no art. 304.","fonte":"Código Penal, arts. 307, 308 e 304","mastigado":"Errado. Para a falsa identidade basta mentir sobre quem se é, até mesmo só falando. Quando a pessoa mostra o documento de outra, o crime passa a ser outro; quando mostra um papel falsificado, também.","teSitua":{"termos":[{"termo":"indispensável","significado":"que não pode faltar; obrigatório."},{"termo":"documento falso ou alheio","significado":"papel falsificado ou papel verdadeiro de outra pessoa."}],"exemplo":"Na fila de atendimento do Juizado, Diogo diz em voz alta que é o filho da autora da ação, para ser atendido antes e pegar uma cópia da sentença. Ele não mostra documento algum. Mesmo assim, comete falsa identidade, porque mentiu sobre quem era para obter vantagem."}},{"id":"aut.penal_tj.falsa_identidade_certames.0008","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"multipla","dificuldade":3,"enunciado":"Segundo o art. 307 do Código Penal, a falsa identidade exige que a atribuição de identidade falsa tenha a finalidade de","alternativas":{"A":"causar prejuízo exclusivamente à Administração Pública.","B":"obter vantagem, em proveito próprio ou alheio, ou causar dano a outrem.","C":"obter vantagem econômica, exclusivamente em proveito próprio.","D":"induzir a erro o juiz ou o perito em processo judicial.","E":"comprometer a credibilidade de certame de interesse público."},"gabarito":"B","explicacao":"O art. 307 exige que a falsa identidade seja atribuída para obter vantagem, em proveito próprio ou alheio, ou para causar dano a outrem. A vantagem não precisa ser econômica nem apenas do agente.","explicacoes":{"A":"O dano pode ser causado a qualquer pessoa, não só à Administração.","B":"Correta: é a finalidade descrita no art. 307.","C":"A vantagem pode ser em proveito alheio, e a lei não exige que seja econômica.","D":"Induzir a erro o juiz ou o perito é a finalidade da fraude processual (art. 347).","E":"Comprometer a credibilidade do certame é finalidade prevista no art. 311-A."},"fonte":"Código Penal, art. 307","mastigado":"A resposta é a letra B. A mentira sobre a identidade vira crime quando serve para conseguir alguma vantagem, para si ou para outro, ou para prejudicar alguém. Não precisa ser vantagem em dinheiro.","teSitua":{"termos":[{"termo":"finalidade","significado":"objetivo que a pessoa quer alcançar com a conduta."},{"termo":"credibilidade de certame","significado":"confiança de todos de que o concurso ou exame é honesto."}],"exemplo":"Mirela diz ao porteiro do condomínio que é a nova síndica, só para conseguir a chave do salão de festas para a filha. Ela não ganhou dinheiro, mas obteve vantagem em proveito alheio com a identidade falsa. Comete falsa identidade."}},{"id":"aut.penal_tj.falsa_identidade_certames.0009","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"multipla","dificuldade":2,"enunciado":"Um funcionário de empresa contratada para aplicar concurso público para o TJSP divulga, na véspera da prova, o caderno de questões sigiloso a um grupo de candidatos, para beneficiá-los. Nos termos do Código Penal, ele responde por","alternativas":{"A":"violação de sigilo funcional, com pena de detenção de seis meses a dois anos, ou multa.","B":"falsidade ideológica, com pena de reclusão de um a cinco anos, e multa.","C":"prevaricação, com pena de detenção de três meses a um ano, e multa.","D":"corrupção passiva, com pena de reclusão de dois a doze anos, e multa.","E":"fraude em certames de interesse público, com pena de reclusão de um a quatro anos, e multa."},"gabarito":"E","explicacao":"O art. 311-A pune quem utiliza ou divulga, indevidamente, com o fim de beneficiar a si ou a outrem, ou de comprometer a credibilidade do certame, conteúdo sigiloso de concurso público, com reclusão de um a quatro anos, e multa. Se o fato é cometido por funcionário público, aumenta-se a pena de um terço (§ 3º).","explicacoes":{"A":"A divulgação de conteúdo sigiloso de concurso tem tipo específico no art. 311-A.","B":"Não houve inserção de declaração falsa em documento.","C":"Não se trata de retardar ou deixar de praticar ato de ofício por interesse pessoal.","D":"O enunciado não menciona solicitação ou recebimento de vantagem.","E":"Correta: divulgar conteúdo sigiloso de concurso público para beneficiar outrem é o crime do art. 311-A."},"fonte":"Código Penal, art. 311-A, I","mastigado":"A resposta é a letra E. Espalhar as questões secretas de um concurso público antes da prova, para ajudar candidatos, é o crime de fraude em certames. A pena básica é de um a quatro anos de reclusão, e multa.","teSitua":{"termos":[{"termo":"concurso público","significado":"seleção aberta a todos para preencher cargos ou empregos públicos."},{"termo":"caderno de questões sigiloso","significado":"prova que ninguém pode conhecer antes da aplicação."},{"termo":"certames de interesse público","significado":"concursos, exames e seleções que interessam a toda a sociedade."}],"exemplo":"Valter trabalha na gráfica que imprime a prova do concurso de escrevente. Na noite anterior, envia fotos do caderno a cinco candidatos conhecidos. A fraude é descoberta e Valter responde por fraude em certames de interesse público."}},{"id":"aut.penal_tj.falsa_identidade_certames.0010","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"certo_errado","dificuldade":2,"enunciado":"O crime de fraude em certames de interesse público abrange a utilização ou divulgação indevida de conteúdo sigiloso de processo seletivo para ingresso no ensino superior.","gabarito":"C","explicacao":"O art. 311-A protege o conteúdo sigiloso de concurso público (I), avaliação ou exame públicos (II), processo seletivo para ingresso no ensino superior (III) e exame ou processo seletivo previstos em lei (IV).","fonte":"Código Penal, art. 311-A, III","mastigado":"Certo. A lei protege não só os concursos públicos, mas também os vestibulares e outras seleções para entrar na faculdade. Divulgar as questões secretas dessas provas também é crime.","teSitua":{"termos":[{"termo":"processo seletivo","significado":"seleção feita para escolher candidatos, como um vestibular."},{"termo":"ensino superior","significado":"nível de ensino das faculdades e universidades."}],"exemplo":"Renan, funcionário de uma universidade, envia a um cursinho as questões do vestibular dois dias antes da prova, para que os alunos do cursinho se saiam melhor. Ele comete fraude em certame de interesse público, porque o vestibular é processo seletivo para ingresso no ensino superior."}},{"id":"aut.penal_tj.falsa_identidade_certames.0011","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 311-A do Código Penal, se da utilização ou divulgação indevida de conteúdo sigiloso de concurso público resulta dano à administração pública, a pena é de","alternativas":{"A":"reclusão, de dois a seis anos, e multa.","B":"reclusão, de um a quatro anos, e multa, aumentada de um sexto.","C":"detenção, de seis meses a dois anos, ou multa.","D":"reclusão, de dois a doze anos, e multa.","E":"reclusão, de um a quatro anos, e multa, aplicada em dobro."},"gabarito":"A","explicacao":"O § 2º do art. 311-A dispõe que, se da ação ou omissão resulta dano à administração pública, a pena é de reclusão, de dois a seis anos, e multa. A pena do caput é de reclusão, de um a quatro anos, e multa.","explicacoes":{"A":"Correta: é a forma qualificada do § 2º.","B":"A lei não prevê aumento de sexta parte para o dano; prevê pena própria de dois a seis anos.","C":"Essa pena não está prevista no art. 311-A.","D":"Dois a doze anos é a pena de crimes como peculato e corrupção, não da fraude em certame.","E":"Não há previsão de pena em dobro no art. 311-A."},"fonte":"Código Penal, art. 311-A, § 2º","mastigado":"A resposta é a letra A. Quando a fraude no concurso causa prejuízo à administração pública, por exemplo obrigando a refazer a prova, a lei aumenta a punição. A pena passa a ser de dois a seis anos de reclusão, e multa.","teSitua":{"termos":[{"termo":"dano à administração pública","significado":"prejuízo causado ao poder público, como o gasto de anular e refazer uma prova."},{"termo":"reclusão","significado":"tipo mais grave de pena de prisão, que pode começar em regime fechado."}],"exemplo":"Por causa do vazamento feito por Nara, o tribunal precisa anular a prova do concurso e pagar à banca uma nova aplicação. Como a fraude causou prejuízo à administração pública, Nara responde pela forma qualificada, com pena de dois a seis anos de reclusão."}},{"id":"aut.penal_tj.falsa_identidade_certames.0012","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"certo_errado","dificuldade":3,"enunciado":"Quem apenas permite ou facilita o acesso de pessoas não autorizadas às informações sigilosas do certame não incorre nas penas da fraude em certames, reservadas a quem utiliza ou divulga o conteúdo.","gabarito":"E","explicacao":"O art. 311-A, § 1º, do CP determina que incorre nas mesmas penas do caput quem permite ou facilita, por qualquer meio, o acesso de pessoas não autorizadas às informações sigilosas mencionadas no caput.","fonte":"Código Penal, art. 311-A, § 1º","mastigado":"Errado. A lei também pune quem deixa ou ajuda pessoas sem autorização a chegar às informações secretas do concurso. Essa pessoa recebe as mesmas penas de quem usa ou espalha o conteúdo.","teSitua":{"termos":[{"termo":"permite ou facilita","significado":"deixa acontecer ou torna mais fácil."},{"termo":"pessoas não autorizadas","significado":"quem não tem permissão para conhecer as informações."}],"exemplo":"Sandra guarda as provas do concurso numa sala trancada. Ela empresta a chave ao namorado Túlio, que quer ver as questões. Sandra não divulgou nada, mas facilitou o acesso de pessoa não autorizada e responde com as mesmas penas da fraude em certame."}},{"id":"aut.penal_tj.falsa_identidade_certames.0013","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"multipla","dificuldade":3,"enunciado":"No crime de fraude em certames de interesse público, se o fato é cometido por funcionário público, a pena","alternativas":{"A":"é aumentada de sexta parte.","B":"é aplicada em dobro.","C":"é aumentada de um terço.","D":"é aumentada de metade.","E":"não sofre alteração, pois a condição de funcionário já integra o tipo."},"gabarito":"C","explicacao":"O art. 311-A, § 3º, prevê o aumento da pena de 1/3 (um terço) se o fato é cometido por funcionário público. Não se confunde com o aumento de sexta parte previsto em vários crimes de falsidade documental (arts. 295, 296, § 2º, 297, § 1º, e 299, parágrafo único).","explicacoes":{"A":"O aumento de sexta parte é o dos crimes de falsidade documental, não o do art. 311-A.","B":"Não há previsão de pena em dobro.","C":"Correta: o aumento é de um terço (art. 311-A, § 3º).","D":"Não há aumento de metade no art. 311-A.","E":"O crime pode ser cometido por qualquer pessoa; a condição de funcionário público é causa de aumento."},"fonte":"Código Penal, art. 311-A, § 3º","mastigado":"A resposta é a letra C. Qualquer pessoa pode cometer fraude em concurso. Mas, quando quem faz isso é servidor público, a pena cresce um terço, porque ele traiu a confiança que o cargo exige.","teSitua":{"termos":[{"termo":"funcionário público","significado":"quem exerce cargo, emprego ou função pública, mesmo sem salário ou por pouco tempo."},{"termo":"integra o tipo","significado":"faz parte da descrição do próprio crime na lei."}],"exemplo":"Elton, servidor da secretaria do tribunal, recebe as provas lacradas e as fotografa para a cunhada, candidata. Como ele é funcionário público, a pena da fraude em certame é aumentada de um terço."}},{"id":"aut.penal_tj.falsa_identidade_certames.0014","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"certo_errado","dificuldade":3,"enunciado":"Só há fraude em certame de interesse público se o agente divulgar o conteúdo sigiloso com o fim de beneficiar a si ou a outrem; a divulgação feita apenas para comprometer a credibilidade do concurso não é crime.","gabarito":"E","explicacao":"O art. 311-A prevê duas finalidades alternativas: beneficiar a si ou a outrem, ou comprometer a credibilidade do certame. Basta uma delas.","fonte":"Código Penal, art. 311-A, caput","mastigado":"Errado. A lei também pune quem divulga as questões secretas só para desmoralizar o concurso, mesmo sem querer ajudar ninguém. Basta querer beneficiar alguém ou abalar a confiança no certame.","teSitua":{"termos":[{"termo":"comprometer a credibilidade","significado":"abalar a confiança das pessoas de que algo é sério e honesto."}],"exemplo":"Irritado por ter sido demitido da banca, Fausto publica numa rede social as questões do exame da OAB antes da prova. Ele não quer ajudar candidato algum, só desmoralizar o exame. Mesmo assim, comete fraude em certame de interesse público."}},{"id":"aut.penal_tj.falsa_identidade_certames.0015","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com o Código Penal, a pena prevista no caput do art. 311-A (fraude em certames de interesse público) é de","alternativas":{"A":"detenção, de três meses a um ano, ou multa.","B":"reclusão, de um a quatro anos, e multa.","C":"reclusão, de dois a seis anos, e multa.","D":"detenção, de quatro meses a dois anos, e multa.","E":"reclusão, de dois a oito anos, e multa."},"gabarito":"B","explicacao":"O caput do art. 311-A prevê reclusão, de 1 (um) a 4 (quatro) anos, e multa. Dois a seis anos é a pena qualificada pelo dano à administração (§ 2º).","explicacoes":{"A":"É a pena da falsa identidade (art. 307).","B":"Correta: reclusão de um a quatro anos, e multa.","C":"É a pena da forma qualificada pelo dano à administração pública (§ 2º).","D":"É a pena do uso de documento de identidade alheia (art. 308).","E":"É a pena da falsificação de papéis públicos (art. 293)."},"fonte":"Código Penal, art. 311-A, caput e § 2º","mastigado":"A resposta é a letra B. Na forma simples, quem frauda um concurso divulgando conteúdo secreto pega de um a quatro anos de reclusão, mais multa. A pena só sobe para dois a seis anos se houver prejuízo para a administração.","teSitua":{"termos":[{"termo":"caput","significado":"a parte principal do artigo, antes dos parágrafos e incisos."},{"termo":"reclusão","significado":"tipo mais grave de pena de prisão, que pode começar em regime fechado."}],"exemplo":"Igor vende a três candidatos as respostas de um exame público e é descoberto antes da prova, sem que ela precise ser refeita. Ele responde pela forma simples da fraude em certame, com pena de um a quatro anos de reclusão e multa."}},{"id":"aut.penal_tj.falsa_identidade_certames.0016","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"certo_errado","dificuldade":3,"enunciado":"Também pratica fraude em certame de interesse público quem utiliza indevidamente, para beneficiar a si mesmo, conteúdo sigiloso de exame público, ainda que não o divulgue a ninguém.","gabarito":"C","explicacao":"O art. 311-A traz dois verbos alternativos: utilizar ou divulgar. O candidato que usa, em proveito próprio, o conteúdo sigiloso que obteve indevidamente pratica a conduta de utilizar.","fonte":"Código Penal, art. 311-A, caput, II","mastigado":"Certo. A lei pune quem espalha as questões secretas e também quem as usa para se dar bem. O candidato que recebe a prova antes e a usa para estudar as respostas comete o crime, mesmo sem mostrar a ninguém.","teSitua":{"termos":[{"termo":"utiliza indevidamente","significado":"usa algo sem ter direito, de forma proibida."},{"termo":"exame público","significado":"prova organizada pelo poder público ou de interesse público, como um exame de habilitação."}],"exemplo":"Kátia recebe de um conhecido, na véspera, o gabarito do exame para tradutor público. Ela decora as respostas e faz a prova sem contar nada a ninguém. Ao ser descoberta, responde por fraude em certame, porque utilizou o conteúdo sigiloso para se beneficiar."}},{"id":"aut.penal_tj.falsa_identidade_certames.0017","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"multipla","dificuldade":4,"enunciado":"Considere três situações: I. Ana diz chamar-se Júlia ao recepcionista de um hotel, para fugir de uma cobrança; II. Bento exibe como sua a carteira de reservista verdadeira do primo; III. Caio, candidato, usa o gabarito sigiloso de concurso público que comprou de um servidor. Os crimes praticados são, respectivamente,","alternativas":{"A":"falsidade ideológica; falsa identidade; corrupção ativa.","B":"falsa identidade; uso de documento falso; violação de sigilo funcional.","C":"uso de documento falso; falsa identidade; fraude em certame.","D":"falsa identidade; uso de documento de identidade alheia; fraude em certame.","E":"falsa identidade; falsa identidade; violação de sigilo funcional."},"gabarito":"D","explicacao":"I: atribuir-se falsa identidade para obter vantagem é o art. 307. II: usar como próprio documento de identidade alheia, como caderneta de reservista, é o art. 308. III: utilizar indevidamente conteúdo sigiloso de concurso público para beneficiar a si é o art. 311-A.","explicacoes":{"A":"Ana não inseriu declaração em documento, e Bento usou documento alheio, não apenas mentiu o nome.","B":"A carteira do primo é verdadeira, não falsa; e Caio pratica a fraude do art. 311-A.","C":"Ana não usou documento algum.","D":"Correta: arts. 307, 308 e 311-A, nessa ordem.","E":"Bento usou documento alheio (art. 308), e Caio, particular, utilizou conteúdo sigiloso de concurso (art. 311-A)."},"fonte":"Código Penal, arts. 307, 308 e 311-A","mastigado":"A resposta é a letra D. Ana só mentiu o nome: falsa identidade. Bento usou documento verdadeiro de outra pessoa como se fosse dele: crime próprio de uso de documento alheio. Caio usou o gabarito secreto do concurso: fraude em certame.","teSitua":{"termos":[{"termo":"carteira de reservista","significado":"documento que comprova a situação do cidadão perante o serviço militar."},{"termo":"gabarito sigiloso","significado":"lista das respostas certas, que não pode ser conhecida antes da prova."},{"termo":"recepcionista","significado":"funcionário que atende as pessoas na entrada de um local."}],"exemplo":"No mesmo dia, a delegada Sônia atende três casos: Ana mentiu o nome no hotel, Bento mostrou na blitz a reservista do primo e Caio foi pego com o gabarito comprado do concurso. Ela registra falsa identidade, uso de documento de identidade alheia e fraude em certame."}},{"id":"aut.penal_tj.falsa_identidade_certames.0018","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"multipla","dificuldade":3,"enunciado":"O art. 308 do Código Penal pune o uso, como próprio, de documento de identidade alheia. Entre os documentos mencionados expressamente no tipo está","alternativas":{"A":"a certidão de casamento.","B":"o cartão de crédito.","C":"o título de eleitor.","D":"o recibo de pagamento.","E":"o livro mercantil."},"gabarito":"C","explicacao":"O art. 308 menciona expressamente passaporte, título de eleitor, caderneta de reservista ou qualquer documento de identidade alheia.","explicacoes":{"A":"A certidão de casamento não está entre os documentos citados no art. 308.","B":"O cartão de crédito é equiparado a documento particular no art. 298, não é documento de identidade do art. 308.","C":"Correta: o título de eleitor está expressamente previsto no art. 308.","D":"Recibo não é documento de identidade.","E":"Livro mercantil é equiparado a documento público (art. 297, § 2º), não é documento de identidade."},"fonte":"Código Penal, art. 308","mastigado":"A resposta é a letra C. A lei cita como exemplos o passaporte, o título de eleitor e a carteira de reservista, além de qualquer outro documento de identidade. Usar um desses, sendo de outra pessoa, como se fosse seu, é crime.","teSitua":{"termos":[{"termo":"título de eleitor","significado":"documento que identifica o cidadão como eleitor e indica onde ele vota."},{"termo":"livro mercantil","significado":"livro de registros obrigatório de uma empresa."}],"exemplo":"No dia da eleição, Wagner tenta votar usando o título de eleitor do vizinho, que viajou. O mesário percebe a diferença e chama a polícia. Wagner responde pelo uso, como próprio, de documento de identidade alheia."}},{"id":"aut.penal_tj.falsa_identidade_certames.0019","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"certo_errado","dificuldade":3,"enunciado":"A pena do crime de uso de documento de identidade alheia (art. 308 do Código Penal) aplica-se mesmo que o fato constitua elemento de crime mais grave, somando-se à pena deste.","gabarito":"E","explicacao":"O art. 308 prevê detenção, de quatro meses a dois anos, e multa, \\"se o fato não constitui elemento de crime mais grave\\". Há subsidiariedade expressa: se o uso do documento for meio de crime mais grave, responde-se apenas por este.","fonte":"Código Penal, art. 308","mastigado":"Errado. A lei diz o contrário: o crime de usar documento de identidade de outra pessoa só é punido sozinho quando não faz parte de um crime mais sério. Se fizer, a pessoa responde só pelo mais grave.","teSitua":{"termos":[{"termo":"elemento de crime mais grave","significado":"parte de um crime mais sério, que absorve a conduta menor."},{"termo":"somando-se à pena deste","significado":"acrescentada à punição do outro crime, de modo que o réu receba as duas."}],"exemplo":"Lauro usa a carteira de identidade verdadeira do irmão para abrir conta e fazer empréstimos que nunca pagará. O uso do documento é só o meio do golpe. Por isso, ele não responde pelo uso de documento alheio somado ao crime maior, mas apenas por este."}},{"id":"aut.penal_tj.falsa_identidade_certames.0020","subtopico":"penal_tj.fe_publica.falsa_identidade_certames","tipo":"multipla","dificuldade":3,"enunciado":"Murilo empresta sua própria carteira de identidade ao amigo Nestor, para que este a use como se fosse sua e consiga entrar em um evento proibido a menores. Nos termos do Código Penal, Murilo","alternativas":{"A":"não comete crime, pois o documento é verdadeiro e pertence a ele.","B":"comete o crime do art. 308, na modalidade de ceder a outrem documento de identidade próprio para que dele se utilize.","C":"comete falsa identidade, com pena de detenção de três meses a um ano, ou multa.","D":"comete uso de documento falso, com a pena da falsificação de documento público.","E":"só responde se Nestor obtiver vantagem econômica com o uso do documento."},"gabarito":"B","explicacao":"O art. 308 pune também quem cede a outrem, para que dele se utilize, documento de identidade próprio ou de terceiro, com detenção de quatro meses a dois anos, e multa, se o fato não constitui elemento de crime mais grave.","explicacoes":{"A":"Ceder documento próprio para uso alheio é conduta expressamente prevista no art. 308.","B":"Correta: é a segunda conduta do art. 308.","C":"Murilo não se atribuiu nem atribuiu a outro identidade falsa verbalmente; ele cedeu documento.","D":"O documento é verdadeiro; não há falsificação.","E":"O art. 308 não exige vantagem econômica."},"fonte":"Código Penal, art. 308","mastigado":"A resposta é a letra B. Emprestar o próprio documento de identidade para outra pessoa usar como se fosse dela também é crime. Quem cede responde pelo mesmo artigo de quem usa, ainda que o documento seja verdadeiro.","teSitua":{"termos":[{"termo":"carteira de identidade","significado":"documento oficial com foto e dados que identifica a pessoa."},{"termo":"ceder a outrem","significado":"entregar ou emprestar a outra pessoa."}],"exemplo":"Nestor tem 16 anos e quer entrar numa festa só para maiores. Murilo, de 19, empresta sua carteira de identidade para que Nestor se passe por ele na portaria. Murilo responde pelo crime de ceder documento de identidade próprio para uso de outra pessoa."}},{"id":"aut.penal_tj.falsidade_documental.0001","subtopico":"penal_tj.fe_publica.falsidade_documental","tipo":"multipla","dificuldade":3,"enunciado":"Um escrevente, prevalecendo-se do cargo, rasura um mandado de levantamento judicial verdadeiro, já assinado pelo juiz, e altera o valor nele constante. Nos termos do Código Penal, a conduta configura","alternativas":{"A":"falsificação de documento particular, sem causa de aumento.","B":"falsificação de documento público, com a pena aumentada de sexta parte.","C":"falsidade ideológica, com a pena aumentada de um terço.","D":"supressão de documento, com a pena aumentada de sexta parte.","E":"falsificação de documento público, com a pena aumentada de metade."},"gabarito":"B","explicacao":"Alterar documento público verdadeiro é falsificação de documento público (art. 297, caput, pena de reclusão de dois a seis anos e multa). Como o agente é funcionário público e se prevaleceu do cargo, a pena é aumentada de sexta parte (art. 297, § 1º).","explicacoes":{"A":"O mandado judicial é documento público, não particular, e há aumento por ser funcionário que se prevalece do cargo.","B":"Correta: alterar documento público verdadeiro é o crime do art. 297, com aumento de sexta parte do § 1º.","C":"Houve alteração material do papel, não inserção de declaração falsa em documento formalmente verdadeiro; e o aumento não é de um terço.","D":"O escrevente não destruiu nem ocultou o documento; ele o alterou.","E":"O aumento previsto no § 1º do art. 297 é de sexta parte, não de metade."},"fonte":"Código Penal, art. 297, caput e § 1º","mastigado":"A resposta é a letra B. O mandado assinado pelo juiz é um papel público, e o servidor mexeu no que estava escrito nele. Isso é falsificar documento público. Como ele usou o cargo para fazer isso, a pena fica um pouco maior: aumenta um sexto.","teSitua":{"termos":[{"termo":"rasura","significado":"risca ou raspa o que está escrito em um papel para apagar ou mudar o texto."},{"termo":"mandado de levantamento judicial","significado":"ordem do juiz que autoriza alguém a sacar no banco um dinheiro depositado no processo."},{"termo":"prevalecendo-se do cargo","significado":"aproveitando-se das facilidades que o cargo público lhe dá."},{"termo":"causa de aumento","significado":"regra da lei que manda aumentar a pena em certa fração quando ocorre uma situação especial."}],"exemplo":"Rogério trabalha no cartório da 3ª Vara Cível e guarda os mandados já assinados. Ele pega um mandado de levantamento de R$ 2.000,00 e muda o valor para R$ 20.000,00. Descoberto, responde por falsificação de documento público, com a pena aumentada de um sexto por ter usado o cargo."}},{"id":"aut.penal_tj.falsidade_documental.0002","subtopico":"penal_tj.fe_publica.falsidade_documental","tipo":"multipla","dificuldade":3,"enunciado":"Para os efeitos penais, o Código Penal equipara a documento público os seguintes papéis, EXCETO","alternativas":{"A":"o título ao portador ou transmissível por endosso.","B":"as ações de sociedade comercial.","C":"os livros mercantis.","D":"o testamento particular.","E":"o cartão de crédito ou débito."},"gabarito":"E","explicacao":"O art. 297, § 2º, equipara a documento público o emanado de entidade paraestatal, o título ao portador ou transmissível por endosso, as ações de sociedade comercial, os livros mercantis e o testamento particular. O cartão de crédito ou débito é equiparado a documento particular (art. 298, parágrafo único).","explicacoes":{"A":"O título ao portador ou transmissível por endosso está no rol do art. 297, § 2º.","B":"As ações de sociedade comercial estão no rol do art. 297, § 2º.","C":"Os livros mercantis estão no rol do art. 297, § 2º.","D":"O testamento particular, apesar do nome, é equiparado a documento público (art. 297, § 2º).","E":"Correta: o cartão de crédito ou débito é equiparado a documento particular (art. 298, parágrafo único)."},"fonte":"Código Penal, art. 297, § 2º, e art. 298, parágrafo único","mastigado":"A resposta é a letra E. A lei trata como papel público, para fins de crime, o título ao portador, as ações de empresa, os livros comerciais e até o testamento particular. Já o cartão de crédito ou débito foi colocado do outro lado: ele vale como documento particular.","teSitua":{"termos":[{"termo":"equipara","significado":"trata como se fosse igual, aplicando as mesmas regras."},{"termo":"título ao portador ou transmissível por endosso","significado":"papel de crédito que pode ser cobrado por quem o tiver em mãos ou passado adiante por assinatura no verso."},{"termo":"livros mercantis","significado":"livros de registro obrigatórios das empresas, como o livro diário."},{"termo":"testamento particular","significado":"testamento escrito e assinado pela própria pessoa, sem passar pelo tabelião."}],"exemplo":"Luana falsifica a assinatura do avô em um testamento particular para ficar com a casa da família. Mesmo sendo um papel feito em casa, a lei o trata como documento público. Já seu primo Diego, que clonou um cartão de débito, responde por falsificação de documento particular."}},{"id":"aut.penal_tj.falsidade_documental.0003","subtopico":"penal_tj.fe_publica.falsidade_documental","tipo":"certo_errado","dificuldade":3,"enunciado":"Na falsidade ideológica, o documento é formalmente verdadeiro, mas nele se omite declaração que devia constar ou se insere declaração falsa, e a pena é aumentada de sexta parte se a falsificação ou alteração for de assentamento de registro civil.","gabarito":"C","explicacao":"O art. 299 pune quem omite, em documento público ou particular, declaração que dele devia constar, ou nele insere ou faz inserir declaração falsa ou diversa da que devia ser escrita, com o fim de prejudicar direito, criar obrigação ou alterar a verdade sobre fato juridicamente relevante. O parágrafo único aumenta a pena de sexta parte se o agente é funcionário público que se prevalece do cargo ou se a falsificação é de assentamento de registro civil.","fonte":"Código Penal, art. 299, caput e parágrafo único","mastigado":"Certo. Na falsidade ideológica o papel é de verdade, mas o que está escrito nele é mentira ou falta algo que devia constar. Se a mentira for no registro civil, como certidão de nascimento, a pena aumenta um sexto.","teSitua":{"termos":[{"termo":"formalmente verdadeiro","significado":"papel autêntico na aparência, feito por quem podia fazê-lo, sem rasura ou montagem."},{"termo":"assentamento de registro civil","significado":"anotação no cartório de registro civil, como nascimento, casamento ou óbito."}],"exemplo":"Bruno vai ao cartório registrar o filho de outra pessoa como se fosse seu, declarando dado falso ao oficial. A certidão é verdadeira na forma, mas o conteúdo é falso. Ele responde por falsidade ideológica, com a pena aumentada de um sexto por envolver registro civil."}},{"id":"aut.penal_tj.falsidade_documental.0004","subtopico":"penal_tj.fe_publica.falsidade_documental","tipo":"multipla","dificuldade":2,"enunciado":"Pedro apresenta em cartório judicial uma procuração particular que sabe ter sido falsificada por um terceiro. De acordo com o Código Penal, Pedro responde por uso de documento falso, com pena","alternativas":{"A":"igual à cominada à falsificação do documento particular.","B":"correspondente à metade da cominada à falsificação.","C":"de detenção, de seis meses a dois anos, ou multa.","D":"aumentada de um terço em relação à da falsificação.","E":"de multa, apenas, por não ter falsificado o documento."},"gabarito":"A","explicacao":"O art. 304 pune quem faz uso de qualquer dos papéis falsificados ou alterados a que se referem os arts. 297 a 302, com a pena cominada à falsificação ou à alteração. Para procuração particular falsa, aplica-se a pena do art. 298 (reclusão, de um a cinco anos, e multa).","explicacoes":{"A":"Correta: a pena do uso é a mesma cominada à falsificação ou à alteração (art. 304).","B":"Não há redução pela metade; a pena é a mesma da falsificação.","C":"Essa não é a pena do uso de documento falso; o art. 304 remete à pena da falsificação.","D":"Não há aumento de um terço; a pena é a mesma da falsificação.","E":"Quem usa o documento falso responde pelo art. 304 com a pena da falsificação, não apenas multa."},"fonte":"Código Penal, art. 304","mastigado":"A resposta é a letra A. Quem usa um papel falso sabendo que é falso recebe a mesma pena de quem o falsificou. Não importa que outra pessoa tenha feito a falsificação: usar já basta para responder pelo crime com a mesma punição.","teSitua":{"termos":[{"termo":"procuração particular","significado":"documento em que uma pessoa dá poderes a outra para agir em seu nome, feito sem tabelião."},{"termo":"cominada","significado":"prevista na lei como castigo para aquele crime."}],"exemplo":"Pedro precisa sacar um dinheiro do tio e compra de um conhecido uma procuração falsa com a assinatura do tio. Ele a entrega no balcão da vara. Mesmo sem ter feito a falsificação, Pedro responde por uso de documento falso com a mesma pena de quem falsificou."}},{"id":"aut.penal_tj.falsidade_documental.0005","subtopico":"penal_tj.fe_publica.falsidade_documental","tipo":"certo_errado","dificuldade":3,"enunciado":"O funcionário público que, no exercício de sua função, reconhece como verdadeira firma ou letra que não o seja comete crime cuja pena é a mesma, seja o documento público, seja particular.","gabarito":"E","explicacao":"O art. 300 (falso reconhecimento de firma ou letra) prevê pena de reclusão de um a cinco anos e multa, se o documento é público, e de um a três anos e multa, se o documento é particular. A pena varia, portanto, conforme a natureza do documento.","fonte":"Código Penal, art. 300","mastigado":"Errado. Reconhecer como verdadeira uma assinatura falsa é crime, mas a pena muda conforme o papel. Se o documento é público, a pena é maior; se é particular, a pena máxima é menor.","teSitua":{"termos":[{"termo":"firma ou letra","significado":"a assinatura ou a escrita à mão de uma pessoa."},{"termo":"reconhece como verdadeira","significado":"declara oficialmente que a assinatura é mesmo daquela pessoa."}],"exemplo":"Célia, funcionária de um cartório de notas, carimba como verdadeira a assinatura de um contrato particular de aluguel, embora a assinatura tenha sido imitada. Ela responde por falso reconhecimento de firma, com a pena prevista para documento particular, que é menor que a de documento público."}},{"id":"aut.penal_tj.falsidade_documental.0006","subtopico":"penal_tj.fe_publica.falsidade_documental","tipo":"multipla","dificuldade":3,"enunciado":"Carla, para prejudicar o vizinho, rasga o recibo verdadeiro que ele lhe entregara para guardar e que comprovava o pagamento de uma dívida. Desse documento particular ela não podia dispor. Nos termos do Código Penal, Carla praticou","alternativas":{"A":"falsificação de documento particular.","B":"falsidade ideológica.","C":"uso de documento falso.","D":"supressão de documento.","E":"dano simples, por não haver falsidade."},"gabarito":"D","explicacao":"O art. 305 pune quem destrói, suprime ou oculta, em benefício próprio ou de outrem, ou em prejuízo alheio, documento público ou particular verdadeiro de que não podia dispor. Sendo particular, a pena é de reclusão, de um a cinco anos, e multa.","explicacoes":{"A":"Não houve falsificação nem alteração; o recibo era verdadeiro e foi destruído.","B":"Não houve inserção nem omissão de declaração no documento.","C":"Carla não usou documento falso algum.","D":"Correta: destruir documento verdadeiro de que não podia dispor, em prejuízo alheio, é supressão de documento (art. 305).","E":"A destruição de documento verdadeiro em prejuízo alheio tem tipo próprio entre os crimes contra a fé pública (art. 305)."},"fonte":"Código Penal, art. 305","mastigado":"A resposta é a letra D. O recibo era verdadeiro e não era dela. Ao rasgá-lo para prejudicar o vizinho, Carla fez sumir uma prova. A lei chama isso de supressão de documento, que é crime mesmo sem falsificar nada.","teSitua":{"termos":[{"termo":"documento particular","significado":"papel feito por pessoas comuns, sem participação de funcionário público, como um recibo."},{"termo":"não podia dispor","significado":"não tinha o direito de destruir ou se desfazer do papel."}],"exemplo":"O vizinho de Carla pagou uma dívida e pediu que ela guardasse o recibo. Depois de uma briga, Carla rasga o papel para que ele não consiga provar o pagamento. Ela responde por supressão de documento particular."}},{"id":"aut.penal_tj.falsidade_documental.0007","subtopico":"penal_tj.fe_publica.falsidade_documental","tipo":"certo_errado","dificuldade":2,"enunciado":"O médico que, no exercício da sua profissão, dá atestado falso comete crime punido com detenção, e, se o crime é cometido com o fim de lucro, a pena é aumentada de metade.","gabarito":"E","explicacao":"O art. 302 do CP pune com detenção, de um mês a um ano, o médico que, no exercício da profissão, dá atestado falso. O parágrafo único não prevê aumento de metade: se o crime é cometido com o fim de lucro, aplica-se também multa.","fonte":"Código Penal, art. 302, caput e parágrafo único","mastigado":"Errado. O médico que dá atestado falso é punido com detenção. Se fez isso para ganhar dinheiro, a lei não aumenta a prisão pela metade: ela manda aplicar também uma multa.","teSitua":{"termos":[{"termo":"atestado falso","significado":"declaração escrita com informação mentirosa, como dizer que alguém estava doente quando não estava."},{"termo":"fim de lucro","significado":"intenção de ganhar dinheiro ou outra vantagem com a conduta."}],"exemplo":"O doutor Fábio cobra R$ 200,00 para dar a Rafael um atestado dizendo que ele estava internado no dia da audiência. Rafael nem foi ao hospital. O médico responde por atestado médico falso e, como agiu para lucrar, também paga multa."}},{"id":"aut.penal_tj.falsidade_documental.0008","subtopico":"penal_tj.fe_publica.falsidade_documental","tipo":"multipla","dificuldade":3,"enunciado":"Um particular falsifica, fabricando-a, uma guia de recolhimento da taxa judiciária, documento relativo à arrecadação de rendas públicas, para simular o pagamento das custas de uma ação. De acordo com o Código Penal, a conduta configura","alternativas":{"A":"falsificação de documento particular, com pena de reclusão de um a cinco anos e multa.","B":"falsificação do selo ou sinal público, com pena de reclusão de dois a seis anos e multa.","C":"falsidade ideológica, com pena de reclusão de um a três anos e multa.","D":"falso reconhecimento de firma, com pena de reclusão de um a cinco anos e multa.","E":"falsificação de papéis públicos, com pena de reclusão de dois a oito anos e multa."},"gabarito":"E","explicacao":"O art. 293, V, pune quem falsifica, fabricando-os ou alterando-os, talão, recibo, guia, alvará ou qualquer outro documento relativo a arrecadação de rendas públicas, com reclusão de dois a oito anos e multa.","explicacoes":{"A":"A guia de arrecadação de rendas públicas tem tipo específico no art. 293, V.","B":"O art. 296 trata de selo público destinado a autenticar atos oficiais, não de guia de arrecadação.","C":"Houve fabricação do papel (falsidade material), não inserção de declaração falsa em documento verdadeiro.","D":"Ninguém reconheceu firma no exercício de função pública.","E":"Correta: guia relativa à arrecadação de rendas públicas está no art. 293, V, com reclusão de dois a oito anos e multa."},"fonte":"Código Penal, art. 293, V","mastigado":"A resposta é a letra E. A guia usada para pagar taxa ao Estado é um papel público ligado à arrecadação de dinheiro público. Fabricar uma guia falsa é o crime de falsificação de papéis públicos, com pena de dois a oito anos.","teSitua":{"termos":[{"termo":"taxa judiciária","significado":"valor pago ao Estado para que o processo seja aceito e ande na Justiça."},{"termo":"arrecadação de rendas públicas","significado":"recebimento, pelo poder público, de tributos e outros valores que lhe são devidos."},{"termo":"simular","significado":"fingir que algo aconteceu quando não aconteceu."}],"exemplo":"Gustavo quer entrar com uma ação sem pagar as custas. Ele monta no computador uma guia de recolhimento com autenticação bancária falsa e a junta ao processo. Responde por falsificação de papéis públicos, com pena de reclusão de dois a oito anos e multa."}},{"id":"aut.penal_tj.falsidade_documental.0009","subtopico":"penal_tj.fe_publica.falsidade_documental","tipo":"certo_errado","dificuldade":3,"enunciado":"Quem utiliza indevidamente selo ou sinal público verdadeiro, em proveito próprio ou em prejuízo de outrem, não comete crime, porque o tipo do art. 296 do Código Penal exige que o selo tenha sido falsificado.","gabarito":"E","explicacao":"O art. 296, § 1º, II, prevê que incorre nas mesmas penas da falsificação do selo ou sinal público quem utiliza indevidamente o selo ou sinal verdadeiro em prejuízo de outrem ou em proveito próprio ou alheio. A falsificação não é exigida nessa figura.","fonte":"Código Penal, art. 296, § 1º, II","mastigado":"Errado. Não é preciso que o selo seja falso. Usar sem direito um selo oficial verdadeiro, para tirar proveito ou prejudicar alguém, também é crime e tem a mesma pena de quem falsifica.","teSitua":{"termos":[{"termo":"selo ou sinal público","significado":"carimbo ou marca oficial que serve para autenticar atos do poder público."},{"termo":"utiliza indevidamente","significado":"usa sem ter direito ou fora da finalidade para a qual o objeto existe."}],"exemplo":"Henrique trabalha em um tabelionato e leva para casa o sinal público verdadeiro do tabelião. Ele o usa para dar aparência oficial a papéis de um amigo. Mesmo sem falsificar o selo, responde pelo crime, porque usou indevidamente o sinal verdadeiro."}},{"id":"aut.penal_tj.falsidade_documental.0010","subtopico":"penal_tj.fe_publica.falsidade_documental","tipo":"multipla","dificuldade":4,"enunciado":"Um escrevente, em razão de sua função, certifica falsamente que determinado candidato não responde a processo criminal, para que ele possa tomar posse em cargo público. Nos termos do Código Penal, a conduta corresponde a","alternativas":{"A":"falsificação de documento público.","B":"falsidade ideológica comum.","C":"certidão ou atestado ideologicamente falso.","D":"falsidade material de atestado ou certidão.","E":"falso reconhecimento de firma ou letra."},"gabarito":"C","explicacao":"O art. 301, caput, pune quem atesta ou certifica falsamente, em razão de função pública, fato ou circunstância que habilite alguém a obter cargo público, isenção de ônus ou de serviço de caráter público, ou qualquer outra vantagem, com detenção de dois meses a um ano. A falsidade material (falsificar ou alterar atestado ou certidão) está no § 1º.","explicacoes":{"A":"O escrevente não falsificou a forma do papel; ele emitiu certidão verdadeira na forma com conteúdo falso.","B":"A falsidade ideológica do art. 299 cede ao tipo especial do art. 301 quando a certidão habilita alguém a obter cargo público.","C":"Correta: certificar falsamente, em razão de função pública, fato que habilite alguém a obter cargo público é o crime do art. 301, caput.","D":"A falsidade material do § 1º é falsificar ou alterar certidão; aqui o funcionário certificou falsamente.","E":"Não houve reconhecimento de assinatura."},"fonte":"Código Penal, art. 301, caput e § 1º","mastigado":"A resposta é a letra C. O papel foi feito pelo próprio servidor, do jeito certo, mas com uma informação mentirosa para ajudar alguém a assumir um cargo público. A lei tem um crime próprio para isso: a certidão ideologicamente falsa.","teSitua":{"termos":[{"termo":"certifica falsamente","significado":"declara oficialmente, por escrito, um fato que não é verdadeiro."},{"termo":"tomar posse em cargo público","significado":"assumir formalmente o cargo depois de aprovado no concurso."},{"termo":"ideologicamente falso","significado":"papel autêntico na forma, mas com conteúdo mentiroso."},{"termo":"falsidade material","significado":"falsificação da própria forma do papel, como montar, rasurar ou alterar o documento."}],"exemplo":"Sílvio, escrevente do distribuidor criminal, emite certidão dizendo que seu sobrinho não tem processos, embora haja um em andamento. Com a certidão, o sobrinho toma posse como guarda municipal. Sílvio responde por certidão ideologicamente falsa."}},{"id":"aut.penal_tj.funcionario_publico.0001","subtopico":"penal_tj.adm_publica.funcionario_publico","tipo":"multipla","dificuldade":3,"enunciado":"Um escrevente que não tem a guarda do cofre da vara, aproveitando-se de que conhece o código de acesso por ser servidor do cartório, abre o cofre e subtrai dinheiro apreendido em um processo. Nos termos do Código Penal, a conduta configura","alternativas":{"A":"furto simples, por não ter o servidor a posse do dinheiro.","B":"peculato-apropriação, previsto no caput do art. 312.","C":"peculato mediante erro de outrem.","D":"peculato, na modalidade do § 1º do art. 312, com a mesma pena do caput.","E":"peculato culposo, com pena de detenção de três meses a um ano."},"gabarito":"D","explicacao":"O art. 312, § 1º, aplica a mesma pena do peculato (reclusão de dois a doze anos, e multa) ao funcionário público que, embora não tendo a posse do dinheiro, valor ou bem, o subtrai, ou concorre para que seja subtraído, valendo-se de facilidade que lhe proporciona a qualidade de funcionário.","explicacoes":{"A":"Como se valeu da facilidade proporcionada pela condição de funcionário, há peculato, não furto comum.","B":"O caput exige que o funcionário tenha a posse do bem em razão do cargo, o que não ocorre.","C":"O peculato mediante erro de outrem (art. 313) pressupõe recebimento por erro de terceiro.","D":"Correta: subtrair, sem ter a posse, valendo-se da facilidade do cargo é o peculato do § 1º, com a mesma pena do caput.","E":"A conduta foi dolosa; o peculato culposo é concorrer culposamente para o crime de outrem."},"fonte":"Código Penal, art. 312, caput e § 1º","mastigado":"A resposta é a letra D. O dinheiro não estava sob os cuidados dele, mas ele só conseguiu pegá-lo porque trabalhava ali e sabia o código. A lei trata isso também como peculato, com a mesma pena de quem desvia o que tem nas mãos.","teSitua":{"termos":[{"termo":"guarda do cofre","significado":"responsabilidade de cuidar do cofre e do que está dentro dele."},{"termo":"subtrai","significado":"tira para si, às escondidas, algo que pertence a outro."},{"termo":"peculato","significado":"crime do servidor que se apropria, desvia ou subtrai bem, valendo-se do cargo."},{"termo":"posse","significado":"ter a coisa sob seu poder e cuidado."}],"exemplo":"Flávio é escrevente da 1ª Vara Criminal, mas quem cuida do cofre é a chefe Rita. Como viu Rita digitar o código, Flávio abre o cofre à noite e leva R$ 3.000,00 apreendidos em um processo. Ele responde por peculato, pela facilidade que o cargo lhe deu."}},{"id":"aut.penal_tj.funcionario_publico.0002","subtopico":"penal_tj.adm_publica.funcionario_publico","tipo":"certo_errado","dificuldade":2,"enunciado":"No peculato culposo, a reparação do dano extingue a punibilidade mesmo quando feita depois da sentença irrecorrível.","gabarito":"E","explicacao":"O art. 312, § 3º, do CP dispõe que, no peculato culposo, a reparação do dano, se precede à sentença irrecorrível, extingue a punibilidade; se lhe é posterior, reduz de metade a pena imposta.","fonte":"Código Penal, art. 312, §§ 2º e 3º","mastigado":"Errado. Devolver o prejuízo só livra o servidor da punição se for feito antes da condenação definitiva. Se a reparação vier depois, a pena apenas cai pela metade.","teSitua":{"termos":[{"termo":"peculato culposo","significado":"quando o servidor, por descuido, facilita que outra pessoa desvie bem público."},{"termo":"sentença irrecorrível","significado":"decisão final contra a qual não cabe mais recurso."},{"termo":"extingue a punibilidade","significado":"faz desaparecer a possibilidade de o Estado punir a pessoa."}],"exemplo":"Lívia, escrevente, esquece aberto o armário dos bens apreendidos, e um estagiário leva um relógio. Processada por peculato culposo, ela paga o valor do relógio antes da condenação definitiva. Com isso, sua punibilidade é extinta e ela não recebe pena."}},{"id":"aut.penal_tj.funcionario_publico.0003","subtopico":"penal_tj.adm_publica.funcionario_publico","tipo":"multipla","dificuldade":3,"enunciado":"Uma escrevente, para dar andamento mais rápido a um processo, exige de uma das partes o pagamento de R$ 500,00, dizendo que, sem isso, os autos ficarão parados. Nos termos do Código Penal, a conduta configura","alternativas":{"A":"concussão, punida com reclusão de dois a doze anos, e multa.","B":"corrupção passiva, punida com reclusão de dois a doze anos, e multa.","C":"excesso de exação, punido com reclusão de três a oito anos, e multa.","D":"prevaricação, punida com detenção de três meses a um ano, e multa.","E":"corrupção passiva privilegiada, punida com detenção de três meses a um ano, ou multa."},"gabarito":"A","explicacao":"O art. 316 pune quem exige, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida, com reclusão de 2 (dois) a 12 (doze) anos, e multa. O verbo central é exigir; na corrupção passiva (art. 317), os verbos são solicitar, receber ou aceitar promessa.","explicacoes":{"A":"Correta: exigir vantagem indevida em razão da função é concussão (art. 316).","B":"Na corrupção passiva o funcionário solicita ou recebe; aqui ele exige, impondo a vantagem.","C":"O excesso de exação envolve exigência de tributo ou contribuição social.","D":"A prevaricação é retardar ou deixar de praticar ato por interesse ou sentimento pessoal, sem exigir vantagem.","E":"A forma privilegiada do art. 317, § 2º, é ceder a pedido ou influência de outrem."},"fonte":"Código Penal, art. 316, caput","mastigado":"A resposta é a letra A. A servidora não pediu um favor: ela impôs o pagamento, usando o poder do cargo como ameaça. Quando o funcionário exige uma vantagem que não é devida, o crime é concussão.","teSitua":{"termos":[{"termo":"exige","significado":"impõe, obriga, com tom de ordem ou ameaça."},{"termo":"dar andamento","significado":"fazer o processo seguir para a próxima etapa."},{"termo":"concussão","significado":"crime do funcionário que exige vantagem indevida por causa da função."},{"termo":"excesso de exação","significado":"crime do funcionário que cobra tributo indevido ou cobra de forma humilhante."}],"exemplo":"A escrevente Marta diz ao advogado Álvaro que o processo do cliente dele só sairá da pilha se ele lhe pagar R$ 500,00. Álvaro, com medo de mais atraso, grava a conversa e procura a corregedoria. Marta responde por concussão."}},{"id":"aut.penal_tj.funcionario_publico.0004","subtopico":"penal_tj.adm_publica.funcionario_publico","tipo":"certo_errado","dificuldade":2,"enunciado":"Pratica concussão o funcionário que exige vantagem indevida ainda que fora da função ou antes de assumi-la, desde que a exigência ocorra em razão dela.","gabarito":"C","explicacao":"O art. 316 descreve a conduta de exigir, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida.","fonte":"Código Penal, art. 316, caput","mastigado":"Certo. Não importa se a pessoa ainda não começou a trabalhar no cargo ou se está de folga. Se ela usa o cargo para exigir uma vantagem que não é devida, comete concussão.","teSitua":{"termos":[{"termo":"antes de assumi-la","significado":"antes de tomar posse e começar a exercer a função."},{"termo":"em razão dela","significado":"por causa da função pública que a pessoa tem ou vai ter."}],"exemplo":"Bernardo foi nomeado escrevente e só tomará posse na semana seguinte. Mesmo assim, procura um conhecido que tem processo na vara onde vai trabalhar e exige R$ 1.000,00 para cuidar bem do caso. Bernardo comete concussão, porque exigiu em razão da futura função."}},{"id":"aut.penal_tj.funcionario_publico.0005","subtopico":"penal_tj.adm_publica.funcionario_publico","tipo":"multipla","dificuldade":3,"enunciado":"O funcionário público que exige tributo que sabe ser indevido, ou que, quando devido, emprega na cobrança meio vexatório ou gravoso que a lei não autoriza, comete","alternativas":{"A":"concussão simples, punida com reclusão de dois a doze anos, e multa.","B":"corrupção passiva, punida com reclusão de dois a doze anos, e multa.","C":"peculato, punido com reclusão de dois a doze anos, e multa.","D":"emprego irregular de verbas públicas, punido com detenção de um a três meses, ou multa.","E":"excesso de exação, punido com reclusão de três a oito anos, e multa."},"gabarito":"E","explicacao":"O art. 316, § 1º, define o excesso de exação: exigir tributo ou contribuição social que sabe ou deveria saber indevido, ou, quando devido, empregar na cobrança meio vexatório ou gravoso, que a lei não autoriza. A pena é de reclusão, de 3 (três) a 8 (oito) anos, e multa.","explicacoes":{"A":"A cobrança de tributo indevido ou por meio vexatório tem figura própria no § 1º do art. 316.","B":"Na corrupção passiva há solicitação ou recebimento de vantagem para o funcionário ou terceiro.","C":"Não há apropriação ou desvio de bem de que o funcionário tenha a posse.","D":"O art. 315 é dar às verbas públicas aplicação diversa da legal.","E":"Correta: é o excesso de exação do art. 316, § 1º."},"fonte":"Código Penal, art. 316, § 1º","mastigado":"A resposta é a letra E. O servidor que cobra um tributo sabendo que ele não é devido, ou que cobra um tributo devido de forma humilhante, comete excesso de exação. A pena é de três a oito anos de reclusão, e multa.","teSitua":{"termos":[{"termo":"tributo","significado":"valor que a pessoa é obrigada por lei a pagar ao Estado, como imposto ou taxa."},{"termo":"meio vexatório ou gravoso","significado":"forma de cobrança que humilha ou causa peso maior do que o necessário."},{"termo":"excesso de exação","significado":"crime do funcionário que cobra tributo indevido ou cobra de forma abusiva."}],"exemplo":"O fiscal Teodoro vai à padaria de Dona Neide cobrar uma taxa realmente devida e, para pressioná-la, grita no balcão, diante dos clientes, que ela é caloteira. Ele usou meio vexatório que a lei não autoriza e responde por excesso de exação."}},{"id":"aut.penal_tj.funcionario_publico.0006","subtopico":"penal_tj.adm_publica.funcionario_publico","tipo":"certo_errado","dificuldade":3,"enunciado":"O funcionário que pratica, deixa de praticar ou retarda ato de ofício, com infração de dever funcional, cedendo a pedido ou influência de outrem, comete corrupção passiva punida com detenção de três meses a um ano, ou multa.","gabarito":"C","explicacao":"É a corrupção passiva privilegiada do art. 317, § 2º: o funcionário não recebe vantagem, mas cede a pedido ou influência de outrem, com pena de detenção, de três meses a um ano, ou multa.","fonte":"Código Penal, art. 317, § 2º","mastigado":"Certo. Quando o servidor descumpre seu dever só para atender ao pedido de alguém, sem ganhar nada em troca, ainda é corrupção passiva, mas na forma mais leve, com detenção ou multa.","teSitua":{"termos":[{"termo":"ato de ofício","significado":"ato que o funcionário tem o dever de praticar por causa do cargo."},{"termo":"cedendo a pedido ou influência","significado":"atendendo ao pedido ou à pressão de outra pessoa."},{"termo":"infração de dever funcional","significado":"descumprimento de obrigação do cargo."}],"exemplo":"O escrevente Gilson recebe telefonema de um vereador pedindo que segure a juntada de um documento contra um aliado. Gilson não ganha nada, mas, para agradar o vereador, deixa o papel na gaveta por um mês. Ele comete corrupção passiva privilegiada."}},{"id":"aut.penal_tj.funcionario_publico.0007","subtopico":"penal_tj.adm_publica.funcionario_publico","tipo":"multipla","dificuldade":2,"enunciado":"Um oficial de justiça recebe, por erro do devedor, o valor de uma dívida em dinheiro durante o cumprimento de um mandado, quando o correto seria o depósito judicial, e fica com a quantia para si. Nos termos do Código Penal, a conduta corresponde a","alternativas":{"A":"peculato-furto, com pena de reclusão de dois a doze anos, e multa.","B":"peculato mediante erro de outrem, com pena de reclusão de um a quatro anos, e multa.","C":"concussão, com pena de reclusão de dois a doze anos, e multa.","D":"apropriação indébita comum, por ter o dinheiro vindo de particular.","E":"excesso de exação, com pena de reclusão de três a oito anos, e multa."},"gabarito":"B","explicacao":"O art. 313 pune quem se apropria de dinheiro ou qualquer utilidade que, no exercício do cargo, recebeu por erro de outrem, com reclusão de um a quatro anos, e multa.","explicacoes":{"A":"O oficial não subtraiu nada; recebeu o dinheiro por erro do devedor.","B":"Correta: apropriar-se do que recebeu, no exercício do cargo, por erro de outrem é o art. 313.","C":"Não houve exigência de vantagem.","D":"Há tipo próprio para o funcionário que se apropria do que recebeu por erro no exercício do cargo (art. 313).","E":"Não houve cobrança de tributo."},"fonte":"Código Penal, art. 313","mastigado":"A resposta é a letra B. O dinheiro chegou às mãos do oficial por um engano do devedor, durante o trabalho. Ficar com ele é um tipo especial de peculato, o peculato por erro de outra pessoa, com pena de um a quatro anos.","teSitua":{"termos":[{"termo":"oficial de justiça","significado":"servidor que cumpre fora do fórum as ordens do juiz, como citações e penhoras."},{"termo":"depósito judicial","significado":"dinheiro colocado em conta do banco à disposição do juiz do processo."},{"termo":"apropriação indébita","significado":"crime de quem fica com coisa alheia que estava legitimamente em seu poder."}],"exemplo":"O oficial Josué vai à casa de Afonso cumprir um mandado de pagamento. Afonso, achando que é assim que funciona, entrega R$ 2.000,00 em dinheiro a Josué, em vez de depositar em juízo. Josué guarda o valor para si. Ele comete peculato mediante erro de outrem."}},{"id":"aut.penal_tj.funcionario_publico.0008","subtopico":"penal_tj.adm_publica.funcionario_publico","tipo":"certo_errado","dificuldade":3,"enunciado":"O funcionário autorizado que insere dados falsos nos sistemas informatizados da Administração Pública, com o fim de obter vantagem indevida para si ou para outrem, comete crime punido com detenção, de três meses a dois anos, e multa.","gabarito":"E","explicacao":"A inserção de dados falsos em sistema de informações (art. 313-A) é punida com reclusão, de 2 (dois) a 12 (doze) anos, e multa. A detenção de três meses a dois anos, e multa, é a pena do art. 313-B (modificar ou alterar, sem autorização, sistema de informações ou programa de informática).","fonte":"Código Penal, arts. 313-A e 313-B","mastigado":"Errado. Colocar dados falsos no sistema do órgão para obter vantagem é crime grave, com reclusão de dois a doze anos. A pena mais leve citada é a de quem mexe no próprio programa sem autorização.","teSitua":{"termos":[{"termo":"funcionário autorizado","significado":"servidor que tem permissão para operar aquele sistema."},{"termo":"sistemas informatizados","significado":"programas e bancos de dados de computador usados pelo órgão público."}],"exemplo":"Débora, servidora com senha do sistema de custas, lança como paga a guia de um amigo que nunca pagou nada, para livrá-lo da cobrança. Ela responde por inserção de dados falsos em sistema de informações, com reclusão de dois a doze anos."}},{"id":"aut.penal_tj.funcionario_publico.0009","subtopico":"penal_tj.adm_publica.funcionario_publico","tipo":"multipla","dificuldade":3,"enunciado":"Um escrevente, que tinha a guarda de processo físico em razão do cargo, inutiliza parcialmente os autos, arrancando folhas, para atrapalhar uma das partes. Se o fato não constituir crime mais grave, ele responde por","alternativas":{"A":"supressão de documento, com reclusão de dois a seis anos, e multa.","B":"subtração ou inutilização de livro ou documento, com reclusão de dois a cinco anos.","C":"extravio, sonegação ou inutilização de livro ou documento, com reclusão de um a quatro anos.","D":"peculato, com reclusão de dois a doze anos, e multa.","E":"prevaricação, com detenção de três meses a um ano, e multa."},"gabarito":"C","explicacao":"O art. 314 pune quem extravia livro oficial ou qualquer documento de que tem a guarda em razão do cargo, ou o sonega ou inutiliza, total ou parcialmente, com reclusão de um a quatro anos, se o fato não constitui crime mais grave. É crime próprio do funcionário que tem a guarda.","explicacoes":{"A":"A supressão de documento (art. 305) é crime contra a fé pública que não exige a guarda em razão do cargo; o art. 314 é específico.","B":"O art. 337 está entre os crimes de particular contra a Administração e trata de documento confiado à custódia de funcionário; aqui o próprio guardião inutilizou.","C":"Correta: o funcionário que inutiliza documento de que tem a guarda em razão do cargo comete o crime do art. 314.","D":"Não houve apropriação nem desvio do bem.","E":"A prevaricação exige retardar ou deixar de praticar ato de ofício para satisfazer interesse pessoal."},"fonte":"Código Penal, art. 314","mastigado":"A resposta é a letra C. O processo estava sob os cuidados do escrevente por causa do cargo. Ao arrancar folhas, ele estragou em parte um documento que devia proteger. A lei tem um crime próprio para isso, com pena de um a quatro anos.","teSitua":{"termos":[{"termo":"guarda","significado":"dever de cuidar e conservar algo que lhe foi confiado."},{"termo":"inutiliza parcialmente","significado":"estraga uma parte, de modo que ela não sirva mais."},{"termo":"sonegação","significado":"esconder ou deixar de apresentar algo que se tinha o dever de entregar."}],"exemplo":"O escrevente Nilton é responsável pelos processos da estante 4. Para prejudicar o ex-sócio, que é parte em uma ação, arranca do processo o laudo favorável a ele. Descoberto, Nilton responde pelo crime de inutilização de documento de que tinha a guarda pelo cargo."}},{"id":"aut.penal_tj.funcionario_publico.0010","subtopico":"penal_tj.adm_publica.funcionario_publico","tipo":"multipla","dificuldade":3,"enunciado":"Sobre a corrupção passiva (art. 317 do Código Penal), assinale a alternativa correta.","alternativas":{"A":"A pena é aumentada de um terço se, em consequência da vantagem ou promessa, o funcionário retarda ou deixa de praticar ato de ofício ou o pratica infringindo dever funcional.","B":"Só se configura se o funcionário efetivamente receber a vantagem, não bastando aceitar a promessa.","C":"Não se configura se o agente ainda não assumiu a função, mesmo que aja em razão dela.","D":"A pena é de reclusão, de três a oito anos, e multa.","E":"Exige que a vantagem seja destinada ao próprio funcionário, e não a terceiro."},"gabarito":"A","explicacao":"O art. 317 pune solicitar ou receber, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida, ou aceitar promessa de tal vantagem, com reclusão de 2 a 12 anos, e multa. O § 1º aumenta a pena de um terço se o funcionário, em consequência da vantagem ou promessa, retarda ou deixa de praticar ato de ofício ou o pratica infringindo dever funcional.","explicacoes":{"A":"Correta: é a causa de aumento do § 1º do art. 317.","B":"Aceitar promessa de vantagem já configura o crime.","C":"O tipo alcança a conduta praticada antes de assumir a função, mas em razão dela.","D":"A pena é de reclusão de dois a doze anos, e multa; três a oito anos é a do excesso de exação.","E":"A vantagem pode ser para si ou para outrem."},"fonte":"Código Penal, art. 317, caput e § 1º","mastigado":"A resposta é a letra A. Se o servidor, por causa do dinheiro ou da promessa, chega a atrasar, deixar de fazer ou fazer errado o seu trabalho, a pena da corrupção cresce um terço. Aceitar a promessa já basta para o crime.","teSitua":{"termos":[{"termo":"aceitar promessa","significado":"concordar em receber depois uma vantagem que foi oferecida."},{"termo":"ato de ofício","significado":"ato que o funcionário tem o dever de praticar por causa do cargo."},{"termo":"dever funcional","significado":"obrigação que o servidor tem por causa do cargo."}],"exemplo":"O escrevente Caetano aceita a promessa de R$ 2.000,00 de um réu para atrasar a expedição de um mandado. Ele de fato segura o mandado por dois meses. Por ter deixado de praticar o ato por causa da promessa, sua pena por corrupção passiva aumenta um terço."}},{"id":"aut.penal_tj.particular.0001","subtopico":"penal_tj.adm_publica.particular","tipo":"multipla","dificuldade":3,"enunciado":"Um particular, que nunca foi servidor, veste colete com a inscrição \\"oficial de justiça\\", vai à casa de um devedor e, dizendo cumprir ordem judicial, recolhe a ele próprio R$ 3.000,00 a título de \\"pagamento da dívida\\". Nos termos do Código Penal, além de eventual crime patrimonial, a conduta configura","alternativas":{"A":"usurpação de função pública simples, com detenção de três meses a dois anos, e multa.","B":"exercício funcional ilegalmente prolongado, com detenção de quinze dias a um mês, ou multa.","C":"usurpação de função pública com vantagem, punida com reclusão de dois a cinco anos, e multa.","D":"tráfico de influência, punido com reclusão de dois a cinco anos, e multa.","E":"falsa identidade, punida com detenção de três meses a um ano, ou multa."},"gabarito":"C","explicacao":"O art. 328 pune quem usurpa o exercício de função pública, com detenção de três meses a dois anos, e multa. Se do fato o agente aufere vantagem, a pena é de reclusão, de dois a cinco anos, e multa (parágrafo único).","explicacoes":{"A":"Como o agente auferiu vantagem, incide a forma qualificada do parágrafo único.","B":"O art. 324 é crime do próprio funcionário que antecipa ou prolonga o exercício; o agente nunca foi servidor.","C":"Correta: usurpar a função e auferir vantagem é a forma qualificada do art. 328, parágrafo único.","D":"O tráfico de influência é pedir vantagem a pretexto de influir em ato de funcionário, não exercer a própria função.","E":"Ele não só se atribuiu identidade falsa: praticou atos da função pública, o que caracteriza a usurpação."},"fonte":"Código Penal, art. 328, caput e parágrafo único","mastigado":"A resposta é a letra C. O homem fingiu ser oficial de justiça e chegou a agir como se fosse um, recebendo dinheiro. Isso é usurpação de função pública. Como ele ganhou vantagem com isso, a pena sobe para dois a cinco anos de reclusão, e multa.","teSitua":{"termos":[{"termo":"usurpação de função pública","significado":"exercer, sem ter direito, uma função que é do poder público."},{"termo":"aufere vantagem","significado":"obtém algum benefício, como dinheiro."},{"termo":"oficial de justiça","significado":"servidor que cumpre fora do fórum as ordens do juiz."}],"exemplo":"Valdir compra um colete escrito \\"oficial de justiça\\" e bate na casa de Dona Iara, dizendo que veio cobrar uma dívida por ordem do juiz. Ela entrega R$ 3.000,00 a ele. Valdir nunca foi servidor e, por ter auferido vantagem, responde pela usurpação de função na forma qualificada."}},{"id":"aut.penal_tj.particular.0002","subtopico":"penal_tj.adm_publica.particular","tipo":"certo_errado","dificuldade":2,"enunciado":"Na usurpação de função pública, se do fato o agente aufere vantagem, a pena é de reclusão, de dois a cinco anos, e multa.","gabarito":"C","explicacao":"É a forma qualificada do art. 328, parágrafo único. A forma simples (caput) tem pena de detenção, de três meses a dois anos, e multa.","fonte":"Código Penal, art. 328, parágrafo único","mastigado":"Certo. Fingir que exerce uma função pública já é crime. Se, além disso, a pessoa ganha alguma vantagem com o fingimento, a pena fica maior: dois a cinco anos de reclusão, e multa.","teSitua":{"termos":[{"termo":"usurpação de função pública","significado":"exercer, sem ter direito, uma função que é do poder público."},{"termo":"aufere vantagem","significado":"obtém algum benefício, como dinheiro."}],"exemplo":"Tales se apresenta como fiscal da prefeitura e \\"multa\\" comerciantes, ficando com o dinheiro. Ele nunca foi fiscal. Como ganhou vantagem com a função que usurpou, responde com pena de reclusão de dois a cinco anos, e multa."}},{"id":"aut.penal_tj.particular.0003","subtopico":"penal_tj.adm_publica.particular","tipo":"multipla","dificuldade":2,"enunciado":"Durante o cumprimento de um mandado de penhora, o devedor ameaça de morte o oficial de justiça para impedir a apreensão do veículo, mas o ato é concluído mesmo assim. Nos termos do Código Penal, o devedor comete","alternativas":{"A":"resistência, punida com detenção de dois meses a dois anos.","B":"resistência qualificada, punida com reclusão de um a três anos.","C":"desobediência, punida com detenção de quinze dias a seis meses, e multa.","D":"desacato, punido com detenção de seis meses a dois anos, ou multa.","E":"coação no curso do processo, punida com reclusão de um a quatro anos, e multa."},"gabarito":"A","explicacao":"O art. 329 pune quem se opõe à execução de ato legal, mediante violência ou ameaça a funcionário competente para executá-lo ou a quem lhe esteja prestando auxílio, com detenção de dois meses a dois anos. Só se o ato, em razão da resistência, não se executa, a pena é de reclusão de um a três anos (§ 1º).","explicacoes":{"A":"Correta: houve oposição com ameaça, mas o ato foi executado; aplica-se o caput do art. 329.","B":"A forma qualificada exige que o ato não se execute por causa da resistência.","C":"A desobediência não envolve violência ou ameaça.","D":"O fim do agente era impedir o ato, e não ofender a dignidade do funcionário.","E":"A coação no curso do processo (art. 344) visa favorecer interesse em processo, com violência ou grave ameaça contra quem nele funciona; a oposição à execução de ato legal tem tipo próprio no art. 329."},"fonte":"Código Penal, art. 329, caput e § 1º","mastigado":"A resposta é a letra A. O devedor ameaçou o oficial para impedir a penhora. Isso é resistência. Como a penhora foi feita mesmo assim, aplica-se a pena simples, de dois meses a dois anos de detenção.","teSitua":{"termos":[{"termo":"mandado de penhora","significado":"ordem do juiz para separar bens do devedor que vão garantir o pagamento da dívida."},{"termo":"apreensão","significado":"ato de recolher e guardar um bem por ordem da autoridade."},{"termo":"resistência qualificada","significado":"forma mais grave da resistência, quando o ato oficial acaba não sendo cumprido."}],"exemplo":"O oficial Celso vai à casa de Mauro para penhorar um carro. Mauro grita que vai matá-lo se tocar no veículo. Celso chama reforço e conclui a penhora. Mauro responde por resistência simples, porque o ato foi executado."}},{"id":"aut.penal_tj.particular.0004","subtopico":"penal_tj.adm_publica.particular","tipo":"certo_errado","dificuldade":2,"enunciado":"No crime de resistência, ainda que o ato legal, em razão da resistência, não se execute, a pena é a mesma da forma simples, de detenção de dois meses a dois anos.","gabarito":"E","explicacao":"O art. 329, § 1º, do CP prevê pena de reclusão, de um a três anos, se o ato, em razão da resistência, não se executa. A detenção de dois meses a dois anos é a pena da forma simples (caput).","fonte":"Código Penal, art. 329, § 1º","mastigado":"Errado. Quando a pessoa consegue impedir que a ordem seja cumprida, a lei pune com mais rigor: a pena passa a ser de um a três anos de reclusão, e não a mesma da resistência simples.","teSitua":{"termos":[{"termo":"ato legal","significado":"ato da autoridade praticado de acordo com a lei."},{"termo":"não se executa","significado":"deixa de ser cumprido como a autoridade mandou."}],"exemplo":"Ao ver o oficial chegar para levar a geladeira penhorada, Josias o empurra para fora e tranca o portão com um cadeado. O oficial vai embora sem cumprir a ordem. Como o ato não foi executado por causa da resistência, Josias responde pela forma qualificada."}},{"id":"aut.penal_tj.particular.0005","subtopico":"penal_tj.adm_publica.particular","tipo":"certo_errado","dificuldade":3,"enunciado":"Pratica resistência quem, sem empregar violência ou ameaça, simplesmente se recusa a cumprir a ordem legal dada pelo oficial de justiça.","gabarito":"E","explicacao":"A resistência (art. 329) exige oposição mediante violência ou ameaça a funcionário competente ou a quem lhe preste auxílio. A simples recusa, sem violência ou ameaça, pode configurar desobediência (art. 330).","fonte":"Código Penal, arts. 329 e 330","mastigado":"Errado. Para ser resistência a pessoa precisa usar violência ou ameaça contra o funcionário. Só se recusar a cumprir a ordem, sem agredir nem ameaçar, é outro crime: desobediência.","teSitua":{"termos":[{"termo":"se recusa a cumprir","significado":"diz que não vai fazer o que foi mandado."},{"termo":"ordem legal","significado":"ordem dada pela autoridade de acordo com a lei."}],"exemplo":"O oficial de justiça manda Heitor entregar os documentos do carro, como determinou o juiz. Heitor apenas cruza os braços e diz que não vai entregar, sem ameaçar ninguém. Ele não comete resistência; pode responder por desobediência."}},{"id":"aut.penal_tj.particular.0006","subtopico":"penal_tj.adm_publica.particular","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do Código Penal, desobedecer a ordem legal de funcionário público é crime punido com","alternativas":{"A":"detenção, de seis meses a dois anos, ou multa.","B":"detenção, de dois meses a dois anos.","C":"reclusão, de um a três anos.","D":"detenção, de quinze dias a seis meses, e multa.","E":"detenção, de três meses a dois anos, ou multa."},"gabarito":"D","explicacao":"O art. 330 pune quem desobedece a ordem legal de funcionário público com detenção, de quinze dias a seis meses, e multa.","explicacoes":{"A":"É a pena do desacato (art. 331).","B":"É a pena da resistência simples (art. 329, caput).","C":"É a pena da resistência qualificada (art. 329, § 1º).","D":"Correta: é a pena da desobediência.","E":"É a pena do art. 359 (desobediência a decisão judicial sobre perda ou suspensão de direito)."},"fonte":"Código Penal, art. 330","mastigado":"A resposta é a letra D. Não cumprir uma ordem legal de servidor público é crime de desobediência, com pena pequena: detenção de quinze dias a seis meses, mais multa.","teSitua":{"termos":[{"termo":"desobedecer","significado":"deixar de cumprir uma ordem."},{"termo":"detenção","significado":"tipo de pena de prisão mais leve, que não começa em regime fechado."}],"exemplo":"O escrevente Otávio, cumprindo ordem do juiz, manda o depositário Lauro apresentar em cartório os bens que guarda. Lauro ignora a ordem de propósito. Ele responde por desobediência, com detenção de quinze dias a seis meses, e multa."}},{"id":"aut.penal_tj.particular.0007","subtopico":"penal_tj.adm_publica.particular","tipo":"certo_errado","dificuldade":3,"enunciado":"No crime de resistência, a pena correspondente à violência empregada contra o funcionário fica absorvida pela pena da resistência.","gabarito":"E","explicacao":"O art. 329, § 2º, do CP determina que as penas da resistência são aplicáveis sem prejuízo das correspondentes à violência. Não há absorção: o agente responde também, por exemplo, pela lesão corporal.","fonte":"Código Penal, art. 329, § 2º","mastigado":"Errado. A lei manda somar as penas. Quem resiste usando violência responde pela resistência e também pela agressão que praticou contra o funcionário.","teSitua":{"termos":[{"termo":"fica absorvida","significado":"deixa de ser punida à parte, por ficar englobada na outra pena."},{"termo":"violência empregada","significado":"força física usada contra alguém."}],"exemplo":"Para impedir a busca na loja, Fausto dá um soco no policial que acompanhava a diligência e quebra o nariz dele. Fausto responde por resistência e também por lesão corporal, com as duas penas somadas."}},{"id":"aut.penal_tj.particular.0008","subtopico":"penal_tj.adm_publica.particular","tipo":"multipla","dificuldade":2,"enunciado":"No balcão do cartório, uma parte, irritada com a demora do processo, chama a escrevente de \\"incompetente e vagabunda\\" diante de outras pessoas. Nos termos do Código Penal, a parte comete","alternativas":{"A":"injúria simples, por se tratar de ofensa pessoal.","B":"desacato, punido com detenção de seis meses a dois anos, ou multa.","C":"desobediência, punida com detenção de quinze dias a seis meses, e multa.","D":"resistência, punida com detenção de dois meses a dois anos.","E":"desacato, punido com reclusão de dois a cinco anos, e multa."},"gabarito":"B","explicacao":"O art. 331 pune quem desacata funcionário público no exercício da função ou em razão dela, com detenção de seis meses a dois anos, ou multa.","explicacoes":{"A":"A ofensa foi dirigida à servidora no exercício da função; há tipo próprio no art. 331.","B":"Correta: ofender funcionário no exercício da função é desacato.","C":"Não houve descumprimento de ordem legal.","D":"Não houve oposição a ato legal com violência ou ameaça.","E":"A pena do desacato é de detenção de seis meses a dois anos, ou multa."},"fonte":"Código Penal, art. 331","mastigado":"A resposta é a letra B. A parte xingou a servidora enquanto ela trabalhava, por causa do serviço. Isso é desacato. A pena é de seis meses a dois anos de detenção, ou multa.","teSitua":{"termos":[{"termo":"desacato","significado":"ofensa ou humilhação dirigida a servidor no exercício da função ou por causa dela."},{"termo":"injúria","significado":"ofensa à honra de uma pessoa, xingando-a ou humilhando-a."}],"exemplo":"Raquel espera há meses o alvará de seu processo. No balcão, grita com a escrevente Ivone, chamando-a de incompetente e vagabunda na frente de todos. Raquel responde por desacato, porque ofendeu a servidora no exercício da função."}},{"id":"aut.penal_tj.particular.0009","subtopico":"penal_tj.adm_publica.particular","tipo":"certo_errado","dificuldade":3,"enunciado":"Só há desacato se o funcionário público estiver no exercício da função no momento da ofensa; a ofensa feita fora do expediente não configura o crime, ainda que em razão da função.","gabarito":"E","explicacao":"O art. 331 pune desacatar funcionário público no exercício da função ou em razão dela. A ofensa feita fora do expediente, mas por causa da função, também configura desacato.","fonte":"Código Penal, art. 331","mastigado":"Errado. O desacato também acontece quando o servidor está de folga, desde que a ofensa seja por causa do trabalho dele. Basta que a humilhação tenha relação com a função.","teSitua":{"termos":[{"termo":"no exercício da função","significado":"enquanto o servidor está trabalhando."},{"termo":"em razão da função","significado":"por causa do trabalho que o servidor exerce."},{"termo":"fora do expediente","significado":"fora do horário de trabalho."}],"exemplo":"No sábado, no supermercado, Breno reconhece a escrevente que cuidou do seu processo e a humilha em voz alta por causa de um despacho que demorou. Mesmo fora do expediente, a ofensa foi em razão da função, e Breno comete desacato."}},{"id":"aut.penal_tj.particular.0010","subtopico":"penal_tj.adm_publica.particular","tipo":"multipla","dificuldade":3,"enunciado":"Gilberto cobra R$ 10.000,00 de um empresário a pretexto de influir em ato de um fiscal da prefeitura, insinuando que parte do dinheiro também será entregue ao fiscal. Nos termos do Código Penal, Gilberto comete","alternativas":{"A":"corrupção ativa, com reclusão de dois a doze anos, e multa.","B":"corrupção passiva, com reclusão de dois a doze anos, e multa.","C":"tráfico de influência, com reclusão de dois a cinco anos, e multa, sem aumento.","D":"estelionato, por não ter influência real sobre o fiscal.","E":"tráfico de influência, com a pena aumentada da metade."},"gabarito":"E","explicacao":"O art. 332 pune quem solicita, exige, cobra ou obtém, para si ou para outrem, vantagem ou promessa de vantagem, a pretexto de influir em ato praticado por funcionário público no exercício da função, com reclusão de 2 a 5 anos, e multa. O parágrafo único aumenta a pena da metade se o agente alega ou insinua que a vantagem é também destinada ao funcionário.","explicacoes":{"A":"Gilberto não ofereceu vantagem a funcionário; ele cobrou do empresário.","B":"Gilberto não é funcionário público.","C":"A insinuação de que o dinheiro vai também para o fiscal faz incidir o aumento da metade.","D":"Há tipo específico para quem cobra vantagem a pretexto de influir em ato de funcionário (art. 332).","E":"Correta: tráfico de influência com aumento da metade (art. 332, parágrafo único)."},"fonte":"Código Penal, art. 332, caput e parágrafo único","mastigado":"A resposta é a letra E. Gilberto vendeu um suposto prestígio junto ao fiscal: isso é tráfico de influência. Como ele ainda deu a entender que parte do dinheiro iria para o fiscal, a pena aumenta pela metade.","teSitua":{"termos":[{"termo":"a pretexto de influir","significado":"usando como desculpa a promessa de convencer ou pressionar alguém."},{"termo":"insinuando","significado":"dando a entender, sem dizer claramente."},{"termo":"tráfico de influência","significado":"crime de quem cobra vantagem dizendo que pode influenciar um servidor."}],"exemplo":"Gilberto diz ao empresário Sandro que é amigo do fiscal responsável pela licença do restaurante e que, por R$ 10.000,00, garante a aprovação, \\"porque o fiscal também precisa ganhar o dele\\". Gilberto responde por tráfico de influência com a pena aumentada da metade."}},{"id":"aut.penal_tj.particular.0011","subtopico":"penal_tj.adm_publica.particular","tipo":"certo_errado","dificuldade":3,"enunciado":"No tráfico de influência, a pena é aumentada da metade se o agente alega ou insinua que a vantagem é também destinada ao funcionário.","gabarito":"C","explicacao":"É o que dispõe o parágrafo único do art. 332. A pena base é de reclusão, de 2 (dois) a 5 (cinco) anos, e multa.","fonte":"Código Penal, art. 332, parágrafo único","mastigado":"Certo. Quem cobra dinheiro dizendo que pode influenciar um servidor já comete tráfico de influência. Se ainda diz ou dá a entender que o servidor vai receber parte, a pena cresce pela metade, porque mancha também a imagem do servidor.","teSitua":{"termos":[{"termo":"alega ou insinua","significado":"afirma claramente ou dá a entender."},{"termo":"tráfico de influência","significado":"crime de quem cobra vantagem dizendo que pode influenciar um servidor."}],"exemplo":"Marlene pede R$ 5.000,00 a um comerciante para conseguir um alvará, dizendo que metade é \\"para o rapaz da prefeitura\\". O servidor nem sabe de nada. Mesmo assim, como Marlene insinuou que a vantagem iria para ele, a pena do tráfico de influência aumenta pela metade."}},{"id":"aut.penal_tj.particular.0012","subtopico":"penal_tj.adm_publica.particular","tipo":"multipla","dificuldade":2,"enunciado":"Um advogado oferece R$ 2.000,00 a uma escrevente para que ela retarde a expedição de um mandado de prisão contra seu cliente. A escrevente recusa e comunica o fato ao juiz. Nos termos do Código Penal, o advogado","alternativas":{"A":"comete corrupção ativa, punida com reclusão de dois a doze anos, e multa.","B":"não comete crime, porque a escrevente recusou a oferta.","C":"comete tráfico de influência, punido com reclusão de dois a cinco anos, e multa.","D":"comete corrupção passiva, punida com reclusão de dois a doze anos, e multa.","E":"comete corrupção ativa com a pena aumentada de um terço."},"gabarito":"A","explicacao":"O art. 333 pune quem oferece ou promete vantagem indevida a funcionário público, para determiná-lo a praticar, omitir ou retardar ato de ofício, com reclusão de 2 a 12 anos, e multa. O crime se perfaz com o oferecimento; a recusa do funcionário não o afasta. O aumento de um terço (parágrafo único) exige que o funcionário efetivamente retarde ou omita o ato.","explicacoes":{"A":"Correta: oferecer vantagem indevida para que a servidora retarde ato de ofício é corrupção ativa.","B":"O crime se configura com o simples oferecimento, independentemente da aceitação.","C":"O advogado não pediu vantagem a pretexto de influir; ofereceu vantagem ao próprio funcionário.","D":"A corrupção passiva é crime do funcionário que solicita ou recebe.","E":"O aumento exige que o funcionário retarde ou omita o ato, o que não aconteceu."},"fonte":"Código Penal, art. 333, caput e parágrafo único","mastigado":"A resposta é a letra A. O advogado ofereceu dinheiro à servidora para que ela atrasasse o seu trabalho. Só oferecer já é corrupção ativa, mesmo que ela tenha dito não. Como o mandado não foi atrasado, não há aumento de pena.","teSitua":{"termos":[{"termo":"retarde a expedição","significado":"atrase a emissão ou o envio do documento."},{"termo":"mandado de prisão","significado":"ordem escrita do juiz que manda prender uma pessoa."},{"termo":"corrupção ativa","significado":"crime de quem oferece ou promete vantagem indevida a servidor público."}],"exemplo":"O advogado Rodolfo chama a escrevente Clara num canto e oferece R$ 2.000,00 para que ela segure por um mês o mandado de prisão do cliente. Clara recusa e conta tudo ao juiz. Rodolfo responde por corrupção ativa, mesmo sem a oferta ter sido aceita."}},{"id":"aut.penal_tj.particular.0013","subtopico":"penal_tj.adm_publica.particular","tipo":"certo_errado","dificuldade":3,"enunciado":"Na corrupção ativa, a pena é aumentada da metade se, em razão da vantagem ou promessa, o funcionário retarda ou omite ato de ofício, ou o pratica infringindo dever funcional.","gabarito":"E","explicacao":"O parágrafo único do art. 333 prevê aumento de um terço, e não da metade, se, em razão da vantagem ou promessa, o funcionário retarda ou omite ato de ofício, ou o pratica infringindo dever funcional.","fonte":"Código Penal, art. 333, parágrafo único","mastigado":"Errado. O aumento existe, mas é de um terço, e não da metade. Ele acontece quando o servidor, por causa do dinheiro ou da promessa, chega mesmo a atrasar, deixar de fazer ou fazer errado o seu trabalho.","teSitua":{"termos":[{"termo":"ato de ofício","significado":"ato que o funcionário tem o dever de praticar por causa do cargo."},{"termo":"infringindo dever funcional","significado":"desrespeitando uma obrigação do cargo."}],"exemplo":"Pâmela promete R$ 3.000,00 ao escrevente Lino para que ele não intime uma testemunha. Lino aceita e deixa de expedir a intimação. Pela omissão do ato, a pena de Pâmela por corrupção ativa aumenta de um terço."}},{"id":"aut.penal_tj.particular.0014","subtopico":"penal_tj.adm_publica.particular","tipo":"multipla","dificuldade":2,"enunciado":"Os verbos que descrevem a conduta do crime de corrupção ativa, previsto no art. 333 do Código Penal, são","alternativas":{"A":"solicitar ou receber.","B":"exigir ou cobrar.","C":"oferecer ou prometer.","D":"solicitar, exigir, cobrar ou obter.","E":"dar, oferecer ou prometer, apenas em processo judicial."},"gabarito":"C","explicacao":"O art. 333 pune quem oferece ou promete vantagem indevida a funcionário público, para determiná-lo a praticar, omitir ou retardar ato de ofício.","explicacoes":{"A":"Solicitar ou receber são verbos da corrupção passiva (art. 317).","B":"Exigir é verbo da concussão (art. 316).","C":"Correta: oferecer ou prometer vantagem indevida.","D":"São os verbos do tráfico de influência (art. 332).","E":"\\"Dar, oferecer ou prometer\\" a testemunha ou perito é a corrupção de testemunha (art. 343), não o art. 333."},"fonte":"Código Penal, arts. 316, 317, 332, 333 e 343","mastigado":"A resposta é a letra C. Na corrupção ativa, quem age é o particular que tenta comprar o servidor: ele oferece ou promete uma vantagem. Pedir e receber são verbos do servidor corrupto, e exigir é próprio da concussão.","teSitua":{"termos":[{"termo":"corrupção ativa","significado":"crime de quem oferece ou promete vantagem indevida a servidor público."},{"termo":"solicitar","significado":"pedir algo a outra pessoa."},{"termo":"obter","significado":"conseguir, chegar a ter algo."}],"exemplo":"Na aula de revisão, a professora Ester resume: o servidor que pede propina comete corrupção passiva; o cidadão que oferece ou promete a propina comete corrupção ativa; quem exige é concussionário. Assim os alunos não confundem os lados do crime."}},{"id":"aut.penal_tj.particular.0015","subtopico":"penal_tj.adm_publica.particular","tipo":"multipla","dificuldade":3,"enunciado":"Durante uma reintegração de posse, um vizinho que ajudava o oficial de justiça a retirar os móveis é agredido pelo réu, que queria impedir o ato. O ato é cumprido. Nos termos do Código Penal, o réu comete","alternativas":{"A":"lesão corporal apenas, porque a vítima não era funcionário público.","B":"resistência, porque a violência foi dirigida a quem prestava auxílio ao funcionário, sem prejuízo da pena da violência.","C":"desacato, porque ofendeu a autoridade do oficial.","D":"desobediência, porque descumpriu a ordem judicial.","E":"resistência qualificada, punida com reclusão de um a três anos."},"gabarito":"B","explicacao":"O art. 329 pune a oposição à execução de ato legal mediante violência ou ameaça a funcionário competente para executá-lo ou a quem lhe esteja prestando auxílio. As penas aplicam-se sem prejuízo das correspondentes à violência (§ 2º). Como o ato foi cumprido, não incide o § 1º.","explicacoes":{"A":"A violência contra quem auxilia o funcionário também caracteriza resistência.","B":"Correta: é resistência, e a pena da lesão se soma.","C":"O réu não ofendeu a dignidade do funcionário; opôs-se ao ato com violência.","D":"Houve violência, o que caracteriza resistência, e não mera desobediência.","E":"A forma qualificada exige que o ato não se execute."},"fonte":"Código Penal, art. 329, caput e §§ 1º e 2º","mastigado":"A resposta é a letra B. A lei protege também quem está ajudando o oficial. Agredir esse ajudante para impedir a ordem é resistência. O réu responde ainda pela agressão. Como o ato foi cumprido, não há a forma mais grave.","teSitua":{"termos":[{"termo":"reintegração de posse","significado":"ordem do juiz para devolver um imóvel a quem tem direito a ele."},{"termo":"prestava auxílio","significado":"estava ajudando o funcionário no serviço."},{"termo":"resistência qualificada","significado":"forma mais grave da resistência, quando o ato oficial acaba não sendo cumprido."}],"exemplo":"O oficial Mário pede ao vizinho Ciro que ajude a carregar os móveis na reintegração de posse. O réu Tadeu dá um soco em Ciro para impedir a retirada. Os móveis saem mesmo assim. Tadeu responde por resistência e pela lesão corporal em Ciro."}},{"id":"aut.penal_tj.particular.0016","subtopico":"penal_tj.adm_publica.particular","tipo":"certo_errado","dificuldade":3,"enunciado":"Configura crime de desobediência deixar de cumprir ordem manifestamente ilegal emitida por funcionário público.","gabarito":"E","explicacao":"O art. 330 pune quem desobedece a ordem legal de funcionário público. A legalidade da ordem é elemento do tipo; descumprir ordem ilegal não é desobediência.","fonte":"Código Penal, art. 330","mastigado":"Errado. Só é desobediência deixar de cumprir uma ordem legal, ou seja, de acordo com a lei. Ninguém é obrigado a cumprir uma ordem claramente ilegal, e recusar-se a ela não é crime.","teSitua":{"termos":[{"termo":"manifestamente ilegal","significado":"claramente contrária à lei, sem dúvida nenhuma."},{"termo":"desobediência","significado":"crime de quem deixa de cumprir ordem legal de servidor público."}],"exemplo":"Um guarda manda Telma entregar o celular dela \\"porque ele quer ver as fotos\\", sem qualquer ordem judicial ou motivo legal. Telma se recusa. Como a ordem era manifestamente ilegal, ela não comete desobediência."}},{"id":"aut.penal_tj.particular.0017","subtopico":"penal_tj.adm_publica.particular","tipo":"certo_errado","dificuldade":2,"enunciado":"A usurpação de função pública, na forma simples, é punida com detenção, de três meses a dois anos, e multa.","gabarito":"C","explicacao":"É a pena do caput do art. 328. Se o agente aufere vantagem, a pena passa a ser de reclusão, de dois a cinco anos, e multa (parágrafo único).","fonte":"Código Penal, art. 328, caput","mastigado":"Certo. Quem exerce, sem direito, uma função pública, mas não ganha nada com isso, responde pela forma simples: detenção de três meses a dois anos, e multa.","teSitua":{"termos":[{"termo":"usurpação de função pública","significado":"exercer, sem ter direito, uma função que é do poder público."},{"termo":"forma simples","significado":"a versão básica do crime, sem as circunstâncias que aumentam a pena."}],"exemplo":"Por vaidade, Ulisses passa uma tarde no fórum dizendo ser escrevente e atendendo pessoas no balcão vazio, sem cobrar nada. Ele usurpou a função pública, mas não obteve vantagem, e responde pela forma simples."}},{"id":"aut.penal_tj.particular.0018","subtopico":"penal_tj.adm_publica.particular","tipo":"multipla","dificuldade":3,"enunciado":"Sobre os crimes praticados por particular contra a Administração em geral, assinale a alternativa correta.","alternativas":{"A":"A desobediência exige o emprego de violência ou ameaça contra o funcionário.","B":"O desacato só se configura se o funcionário estiver em seu local de trabalho.","C":"A corrupção ativa só se consuma se o funcionário aceitar a vantagem oferecida.","D":"O tráfico de influência pode ter por objeto vantagem para si ou para outrem, a pretexto de influir em ato de funcionário público no exercício da função.","E":"A resistência só pode ter como vítima o próprio funcionário que executa o ato."},"gabarito":"D","explicacao":"O art. 332 descreve solicitar, exigir, cobrar ou obter, para si ou para outrem, vantagem ou promessa de vantagem, a pretexto de influir em ato praticado por funcionário público no exercício da função.","explicacoes":{"A":"Violência ou ameaça caracterizam a resistência (art. 329), não a desobediência (art. 330).","B":"O desacato ocorre no exercício da função ou em razão dela (art. 331), mesmo fora do local de trabalho.","C":"Basta oferecer ou prometer a vantagem (art. 333).","D":"Correta: é a redação do art. 332.","E":"A resistência também protege quem presta auxílio ao funcionário (art. 329)."},"fonte":"Código Penal, arts. 329 a 333","mastigado":"A resposta é a letra D. No tráfico de influência a pessoa cobra ou consegue uma vantagem, para ela ou para outro, dizendo que vai influenciar um servidor. As outras frases trocam os elementos de cada crime.","teSitua":{"termos":[{"termo":"tráfico de influência","significado":"crime de quem cobra vantagem dizendo que pode influenciar um servidor."},{"termo":"a pretexto de influir","significado":"usando como desculpa a promessa de convencer ou pressionar alguém."},{"termo":"desacato","significado":"ofensa ou humilhação dirigida a servidor no exercício da função ou por causa dela."}],"exemplo":"Rômulo pede dinheiro a um candidato a motorista de aplicativo dizendo que conhece o servidor que libera a licença e que vai convencê-lo. Pede que o valor seja depositado na conta da esposa. Mesmo a vantagem indo para outra pessoa, Rômulo comete tráfico de influência."}},{"id":"aut.penal_tj.particular.0019","subtopico":"penal_tj.adm_publica.particular","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do Código Penal, o crime de tráfico de influência, em sua forma simples, é punido com","alternativas":{"A":"reclusão, de dois a cinco anos, e multa.","B":"reclusão, de dois a doze anos, e multa.","C":"reclusão, de um a cinco anos, e multa.","D":"detenção, de seis meses a dois anos, ou multa.","E":"reclusão, de três a oito anos, e multa."},"gabarito":"A","explicacao":"O art. 332 prevê reclusão, de 2 (dois) a 5 (cinco) anos, e multa, aumentada da metade se o agente alega ou insinua que a vantagem é também destinada ao funcionário.","explicacoes":{"A":"Correta: é a pena do caput do art. 332.","B":"É a pena da corrupção ativa e da corrupção passiva.","C":"É a pena da exploração de prestígio (art. 357).","D":"É a pena do desacato.","E":"É a pena do excesso de exação."},"fonte":"Código Penal, art. 332","mastigado":"A resposta é a letra A. Quem vende uma suposta influência sobre um servidor público pega de dois a cinco anos de reclusão, mais multa. A pena só aumenta se a pessoa disser que o servidor também vai receber parte.","teSitua":{"termos":[{"termo":"tráfico de influência","significado":"crime de quem cobra vantagem dizendo que pode influenciar um servidor."},{"termo":"reclusão","significado":"tipo mais grave de pena de prisão, que pode começar em regime fechado."}],"exemplo":"Celina cobra R$ 4.000,00 de um comerciante prometendo usar sua amizade com um servidor para liberar uma licença, sem dizer que ele ganharia algo. Condenada por tráfico de influência simples, recebe pena dentro do intervalo de dois a cinco anos de reclusão."}},{"id":"aut.penal_tj.particular.0020","subtopico":"penal_tj.adm_publica.particular","tipo":"certo_errado","dificuldade":3,"enunciado":"Comete corrupção ativa o particular que promete vantagem indevida a funcionário público para que ele omita ato de ofício, ainda que o funcionário recuse a promessa.","gabarito":"C","explicacao":"O art. 333 pune quem oferece ou promete vantagem indevida a funcionário público, para determiná-lo a praticar, omitir ou retardar ato de ofício. O tipo se realiza com a promessa, sem depender da aceitação do funcionário.","fonte":"Código Penal, art. 333, caput","mastigado":"Certo. O crime do particular está em oferecer ou prometer a vantagem. Se o servidor recusa, o particular já cometeu corrupção ativa, porque a lei pune a tentativa de comprar o servidor.","teSitua":{"termos":[{"termo":"promete vantagem indevida","significado":"se compromete a dar, no futuro, um benefício que não é devido."},{"termo":"omita ato de ofício","significado":"deixe de fazer algo que é dever do cargo."}],"exemplo":"Na fila do protocolo, Neusa diz ao escrevente Artur que lhe dará uma viagem se ele \\"perder\\" a petição da parte contrária. Artur recusa na hora. Neusa já cometeu corrupção ativa, porque prometeu a vantagem para que ele omitisse ato de ofício."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0001","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"multipla","dificuldade":2,"enunciado":"Uma escrevente, por antipatia pessoal a um advogado, deixa de juntar aos autos, durante semanas, as petições que ele protocola, sem receber vantagem e sem pedido de ninguém. Nos termos do Código Penal, a conduta configura","alternativas":{"A":"corrupção passiva privilegiada.","B":"prevaricação.","C":"condescendência criminosa.","D":"advocacia administrativa.","E":"abandono de função."},"gabarito":"B","explicacao":"O art. 319 pune quem retarda ou deixa de praticar, indevidamente, ato de ofício, ou o pratica contra disposição expressa de lei, para satisfazer interesse ou sentimento pessoal, com detenção de três meses a um ano, e multa. A antipatia pessoal é o sentimento pessoal que move a servidora.","explicacoes":{"A":"Na corrupção passiva privilegiada (art. 317, § 2º) o funcionário cede a pedido ou influência de outrem, o que não houve.","B":"Correta: retardar ato de ofício para satisfazer sentimento pessoal é prevaricação (art. 319).","C":"A condescendência criminosa é deixar, por indulgência, de responsabilizar subordinado.","D":"A advocacia administrativa é patrocinar interesse privado perante a Administração.","E":"Ela não abandonou o cargo; continuou trabalhando, mas retardou atos."},"fonte":"Código Penal, art. 319","mastigado":"A resposta é a letra B. A servidora atrasou de propósito o seu trabalho só porque não gosta do advogado. Ninguém pediu e ela não ganhou nada. Atrasar ou deixar de fazer o serviço para satisfazer um sentimento pessoal é prevaricação.","teSitua":{"termos":[{"termo":"juntar aos autos","significado":"colocar a petição ou o documento dentro do processo."},{"termo":"petições","significado":"pedidos escritos que os advogados fazem ao juiz."},{"termo":"prevaricação","significado":"crime do servidor que atrasa, deixa de fazer ou faz contra a lei um ato do cargo por interesse ou sentimento pessoal."},{"termo":"condescendência criminosa","significado":"crime do chefe que, por tolerância, deixa de punir subordinado que errou."}],"exemplo":"A escrevente Regina não suporta o advogado Hélio desde uma discussão no balcão. Por isso, guarda numa gaveta todas as petições dele, que ficam semanas sem ir ao processo. Regina não recebeu nada nem atendeu pedido de ninguém. Ela comete prevaricação."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0002","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"certo_errado","dificuldade":2,"enunciado":"Comete prevaricação o funcionário que, para satisfazer interesse ou sentimento pessoal, pratica ato de ofício contra disposição expressa de lei.","gabarito":"C","explicacao":"O art. 319 tem três condutas: retardar indevidamente ato de ofício, deixar de praticá-lo ou praticá-lo contra disposição expressa de lei, sempre para satisfazer interesse ou sentimento pessoal.","fonte":"Código Penal, art. 319","mastigado":"Certo. A prevaricação não é só atrasar ou deixar de fazer o serviço. Também comete o crime quem faz o ato do cargo contrariando o que a lei manda, para atender a um interesse ou sentimento próprio.","teSitua":{"termos":[{"termo":"ato de ofício","significado":"ato que o funcionário tem o dever de praticar por causa do cargo."},{"termo":"contra disposição expressa de lei","significado":"de forma contrária ao que a lei diz claramente."}],"exemplo":"O escrevente Murilo expede uma certidão de objeto e pé para o primo sem a cobrança das custas que a lei exige, só para agradá-lo. Ele praticou o ato de ofício contra disposição expressa de lei para satisfazer sentimento pessoal e comete prevaricação."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0003","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"multipla","dificuldade":3,"enunciado":"Assinale a alternativa que indica o elemento que diferencia a prevaricação (art. 319) da corrupção passiva privilegiada (art. 317, § 2º).","alternativas":{"A":"Na prevaricação o funcionário recebe vantagem indevida; na corrupção privilegiada, não.","B":"Na prevaricação a pena é de reclusão; na corrupção privilegiada, de detenção.","C":"A prevaricação só se configura por omissão; a corrupção privilegiada, só por ação.","D":"A prevaricação só pode ser praticada por funcionário em cargo de direção.","E":"Na prevaricação o funcionário age para satisfazer interesse ou sentimento pessoal; na corrupção privilegiada, cede a pedido ou influência de outrem."},"gabarito":"E","explicacao":"Os dois crimes envolvem retardar, deixar de praticar ou praticar ato de ofício com infração de dever. Na prevaricação, o motivo é satisfazer interesse ou sentimento pessoal (art. 319); na corrupção passiva privilegiada, o funcionário cede a pedido ou influência de outrem (art. 317, § 2º).","explicacoes":{"A":"Em nenhum dos dois há recebimento de vantagem indevida.","B":"Ambos são punidos com detenção.","C":"Os dois admitem ação (praticar) e omissão (deixar de praticar ou retardar).","D":"Qualquer funcionário público pode praticar prevaricação.","E":"Correta: o motivo pessoal marca a prevaricação; o pedido ou influência de terceiro, a corrupção privilegiada."},"fonte":"Código Penal, arts. 317, § 2º, e 319","mastigado":"A resposta é a letra E. Nos dois casos o servidor descumpre seu dever sem ganhar nada. A diferença está no motivo: se foi por vontade ou sentimento próprio, é prevaricação; se foi para atender ao pedido de alguém, é corrupção passiva na forma mais leve.","teSitua":{"termos":[{"termo":"corrupção passiva privilegiada","significado":"forma mais leve da corrupção, em que o servidor atende a pedido sem receber vantagem."},{"termo":"cede a pedido ou influência","significado":"atende ao pedido ou à pressão de outra pessoa."},{"termo":"cargo de direção","significado":"cargo de chefia, de quem comanda um setor."}],"exemplo":"O escrevente Ari atrasa um mandado porque odeia o réu: é prevaricação. Já sua colega Bia atrasa outro mandado porque um deputado ligou pedindo: é corrupção passiva privilegiada. Nenhum dos dois ganhou dinheiro, mas o motivo de cada um muda o crime."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0004","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"certo_errado","dificuldade":3,"enunciado":"Comete crime, punido com reclusão de dois a seis anos, o Diretor de Penitenciária ou agente público que deixa de cumprir seu dever de vedar ao preso o acesso a aparelho telefônico, de rádio ou similar que permita a comunicação com outros presos ou com o ambiente externo.","gabarito":"E","explicacao":"O art. 319-A do CP prevê, para essa conduta, pena de detenção, de 3 (três) meses a 1 (um) ano, e não reclusão de dois a seis anos.","fonte":"Código Penal, art. 319-A","mastigado":"Errado. A conduta é crime, mas a pena é bem menor: detenção de três meses a um ano. A pena de reclusão de dois a seis anos não é a prevista para esse caso.","teSitua":{"termos":[{"termo":"vedar","significado":"proibir, impedir que algo aconteça."},{"termo":"aparelho telefônico, de rádio ou similar","significado":"celular, rádio ou outro aparelho que permita conversar à distância."}],"exemplo":"O agente penitenciário Wilson vê um preso usando celular na cela e, para evitar confusão, finge que não viu e não recolhe o aparelho. Ele deixou de cumprir o dever de impedir o acesso do preso ao telefone e responde pelo crime com detenção de três meses a um ano."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0005","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"multipla","dificuldade":3,"enunciado":"O chefe de seção de um cartório judicial descobre que um escrevente subordinado desviou documentos e, por indulgência, deixa de responsabilizá-lo. Nos termos do Código Penal, o chefe comete","alternativas":{"A":"condescendência criminosa, punida com detenção de quinze dias a um mês, ou multa.","B":"prevaricação, punida com detenção de três meses a um ano, e multa.","C":"advocacia administrativa, punida com detenção de um a três meses, ou multa.","D":"corrupção passiva privilegiada, punida com detenção de três meses a um ano, ou multa.","E":"condescendência criminosa, punida com reclusão de um a quatro anos."},"gabarito":"A","explicacao":"O art. 320 pune o funcionário que deixa, por indulgência, de responsabilizar subordinado que cometeu infração no exercício do cargo ou, quando lhe falte competência, não leva o fato ao conhecimento da autoridade competente, com detenção de quinze dias a um mês, ou multa.","explicacoes":{"A":"Correta: é a condescendência criminosa do art. 320.","B":"O motivo do chefe é a indulgência para com o subordinado, figura específica do art. 320.","C":"O chefe não patrocinou interesse privado perante a Administração.","D":"Não houve pedido ou influência de terceiro para que deixasse de agir.","E":"A pena da condescendência criminosa é detenção de quinze dias a um mês, ou multa."},"fonte":"Código Penal, art. 320","mastigado":"A resposta é a letra A. O chefe soube da falta do subordinado e, por pena ou tolerância, deixou para lá. Isso é condescendência criminosa. A pena é leve: detenção de quinze dias a um mês, ou multa.","teSitua":{"termos":[{"termo":"indulgência","significado":"tolerância, vontade de perdoar ou de não punir."},{"termo":"responsabilizar","significado":"tomar providências para que a pessoa responda pela falta cometida."},{"termo":"condescendência criminosa","significado":"crime do chefe que, por tolerância, deixa de punir subordinado que errou."}],"exemplo":"Fernanda, chefe do cartório, descobre que o escrevente Davi sumiu com documentos de um processo. Como Davi está passando por problemas em casa, ela fica com pena e não abre apuração nem comunica a ninguém. Fernanda responde por condescendência criminosa."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0006","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"certo_errado","dificuldade":3,"enunciado":"Também comete condescendência criminosa o funcionário que, quando lhe falte competência para responsabilizar o subordinado infrator, não leva o fato ao conhecimento da autoridade competente.","gabarito":"C","explicacao":"O art. 320 tem duas condutas: deixar, por indulgência, de responsabilizar o subordinado que cometeu infração no exercício do cargo, ou, quando lhe falte competência, não levar o fato ao conhecimento da autoridade competente.","fonte":"Código Penal, art. 320","mastigado":"Certo. Se o chefe não tem poder para punir o subordinado, ele deve avisar quem tem. Se, por tolerância, deixa de avisar, comete o mesmo crime de quem podia punir e não puniu.","teSitua":{"termos":[{"termo":"falte competência","significado":"não tenha o poder legal de tomar aquela providência."},{"termo":"autoridade competente","significado":"quem tem, por lei, o poder de decidir ou punir naquele caso."}],"exemplo":"O coordenador Paulo não pode abrir processo disciplinar, função que é do juiz corregedor. Ao saber que uma subordinada cobrou dinheiro de partes, ele fica com dó e não conta nada ao juiz. Paulo comete condescendência criminosa por não levar o fato à autoridade competente."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0007","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"multipla","dificuldade":3,"enunciado":"Um escrevente do TJSP, valendo-se da qualidade de funcionário, procura servidores da prefeitura para acelerar o pedido de alvará de construção de seu cunhado, que é legítimo. Nos termos do Código Penal, ele comete","alternativas":{"A":"tráfico de influência, punido com reclusão de dois a cinco anos, e multa.","B":"corrupção ativa, punida com reclusão de dois a doze anos, e multa.","C":"prevaricação, punida com detenção de três meses a um ano, e multa.","D":"advocacia administrativa, punida com detenção de um a três meses, ou multa.","E":"advocacia administrativa, punida com detenção de três meses a um ano, além da multa."},"gabarito":"D","explicacao":"O art. 321 pune quem patrocina, direta ou indiretamente, interesse privado perante a administração pública, valendo-se da qualidade de funcionário, com detenção de um a três meses, ou multa. Só se o interesse é ilegítimo a pena passa a ser de detenção de três meses a um ano, além da multa (parágrafo único).","explicacoes":{"A":"O tráfico de influência (art. 332) envolve pedir ou obter vantagem a pretexto de influir em ato de funcionário.","B":"Ele não ofereceu vantagem a funcionário.","C":"Ele não retardou ou deixou de praticar ato de ofício seu.","D":"Correta: é a advocacia administrativa na forma simples, pois o interesse é legítimo.","E":"Essa é a pena do parágrafo único, para interesse ilegítimo."},"fonte":"Código Penal, art. 321, caput e parágrafo único","mastigado":"A resposta é a letra D. O escrevente usou sua condição de servidor para defender, na prefeitura, um interesse particular do cunhado. Isso é advocacia administrativa. Como o pedido era legítimo, aplica-se a pena mais leve: detenção de um a três meses, ou multa.","teSitua":{"termos":[{"termo":"valendo-se da qualidade de funcionário","significado":"usando o fato de ser servidor público para conseguir algo."},{"termo":"alvará de construção","significado":"autorização da prefeitura para fazer uma obra."},{"termo":"legítimo","significado":"permitido pela lei e de acordo com o direito."}],"exemplo":"Ronaldo, escrevente do fórum, vai à prefeitura com o crachá do tribunal e pede aos colegas de lá que passem na frente o alvará da obra do cunhado. O pedido do cunhado está todo correto. Mesmo assim, Ronaldo comete advocacia administrativa, na forma simples."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0008","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"certo_errado","dificuldade":3,"enunciado":"Se o interesse privado patrocinado pelo funcionário perante a Administração Pública for legítimo, não há crime de advocacia administrativa.","gabarito":"E","explicacao":"O art. 321, caput, pune o patrocínio de interesse privado perante a administração pública, valendo-se da qualidade de funcionário, sem exigir que o interesse seja ilegítimo. O parágrafo único apenas aumenta a pena quando o interesse é ilegítimo.","fonte":"Código Penal, art. 321, caput e parágrafo único","mastigado":"Errado. O crime existe mesmo que o pedido defendido seja correto. O que a lei pune é o servidor usar o cargo para defender interesse particular. Se o interesse for ilegítimo, a pena só fica maior.","teSitua":{"termos":[{"termo":"patrocinado","significado":"defendido por alguém em favor de outra pessoa."},{"termo":"advocacia administrativa","significado":"crime do servidor que usa o cargo para defender interesse particular perante a Administração."}],"exemplo":"A escrevente Joana usa seu cargo para pedir ao setor de compras do tribunal que pague logo a nota de uma empresa do irmão, que tem direito ao pagamento. Mesmo sendo justo o pagamento, ela comete advocacia administrativa."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0009","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"multipla","dificuldade":2,"enunciado":"O funcionário público que pratica violência no exercício de função ou a pretexto de exercê-la comete violência arbitrária, punida com","alternativas":{"A":"detenção, de quinze dias a um mês, ou multa.","B":"reclusão, de um a quatro anos, e multa, absorvida a pena da violência.","C":"detenção, de seis meses a três anos, além da pena correspondente à violência.","D":"detenção, de três meses a um ano, ou multa.","E":"reclusão, de dois a doze anos, e multa."},"gabarito":"C","explicacao":"O art. 322 pune quem pratica violência, no exercício de função ou a pretexto de exercê-la, com detenção de seis meses a três anos, além da pena correspondente à violência.","explicacoes":{"A":"Essa é a pena da condescendência criminosa e do abandono de função simples.","B":"A pena é de detenção e se soma à da violência, que não é absorvida.","C":"Correta: detenção de seis meses a três anos, além da pena correspondente à violência.","D":"Essa pena não corresponde ao art. 322.","E":"Dois a doze anos é a pena de crimes como peculato e corrupção."},"fonte":"Código Penal, art. 322","mastigado":"A resposta é a letra C. O servidor que agride alguém usando o cargo como desculpa responde pela violência arbitrária, com detenção de seis meses a três anos, e ainda responde pela agressão em si. As duas penas se somam.","teSitua":{"termos":[{"termo":"a pretexto de exercê-la","significado":"usando a função como desculpa para o que faz."},{"termo":"violência arbitrária","significado":"agressão praticada pelo servidor sem base legal, usando a função."}],"exemplo":"Durante o cumprimento de uma ordem, o funcionário Haroldo empurra e machuca o morador Ênio, que apenas perguntava o motivo da diligência. Haroldo responde por violência arbitrária e também pela lesão corporal que causou, com as penas somadas."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0010","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"certo_errado","dificuldade":3,"enunciado":"No crime de abandono de função, se o fato ocorre em lugar compreendido na faixa de fronteira, a pena é a mesma do abandono simples, de quinze dias a um mês de detenção, ou multa.","gabarito":"E","explicacao":"O art. 323, § 2º, do CP prevê pena própria, mais grave, para o abandono em faixa de fronteira: detenção, de um a três anos, e multa. A pena de quinze dias a um mês, ou multa, é a do abandono simples (caput).","fonte":"Código Penal, art. 323, § 2º","mastigado":"Errado. Abandonar o cargo numa região de fronteira é tratado com mais rigor. A pena sobe para um a três anos de detenção, e multa, e não fica igual à do abandono comum.","teSitua":{"termos":[{"termo":"abandono de função","significado":"deixar o cargo público sem autorização, fora dos casos da lei."},{"termo":"faixa de fronteira","significado":"área do território brasileiro próxima à divisa com outros países."}],"exemplo":"Um servidor federal lotado em posto de uma cidade na divisa com o Paraguai simplesmente para de ir ao trabalho e some, sem pedir licença nem exoneração. Como o abandono ocorreu em faixa de fronteira, a pena é de um a três anos de detenção, e multa."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0011","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do Código Penal, se do abandono de cargo público resulta prejuízo público, a pena é de","alternativas":{"A":"detenção, de quinze dias a um mês, ou multa.","B":"detenção, de três meses a um ano, e multa.","C":"detenção, de um a três anos, e multa.","D":"reclusão, de dois a seis anos, e multa.","E":"detenção, de seis meses a dois anos, ou multa."},"gabarito":"B","explicacao":"O art. 323 prevê três patamares: abandono simples, detenção de quinze dias a um mês, ou multa (caput); se resulta prejuízo público, detenção de três meses a um ano, e multa (§ 1º); se ocorre em faixa de fronteira, detenção de um a três anos, e multa (§ 2º).","explicacoes":{"A":"É a pena do abandono simples (caput).","B":"Correta: é a pena do § 1º, quando resulta prejuízo público.","C":"É a pena do abandono em faixa de fronteira (§ 2º).","D":"Essa pena não está no art. 323.","E":"É a pena da violação de sigilo funcional (art. 325)."},"fonte":"Código Penal, art. 323, caput e §§ 1º e 2º","mastigado":"A resposta é a letra B. Abandonar o cargo já é crime com pena pequena. Se o abandono causa prejuízo ao serviço público, a pena aumenta para três meses a um ano de detenção, e multa.","teSitua":{"termos":[{"termo":"prejuízo público","significado":"dano causado ao serviço ou ao patrimônio do poder público."},{"termo":"cargo público","significado":"posto criado por lei na Administração, ocupado por servidor."}],"exemplo":"O único escrevente de uma vara de comarca pequena abandona o cargo sem aviso, e as audiências da semana precisam ser canceladas por falta de quem as registre. Como o abandono causou prejuízo público, a pena é de três meses a um ano de detenção, e multa."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0012","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"multipla","dificuldade":3,"enunciado":"Um escrevente, depois de ser comunicado oficialmente de sua suspensão, continua a ir ao cartório e a praticar atos do cargo, sem autorização. Nos termos do Código Penal, a conduta configura","alternativas":{"A":"usurpação de função pública.","B":"abandono de função.","C":"prevaricação.","D":"desobediência.","E":"exercício funcional ilegalmente prolongado."},"gabarito":"E","explicacao":"O art. 324 pune quem entra no exercício de função pública antes de satisfeitas as exigências legais, ou continua a exercê-la, sem autorização, depois de saber oficialmente que foi exonerado, removido, substituído ou suspenso, com detenção de quinze dias a um mês, ou multa.","explicacoes":{"A":"A usurpação (art. 328) é crime de particular que nunca teve a função; aqui é o próprio servidor que a prolonga indevidamente.","B":"Ele não abandonou o cargo; ao contrário, continuou nele.","C":"A prevaricação é retardar ou deixar de praticar ato por interesse pessoal.","D":"Há tipo específico para o servidor que continua no exercício depois de suspenso (art. 324).","E":"Correta: continuar a exercer a função após saber oficialmente da suspensão é o art. 324."},"fonte":"Código Penal, art. 324","mastigado":"A resposta é a letra E. O servidor foi avisado oficialmente de que estava suspenso, mas continuou trabalhando como se nada tivesse acontecido. A lei chama isso de exercício da função ilegalmente prolongado.","teSitua":{"termos":[{"termo":"comunicado oficialmente","significado":"avisado por documento ou ato formal da Administração."},{"termo":"usurpação de função pública","significado":"crime de quem, sem ser servidor, exerce função pública como se fosse."},{"termo":"exercício funcional ilegalmente prolongado","significado":"continuar exercendo a função depois de perder o direito a ela."}],"exemplo":"Lúcia recebe ofício avisando que está suspensa por 30 dias. No dia seguinte, volta ao cartório, entra no sistema e assina certidões como se nada tivesse acontecido. Ela responde por exercício funcional ilegalmente prolongado."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0013","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"certo_errado","dificuldade":3,"enunciado":"Comete crime o aprovado em concurso que entra no exercício de função pública antes de satisfeitas as exigências legais.","gabarito":"C","explicacao":"O art. 324 pune quem entra no exercício de função pública antes de satisfeitas as exigências legais (exercício funcional ilegalmente antecipado), com detenção de quinze dias a um mês, ou multa.","fonte":"Código Penal, art. 324","mastigado":"Certo. Quem começa a trabalhar no cargo antes de cumprir o que a lei exige, como tomar posse, comete crime. A lei pune tanto quem começa cedo demais quanto quem fica depois de afastado.","teSitua":{"termos":[{"termo":"exigências legais","significado":"requisitos que a lei impõe, como a posse e a apresentação de documentos."},{"termo":"entra no exercício","significado":"começa a desempenhar efetivamente as tarefas do cargo."}],"exemplo":"Sérgio passou no concurso de escrevente, mas ainda não tomou posse nem entregou os exames médicos. Ansioso, vai ao cartório e começa a atender partes e a lançar andamentos no sistema. Ele comete o crime de exercício funcional ilegalmente antecipado."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0014","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"multipla","dificuldade":2,"enunciado":"Uma escrevente conta a uma amiga detalhes de um processo de família que tramita em segredo de justiça e dos quais teve ciência em razão do cargo. Se o fato não constituir crime mais grave, ela responde por","alternativas":{"A":"violação de sigilo funcional, com detenção de seis meses a dois anos, ou multa.","B":"violação de sigilo funcional, com reclusão de dois a seis anos, e multa.","C":"prevaricação, com detenção de três meses a um ano, e multa.","D":"fraude em certame de interesse público, com reclusão de um a quatro anos, e multa.","E":"advocacia administrativa, com detenção de um a três meses, ou multa."},"gabarito":"A","explicacao":"O art. 325 pune quem revela fato de que tem ciência em razão do cargo e que deva permanecer em segredo, ou facilita-lhe a revelação, com detenção de seis meses a dois anos, ou multa, se o fato não constitui crime mais grave. A reclusão de dois a seis anos é para quando resulta dano à Administração ou a outrem (§ 2º).","explicacoes":{"A":"Correta: é a violação de sigilo funcional na forma simples.","B":"Essa é a pena da forma qualificada, quando resulta dano (§ 2º), o que o enunciado não menciona.","C":"Ela não retardou nem deixou de praticar ato de ofício.","D":"Não se trata de conteúdo de concurso ou exame.","E":"Ela não patrocinou interesse privado perante a Administração."},"fonte":"Código Penal, art. 325, caput e § 2º","mastigado":"A resposta é a letra A. A servidora soube de segredos do processo por causa do trabalho e contou a uma amiga. Isso é violação de sigilo funcional. Sem dano comprovado, a pena é de seis meses a dois anos de detenção, ou multa.","teSitua":{"termos":[{"termo":"segredo de justiça","significado":"regra que limita o acesso ao processo às partes e aos advogados, para proteger a intimidade."},{"termo":"teve ciência em razão do cargo","significado":"ficou sabendo por causa do trabalho que exerce."},{"termo":"sigilo funcional","significado":"dever do servidor de guardar segredo do que sabe pelo cargo."}],"exemplo":"Patrícia, escrevente da Vara de Família, conta no almoço com a amiga Selma os motivos do divórcio de um casal conhecido da cidade, que leu no processo sigiloso. Ela responde por violação de sigilo funcional."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0015","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"certo_errado","dificuldade":2,"enunciado":"Incorre nas penas da violação de sigilo funcional o servidor que permite ou facilita, mediante empréstimo de sua senha, o acesso de pessoa não autorizada a sistema de informações da Administração Pública.","gabarito":"C","explicacao":"O art. 325, § 1º, I, prevê que incorre nas mesmas penas quem permite ou facilita, mediante atribuição, fornecimento e empréstimo de senha ou qualquer outra forma, o acesso de pessoas não autorizadas a sistemas de informações ou banco de dados da Administração Pública.","fonte":"Código Penal, art. 325, § 1º, I","mastigado":"Certo. Emprestar a senha do sistema do trabalho para alguém que não tem autorização é tratado pela lei do mesmo jeito que contar um segredo do cargo. O servidor responde pelas mesmas penas.","teSitua":{"termos":[{"termo":"sistema de informações","significado":"programa de computador em que o órgão guarda e consulta seus dados."},{"termo":"pessoa não autorizada","significado":"quem não tem permissão para entrar no sistema."}],"exemplo":"O escrevente Douglas empresta sua senha do sistema processual ao primo, que é despachante e quer consultar processos sigilosos de clientes. Douglas responde pelas penas da violação de sigilo funcional, por facilitar o acesso de pessoa não autorizada."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0016","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"multipla","dificuldade":3,"enunciado":"No crime de violação de sigilo funcional, se da ação ou omissão resulta dano à Administração Pública ou a outrem, a pena é de","alternativas":{"A":"detenção, de seis meses a dois anos, ou multa, aumentada de um terço.","B":"detenção, de três meses a um ano, e multa.","C":"reclusão, de um a quatro anos, e multa.","D":"reclusão, de dois a seis anos, e multa.","E":"reclusão, de dois a doze anos, e multa."},"gabarito":"D","explicacao":"O art. 325, § 2º, dispõe que, se da ação ou omissão resulta dano à Administração Pública ou a outrem, a pena é de reclusão, de 2 (dois) a 6 (seis) anos, e multa.","explicacoes":{"A":"A lei não prevê aumento de um terço; prevê pena própria para o resultado danoso.","B":"Essa pena não corresponde à forma qualificada do art. 325.","C":"Um a quatro anos é a pena simples da fraude em certames (art. 311-A).","D":"Correta: é a forma qualificada do § 2º do art. 325.","E":"Dois a doze anos é a pena de crimes como peculato e corrupção."},"fonte":"Código Penal, art. 325, § 2º","mastigado":"A resposta é a letra D. Se o segredo revelado pelo servidor causa prejuízo à Administração ou a outra pessoa, a punição fica bem maior: passa a ser de dois a seis anos de reclusão, e multa.","teSitua":{"termos":[{"termo":"dano","significado":"prejuízo, estrago causado a alguém ou ao poder público."},{"termo":"ação ou omissão","significado":"fazer algo ou deixar de fazer o que devia."}],"exemplo":"A escrevente Vânia revela a um empresário a data de uma ordem de bloqueio de contas que ainda era sigilosa. O empresário esvazia as contas antes do bloqueio e o credor fica sem receber. Como houve dano a outrem, Vânia responde pela forma qualificada, com reclusão de dois a seis anos."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0017","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"certo_errado","dificuldade":2,"enunciado":"Para os efeitos penais, considera-se funcionário público quem, embora transitoriamente ou sem remuneração, exerce cargo, emprego ou função pública.","gabarito":"C","explicacao":"É a redação do art. 327, caput, do Código Penal, que adota conceito amplo de funcionário público para os efeitos penais.","fonte":"Código Penal, art. 327, caput","mastigado":"Certo. Para a lei penal, é funcionário público quem exerce cargo, emprego ou função pública, mesmo que por pouco tempo ou de graça. Um mesário de eleição ou um jurado, por exemplo, entram nesse conceito.","teSitua":{"termos":[{"termo":"transitoriamente","significado":"por um tempo curto, de forma passageira."},{"termo":"sem remuneração","significado":"sem receber salário ou pagamento."},{"termo":"cargo, emprego ou função pública","significado":"diferentes formas de trabalhar para o poder público."}],"exemplo":"Lara é convocada como mesária nas eleições e trabalha um único domingo, sem salário. Durante a votação, ela pede dinheiro a um eleitor para deixá-lo votar sem documento. Para a lei penal, Lara é funcionária pública e pode responder por crime contra a Administração."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0018","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 327 do Código Penal, é correto afirmar que","alternativas":{"A":"equipara-se a funcionário público quem trabalha para empresa prestadora de serviço contratada ou conveniada para a execução de atividade típica da Administração Pública.","B":"só é funcionário público, para os efeitos penais, o servidor ocupante de cargo efetivo.","C":"o empregado de entidade paraestatal não pode ser equiparado a funcionário público.","D":"quem exerce função pública sem remuneração não é considerado funcionário público.","E":"o exercício transitório de função pública afasta a condição de funcionário público."},"gabarito":"A","explicacao":"O art. 327, caput, considera funcionário público quem, embora transitoriamente ou sem remuneração, exerce cargo, emprego ou função pública. O § 1º equipara a funcionário público quem exerce cargo, emprego ou função em entidade paraestatal e quem trabalha para empresa prestadora de serviço contratada ou conveniada para a execução de atividade típica da Administração Pública.","explicacoes":{"A":"Correta: é a segunda equiparação do § 1º do art. 327.","B":"O conceito penal abrange cargo, emprego ou função, e não só o cargo efetivo.","C":"O § 1º equipara expressamente quem exerce cargo, emprego ou função em entidade paraestatal.","D":"O caput diz que a falta de remuneração não afasta a condição de funcionário público.","E":"O caput diz que o exercício transitório não afasta a condição de funcionário público."},"fonte":"Código Penal, art. 327, caput e § 1º","mastigado":"A resposta é a letra A. A lei penal amplia muito a ideia de funcionário público. Até o empregado de empresa contratada para fazer um serviço típico do Estado é tratado como funcionário, e quem trabalha por pouco tempo ou sem salário também.","teSitua":{"termos":[{"termo":"equipara-se","significado":"passa a ser tratado como igual para aquele efeito."},{"termo":"entidade paraestatal","significado":"entidade que atua ao lado do Estado em atividades de interesse público."},{"termo":"atividade típica da Administração Pública","significado":"serviço próprio do poder público, que ele normalmente presta."},{"termo":"conveniada","significado":"ligada ao poder público por um convênio, um acordo de cooperação."}],"exemplo":"Cristiano é empregado de uma empresa contratada pelo Estado para administrar um posto de atendimento ao público. Ele desvia taxas pagas pelos usuários. Embora não seja servidor concursado, a lei penal o equipara a funcionário público, e ele pode responder por peculato."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0019","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"multipla","dificuldade":4,"enunciado":"De acordo com o art. 327, § 2º, do Código Penal, a pena dos crimes praticados por funcionário público contra a Administração em geral será aumentada da terça parte quando o autor for","alternativas":{"A":"servidor efetivo com mais de dez anos de exercício.","B":"ocupante de cargo em comissão ou de função de direção ou assessoramento de órgão da administração direta, sociedade de economia mista, empresa pública ou fundação instituída pelo poder público.","C":"funcionário que pratica o crime em faixa de fronteira.","D":"empregado de empresa prestadora de serviço contratada para atividade típica da Administração.","E":"ocupante de qualquer cargo, desde que remunerado."},"gabarito":"B","explicacao":"O art. 327, § 2º, aumenta a pena da terça parte quando os autores dos crimes do capítulo forem ocupantes de cargos em comissão ou de função de direção ou assessoramento de órgão da administração direta, sociedade de economia mista, empresa pública ou fundação instituída pelo poder público.","explicacoes":{"A":"O tempo de serviço não é causa de aumento prevista no art. 327.","B":"Correta: é a hipótese do § 2º do art. 327.","C":"A faixa de fronteira só agrava o abandono de função (art. 323, § 2º).","D":"Esse é um caso de equiparação a funcionário público (§ 1º), não de aumento de pena.","E":"A remuneração não é critério de aumento; o § 2º exige cargo em comissão ou função de direção ou assessoramento."},"fonte":"Código Penal, art. 327, § 2º","mastigado":"A resposta é a letra B. Quem ocupa cargo de confiança, de chefia ou de assessoria no poder público tem mais responsabilidade. Por isso, quando comete crime contra a Administração, a lei aumenta a pena em um terço.","teSitua":{"termos":[{"termo":"cargo em comissão","significado":"cargo de confiança, de livre nomeação e exoneração, sem concurso."},{"termo":"função de direção ou assessoramento","significado":"função de chefia ou de apoio direto a quem chefia."},{"termo":"sociedade de economia mista","significado":"empresa com capital público e privado, controlada pelo Estado."},{"termo":"empresa pública","significado":"empresa criada pelo Estado com capital todo público."}],"exemplo":"Ivo é diretor de departamento, nomeado em cargo em comissão numa secretaria estadual. Ele exige propina de um fornecedor para liberar pagamento. Condenado por concussão, tem a pena aumentada de um terço por ocupar cargo em comissão de direção."}},{"id":"aut.penal_tj.prevaricacao_sigilo.0020","subtopico":"penal_tj.adm_publica.prevaricacao_sigilo","tipo":"certo_errado","dificuldade":4,"enunciado":"Para os efeitos penais, equipara-se a funcionário público quem trabalha para empresa prestadora de serviço contratada pela Administração para a execução de qualquer atividade, ainda que não seja típica da Administração Pública.","gabarito":"E","explicacao":"O art. 327, § 1º, equipara a funcionário público quem trabalha para empresa prestadora de serviço contratada ou conveniada para a execução de atividade típica da Administração Pública. A atividade precisa ser típica da Administração.","fonte":"Código Penal, art. 327, § 1º","mastigado":"Errado. A lei só trata como funcionário público o empregado de empresa contratada quando o serviço for próprio do Estado. Quem só presta um serviço comum, que não é típico do poder público, não entra nessa equiparação.","teSitua":{"termos":[{"termo":"empresa prestadora de serviço","significado":"empresa contratada para executar um trabalho para outra pessoa ou órgão."},{"termo":"típica da Administração Pública","significado":"própria do poder público, que ele normalmente presta à população."}],"exemplo":"Gael é empregado da empresa que fornece café para as reuniões de uma secretaria. Ele não executa atividade típica da Administração, então não é equiparado a funcionário público. Já Lia, da empresa contratada para atender o público no posto de emissão de documentos, é equiparada."}}]`);export{e as default};